function createCloudAssemblyFrames(sheet) {
  const sampleCanvas = document.createElement("canvas");
  sampleCanvas.width = CLOUD_SPRITE_SHEET_WIDTH;
  sampleCanvas.height = CLOUD_SPRITE_SHEET_HEIGHT;
  const sampleCtx = sampleCanvas.getContext("2d", { willReadFrequently: true });
  if (!sampleCtx) throw new Error("Could not create cloud assembly sample canvas");
  sampleCtx.imageSmoothingEnabled = false;
  sampleCtx.drawImage(sheet, 0, 0);
  const source = sampleCtx.getImageData(
    0,
    0,
    CLOUD_SPRITE_SHEET_WIDTH,
    CLOUD_SPRITE_SHEET_HEIGHT
  ).data;

  return Object.freeze(Array.from({ length: CLOUD_SPRITE_VARIANT_COUNT }, (_, frameIndex) => {
    return Object.freeze(Array.from({ length: CLOUD_ASSEMBLY_STAGE_COUNT }, (_, stageIndex) => {
      const visibility = (stageIndex + 1) / CLOUD_ASSEMBLY_STAGE_COUNT;
      const canvas = document.createElement("canvas");
      canvas.width = CLOUD_SPRITE_FRAME_SIZE;
      canvas.height = CLOUD_SPRITE_FRAME_SIZE;
      const frameCtx = canvas.getContext("2d");
      if (!frameCtx) throw new Error(`Could not create cloud assembly frame ${frameIndex}:${stageIndex}`);
      frameCtx.imageSmoothingEnabled = false;
      const output = frameCtx.createImageData(CLOUD_SPRITE_FRAME_SIZE, CLOUD_SPRITE_FRAME_SIZE);
      for (let y = 0; y < CLOUD_SPRITE_FRAME_SIZE; y++) {
        for (let x = 0; x < CLOUD_SPRITE_FRAME_SIZE; x++) {
          const sourceIndex = (
            frameIndex * CLOUD_SPRITE_FRAME_SIZE +
            x +
            y * CLOUD_SPRITE_SHEET_WIDTH
          ) * 4;
          const sourceAlpha = source[sourceIndex + 3];
          if (sourceAlpha === 0) continue;
          const particle = cloudParticleAssembly(frameIndex, x, y, visibility);
          if (!particle.visible) continue;
          const outputIndex = (particle.x + particle.y * CLOUD_SPRITE_FRAME_SIZE) * 4;
          const alpha = Math.round(sourceAlpha * particle.alpha);
          if (alpha <= output.data[outputIndex + 3]) continue;
          output.data[outputIndex] = source[sourceIndex];
          output.data[outputIndex + 1] = source[sourceIndex + 1];
          output.data[outputIndex + 2] = source[sourceIndex + 2];
          output.data[outputIndex + 3] = alpha;
        }
      }
      frameCtx.putImageData(output, 0, 0);
      return canvas;
    }));
  }));
}

function loadImage(key) {
  return loadAssetImage(
    `assets/terrain/${TERRAIN_VARIANT}/${key}.png?v=${TERRAIN_ASSET_VERSION}`,
    `${TERRAIN_VARIANT} terrain image: ${key}`
  ).then((image) => [key, image]);
}

function loadVehicleImage(key) {
  return loadAssetImage(`assets/vehicles/${key}.png?v=${VEHICLE_ASSET_VERSION}`, `vehicle image: ${key}`);
}

async function loadShipSpriteAsset(spriteKey, label, slug) {
  if (!shipRenderLayerAssetStore) {
    throw new Error("Ship render-layer asset store is not initialized");
  }
  const [image, sinkDepthImage, renderLayers] = await Promise.all([
    loadVehicleImage(spriteKey),
    loadVehicleImage(`${spriteKey}-sink-depth`),
    shipRenderLayerAssetStore.request(slug)
  ]);
  validateShipSpriteSheet(image, `${label} image`);
  validateShipSpriteSheet(sinkDepthImage, `${label} sink-depth image`);
  attachShipRenderLayers(image, slug, spriteKey, renderLayers);
  return Object.freeze({ image, sinkDepthImage });
}

const WORLD_ANIMATION_ASSET = Object.freeze({
  SEAGULLS: "seagulls",
  FISHING_NET: "fishing-net",
  STORM_STRIKE: "storm-strike",
  FIRE: "fire"
});

function initializeWorldAssetStores() {
  if (shipSpriteAssetStore || shipLightingAssetStore || shipRenderLayerAssetStore ||
      rowingShipAssetStore ||
      whaleAssetStore || icebergAssetStore || landVehicleAssetStore || worldAnimationAssetStore) {
    throw new Error("World asset stores are already initialized");
  }
  shipSpriteAssetStore = createOnDemandAssetStore({
    label: "ship sprite",
    load: loadShipSpriteAssetsForSlug
  });
  shipLightingAssetStore = createOnDemandAssetStore({
    label: "ship lighting",
    load: loadShipLightingForSlug
  });
  shipRenderLayerAssetStore = createOnDemandAssetStore({
    label: "ship-render-layers",
    load: loadShipRenderLayersForSlug
  });
  rowingShipAssetStore = createOnDemandAssetStore({
    label: "rowing animation",
    load: loadRowingShipAssetsForSlug
  });
  whaleAssetStore = createOnDemandAssetStore({
    label: "whale sprite",
    load: loadWhaleAssetsForSlug
  });
  icebergAssetStore = createOnDemandAssetStore({
    label: "iceberg sprite",
    load: loadIcebergAssetsForSlug
  });
  landVehicleAssetStore = createOnDemandAssetStore({
    label: "horse-cart animation",
    load: loadLandVehicleAssets
  });
  worldAnimationAssetStore = createOnDemandAssetStore({
    label: "world animation",
    load: loadWorldAnimationAsset
  });
}

async function loadWorldAnimationAsset(key) {
  if (key === WORLD_ANIMATION_ASSET.SEAGULLS) {
    const [flight, standing] = await Promise.all([
      loadAssetImage(`${SEAGULL_FLIGHT_URL}?v=${ANIMAL_ASSET_VERSION}`, "seagull flight sheet"),
      loadAssetImage(`${SEAGULL_STANDING_URL}?v=${ANIMAL_ASSET_VERSION}`, "standing seagull image")
    ]);
    validateImageDimensions(
      flight,
      "seagull flight sheet",
      SEAGULL_FRAME_SIZE * SEAGULL_FLIGHT_FRAMES,
      SEAGULL_FRAME_SIZE
    );
    validateImageDimensions(
      standing,
      "standing seagull image",
      SEAGULL_FRAME_SIZE,
      SEAGULL_FRAME_SIZE
    );
    return Object.freeze({ flight, standing });
  }
  if (key === WORLD_ANIMATION_ASSET.FISHING_NET) {
    const image = await loadAssetImage(
      `${FISHING_NET_SHEET_URL}?v=${ANIMAL_ASSET_VERSION}`,
      "fishing net sheet"
    );
    validateImageDimensions(
      image,
      "fishing net sheet",
      FISHING_NET_FRAME_SIZE * FISHING_NET_FRAME_COUNT,
      FISHING_NET_FRAME_SIZE
    );
    return image;
  }
  if (key === WORLD_ANIMATION_ASSET.STORM_STRIKE) return loadStormShipStrikeImage();
  if (key === WORLD_ANIMATION_ASSET.FIRE) return loadFireEffectImage();
  throw new Error(`Unknown world animation asset key: ${key}`);
}

async function loadShipSpriteAssetsForSlug(slug) {
  shipStatsForSlug(slug);
  const key = `${vehicleSpriteKeyForShipSlug(slug)}-${SHIP_SPRITE_HEADING_SUFFIX}`;
  return loadShipSpriteAsset(key, `Ship: ${slug}`, slug);
}

async function loadShipLightingForSlug(slug) {
  shipStatsForSlug(slug);
  return loadShipLightingBake(vehicleSpriteKeyForShipSlug(slug));
}

async function loadShipRenderLayersForSlug(slug) {
  shipStatsForSlug(slug);
  const entry = shipRenderLayerManifest?.ships?.[slug];
  if (!entry) throw new Error(`Ship render-layer manifest is missing: ${slug}`);
  const bundle = await loadShipRenderLayerBundle(entry.bundle);
  const end = entry.byteOffset + entry.byteLength;
  if (end > bundle.byteLength) {
    throw new Error(`Ship render-layer payload exceeds its bundle: ${slug}`);
  }
  const payload = bundle.slice(entry.byteOffset, end);
  const image = await loadBundledPngImage(payload, `ship render-layer atlas: ${slug}`);
  validateImageDimensions(image, `Ship render-layer atlas: ${slug}`, entry.width, entry.height);
  return Object.freeze({ image, entry });
}

function loadShipRenderLayerBundle(bundleName) {
  const metadata = shipRenderLayerManifest?.bundles?.[bundleName];
  if (!metadata) throw new Error(`Unknown ship render-layer bundle: ${bundleName}`);
  let promise = shipRenderLayerBundlePromises.get(bundleName);
  if (!promise) {
    const label = bundleName;
    promise = fetchStaticAsset(
      `assets/vehicles/ship-render-layers/${bundleName}`,
      { label }
    ).then(async (response) => {
      if (!response.ok) throw new Error(`Failed to load ${label}: HTTP ${response.status}`);
      const buffer = await response.arrayBuffer();
      if (buffer.byteLength !== metadata.byteLength) {
        throw new Error(
          `Ship render-layer bundle ${bundleName} is ${buffer.byteLength} bytes; ` +
          `expected ${metadata.byteLength}`
        );
      }
      return buffer;
    });
    shipRenderLayerBundlePromises.set(bundleName, promise);
  }
  return promise;
}

async function loadBundledPngImage(buffer, label) {
  const url = URL.createObjectURL(new Blob([buffer], { type: "image/png" }));
  try {
    return await loadAssetImage(url, label);
  } finally {
    URL.revokeObjectURL(url);
  }
}

async function loadRowingShipAssetsForSlug(slug) {
  shipStatsForSlug(slug);
  const spec = ROWING_SHIP_ANIMATION_SPECS.get(slug);
  if (!spec) throw new Error(`Ship has no rowing animation specification: ${slug}`);
  const loadMode = async (modeStem) => {
    if (BUILD_EDITION_ID === "demo") {
      return loadDemoRowingShipAtlas(slug, spec.frames, modeStem);
    }
    const frames = [];
    for (let frameIndex = 0; frameIndex < spec.frames; frameIndex++) {
      const key = `${vehicleSpriteKeyForShipSlug(slug)}-${modeStem}-${frameIndex}-` +
        SHIP_SPRITE_HEADING_SUFFIX;
      frames.push(await loadShipSpriteAsset(
        key,
        `${modeStem} ship: ${slug} frame ${frameIndex}`,
        slug
      ));
    }
    return Object.freeze(frames);
  };
  const [ahead, pivotPort, pivotStarboard] = await Promise.all([
    loadMode("rowing"),
    loadMode("pivot-port"),
    loadMode("pivot-starboard")
  ]);
  return Object.freeze({
    ahead: Object.freeze(ahead),
    pivotPort: Object.freeze(pivotPort),
    pivotStarboard: Object.freeze(pivotStarboard)
  });
}

async function loadDemoRowingShipAtlas(slug, frameCount, modeStem) {
  const key = `${vehicleSpriteKeyForShipSlug(slug)}-${modeStem}-atlas-${SHIP_SPRITE_HEADING_SUFFIX}`;
  const [imageAtlas, sinkDepthAtlas] = await Promise.all([
    loadVehicleImage(key),
    loadVehicleImage(`${key}-sink-depth`)
  ]);
  const atlasHeight = SHIP_SHEET_FRAME_SIZE * Math.ceil(SHIP_HEADING_COUNT / SHIP_SHEET_COLS) *
    frameCount;
  const atlasWidth = SHIP_SHEET_FRAME_SIZE * SHIP_SHEET_COLS;
  validateImageDimensions(imageAtlas, `Demo rowing ship atlas: ${slug}`, atlasWidth, atlasHeight);
  validateImageDimensions(
    sinkDepthAtlas,
    `Demo rowing ship sink-depth atlas: ${slug}`,
    atlasWidth,
    atlasHeight
  );
  const renderLayers = await shipRenderLayerAssetStore.request(slug);
  const frames = await Promise.all(Array.from({ length: frameCount }, async (_, frameIndex) => {
    const image = demoRowingAtlasFrame(imageAtlas, frameIndex, atlasWidth, atlasHeight / frameCount);
    const sinkDepthImage = demoRowingAtlasFrame(
      sinkDepthAtlas,
      frameIndex,
      atlasWidth,
      atlasHeight / frameCount
    );
    validateShipSpriteSheet(image, `Demo rowing ship: ${slug} frame ${frameIndex}`);
    validateShipSpriteSheet(
      sinkDepthImage,
      `Demo rowing ship sink-depth: ${slug} frame ${frameIndex}`
    );
    const sourceKey = `${vehicleSpriteKeyForShipSlug(slug)}-${modeStem}-${frameIndex}-` +
      SHIP_SPRITE_HEADING_SUFFIX;
    attachShipRenderLayers(image, slug, sourceKey, renderLayers);
    return Object.freeze({ image, sinkDepthImage });
  }));
  return Object.freeze(frames);
}

function demoRowingAtlasFrame(atlas, frameIndex, width, height) {
  const canvas = document.createElement("canvas");
  canvas.width = width;
  canvas.height = height;
  const frameCtx = canvas.getContext("2d");
  if (!frameCtx) throw new Error(`Could not create demo rowing atlas frame ${frameIndex}`);
  frameCtx.imageSmoothingEnabled = false;
  frameCtx.drawImage(atlas, 0, frameIndex * height, width, height, 0, 0, width, height);
  return canvas;
}

async function loadWhaleAssetsForSlug(slug) {
  if (!WHALE_ASSET_SLUG_SET.has(slug)) throw new Error(`Unknown whale asset slug: ${slug}`);
  const [image, sinkDepthImage] = await Promise.all([
    loadAssetImage(
      `assets/animals/${slug}-32-headings.png?v=${ANIMAL_ASSET_VERSION}`,
      `${slug} sprite sheet`
    ),
    loadAssetImage(
      `assets/animals/${slug}-32-headings-sink-depth.png?v=${ANIMAL_ASSET_VERSION}`,
      `${slug} sink-depth sheet`
    )
  ]);
  validateShipSpriteSheet(image, `${slug} sprite sheet`);
  validateShipSpriteSheet(sinkDepthImage, `${slug} sink-depth sheet`);
  prebakeSubmergedObjectRenderSource(image, sinkDepthImage, slug);
  return Object.freeze({ image, sinkDepthImage });
}

async function loadIcebergAssetsForSlug(slug) {
  if (!icebergManifest?.variantsBySlug?.has(slug)) {
    throw new Error(`Unknown iceberg asset slug: ${slug}`);
  }
  const [image, sinkDepthImage] = await Promise.all([
    loadAssetImage(
      `assets/icebergs/${slug}-32-headings.png?v=${ICEBERG_ASSET_VERSION}`,
      `${slug} sprite sheet`
    ),
    loadAssetImage(
      `assets/icebergs/${slug}-32-headings-sink-depth.png?v=${ICEBERG_ASSET_VERSION}`,
      `${slug} sink-depth sheet`
    )
  ]);
  validateShipSpriteSheet(image, `${slug} sprite sheet`);
  validateShipSpriteSheet(sinkDepthImage, `${slug} sink-depth sheet`);
  prebakeSubmergedObjectRenderSource(image, sinkDepthImage, slug);
  return Object.freeze({ image, sinkDepthImage });
}

async function requestShipVisualAssets(slug) {
  if (!shipSpriteAssetStore || !rowingShipAssetStore) {
    throw new Error("Ship asset stores are not initialized");
  }
  const spriteAsset = await shipSpriteAssetStore.request(slug);
  if (ROWING_SHIP_ANIMATION_SPECS.has(slug)) {
    await rowingShipAssetStore.request(slug);
  }
  return spriteAsset;
}

function residentShipVisualAsset(slug) {
  if (!shipSpriteAssetStore || !rowingShipAssetStore) return null;
  const spriteAsset = shipSpriteAssetStore.peek(slug);
  if (!spriteAsset) return null;
  if (ROWING_SHIP_ANIMATION_SPECS.has(slug) && !rowingShipAssetStore.peek(slug)) return null;
  return spriteAsset;
}

function observeWorldAssetRequest(promise, context) {
  if (!(promise instanceof Promise)) throw new Error(`World asset request is not a Promise: ${context}`);
  if (observedWorldAssetPromises.has(promise)) return;
  observedWorldAssetPromises.add(promise);
  promise.then(
    () => {
      dirty = true;
    },
    (error) => {
      if (!pendingWorldAssetError) {
        const cause = error instanceof Error ? error : new Error(String(error));
        pendingWorldAssetError = new Error(`Streaming ${context} failed: ${cause.message}`, { cause });
      }
      dirty = true;
    }
  );
}

function queueShipVisualAssets(slug, context) {
  if (!shipSpriteAssetStore || !rowingShipAssetStore) {
    throw new Error("Ship asset stores are not initialized");
  }
  const spritePromise = shipSpriteAssetStore.request(slug);
  observeWorldAssetRequest(
    spritePromise,
    `${context} ship sprite for ${slug}`
  );
  if (ROWING_SHIP_ANIMATION_SPECS.has(slug)) {
    spritePromise.then(
      () => observeWorldAssetRequest(
        rowingShipAssetStore.request(slug),
        `${context} rowing animation for ${slug}`
      ),
      () => {}
    );
  }
}

function queueWhaleAssets(whale, context) {
  if (!whaleAssetStore) throw new Error("Whale asset store is not initialized");
  const slug = whaleAssetSlug(whale);
  const promise = whaleAssetStore.request(slug);
  observeWorldAssetRequest(promise, `${context} whale assets for ${slug}`);
}

function queueLandVehicleAssets(vehicleType, context) {
  if (!landVehicleAssetStore) throw new Error("Land-vehicle asset store is not initialized");
  const promise = landVehicleAssetStore.request(vehicleType);
  observeWorldAssetRequest(promise, `${context} ${vehicleType} assets`);
}

function residentWorldAnimationAsset(key) {
  if (!worldAnimationAssetStore) throw new Error("World animation asset store is not initialized");
  return worldAnimationAssetStore.peek(key);
}

function queueWorldAnimationAsset(key, context) {
  if (!worldAnimationAssetStore) throw new Error("World animation asset store is not initialized");
  observeWorldAssetRequest(
    worldAnimationAssetStore.request(key),
    `${context} ${key} animation`
  );
}

function validateShipSpriteSheet(img, label) {
  const rows = Math.ceil(SHIP_HEADING_COUNT / SHIP_SHEET_COLS);
  const expectedWidth = SHIP_SHEET_FRAME_SIZE * SHIP_SHEET_COLS;
  const expectedHeight = SHIP_SHEET_FRAME_SIZE * rows;
  validateImageDimensions(img, label, expectedWidth, expectedHeight);
}

async function loadShipWakeAnchors() {
  const bake = await fetchJson(SHIP_WAKE_ANCHORS_URL, "ship wake anchors");
  if (!bake || bake.frameSize !== SHIP_SHEET_FRAME_SIZE || bake.headings !== SHIP_HEADING_COUNT) {
    throw new Error("Ship wake anchor bake has incompatible dimensions");
  }
  if (!bake.ships || typeof bake.ships !== "object" || Array.isArray(bake.ships)) {
    throw new Error("Ship wake anchor bake is missing its ships object");
  }

  const anchorsBySlug = new Map();
  for (const [slug, anchors] of Object.entries(bake.ships)) {
    if (!SHIP_STATS_BY_SLUG.has(slug)) throw new Error(`Ship wake anchor bake contains unknown ship: ${slug}`);
    anchorsBySlug.set(slug, validateShipWakeAnchors(
      slug,
      anchors,
      SHIP_HEADING_COUNT,
      SHIP_SHEET_FRAME_SIZE
    ));
  }
  for (const slug of SHIP_MENU_SLUGS) {
    if (!anchorsBySlug.has(slug)) throw new Error(`Ship manifest is missing wake anchors for: ${slug}`);
  }
  return anchorsBySlug;
}

async function loadShipFootprints() {
  const bake = await fetchJson(SHIP_HULL_FOOTPRINTS_URL, "ship hull footprints");
  return validateShipFootprintBake(bake, SHIP_SHEET_FRAME_SIZE, SHIP_HEADING_COUNT, SHIP_MENU_SLUGS);
}

async function loadShipFlagAnchors() {
  const bake = await fetchJson(SHIP_FLAG_ANCHORS_URL, "ship flag anchors");
  const rowingFramesBySlug = new Map(SHIP_MENU_SLUGS.map((slug) => [
    slug,
    ROWING_SHIP_ANIMATION_SPECS.get(slug)?.frames || 0
  ]));
  return validateShipFlagAnchorBake(
    bake,
    SHIP_SHEET_FRAME_SIZE,
    SHIP_HEADING_COUNT,
    rowingFramesBySlug
  );
}

async function loadShipRenderLayerManifest() {
  const manifest = await fetchJson(SHIP_RENDER_LAYERS_URL, "ship-render-layers");
  return validateShipRenderLayerManifest(
    manifest,
    SHIP_STATS.map((stats) => stats.slug)
  );
}

async function loadIcebergManifest() {
  const manifest = await fetchJson(ICEBERG_MANIFEST_URL, "iceberg sprite manifest");
  if (!manifest || manifest.frameSize !== SHIP_SHEET_FRAME_SIZE ||
      manifest.headings !== SHIP_HEADING_COUNT || manifest.sheetCols !== SHIP_SHEET_COLS) {
    throw new Error("Iceberg sprite manifest has incompatible dimensions");
  }
  if (!Array.isArray(manifest.variants)) throw new Error("Iceberg sprite manifest requires variants");
  const expected = new Set(ICEBERG_VARIANTS.map((variant) => variant.id));
  const variantsBySlug = new Map();
  const footprintsBySlug = new Map();
  for (const variant of manifest.variants) {
    if (!expected.delete(variant.slug)) {
      throw new Error(`Iceberg sprite manifest contains an unexpected variant: ${variant.slug}`);
    }
    variantsBySlug.set(variant.slug, variant);
    footprintsBySlug.set(variant.slug, validateShipFootprintFrames(
      variant.slug,
      variant.hullFootprints,
      SHIP_HEADING_COUNT
    ));
  }
  if (expected.size > 0) {
    throw new Error(`Iceberg sprite manifest is missing: ${[...expected].join(", ")}`);
  }
  return Object.freeze({
    manifest: Object.freeze({ ...manifest, variantsBySlug }),
    footprintsBySlug
  });
}

function requiredShipFlagAnchor(slug, frame, rowingFrameIndex) {
  const anchorSet = shipFlagAnchorsBySlug?.get(slug);
  if (!anchorSet) throw new Error(`Missing baked flag anchors for ship: ${slug}`);
  const anchors = rowingFrameIndex === null
    ? anchorSet.base
    : anchorSet.rowing[rowingFrameIndex];
  if (!anchors) {
    throw new Error(`Missing baked flag anchors for ship ${slug} rowing frame ${rowingFrameIndex}`);
  }
  const anchor = anchors[frame];
  if (!anchor) throw new Error(`Missing baked flag anchor for ship ${slug} frame ${frame}`);
  return anchor;
}

function requiredShipFootprints(slug) {
  const footprints = shipFootprintsBySlug?.get(slug);
  if (!footprints) throw new Error(`Missing baked hull footprints for ship: ${slug}`);
  return footprints;
}

function requiredIcebergFootprints(slug) {
  const footprints = icebergFootprintsBySlug?.get(slug);
  if (!footprints) throw new Error(`Missing baked hull footprint for iceberg: ${slug}`);
  return footprints;
}

function requiredShipWakeAnchors(slug) {
  const anchors = shipWakeAnchorsBySlug?.get(slug);
  if (!anchors) throw new Error(`Missing baked wake anchors for ship: ${slug}`);
  return anchors;
}

async function loadGameIconAtlas() {
  const image = await loadAssetImage(
    `assets/ui/game-icons.png?v=${GAME_ICON_ASSET_VERSION}`,
    "game icon atlas"
  );
  const dimensions = gameIconAtlasDimensions();
  validateImageDimensions(image, "game icon atlas", dimensions.width, dimensions.height);
  return image;
}

function createGameIconOutlineAtlas(image) {
  const dimensions = gameIconAtlasDimensions();
  const sourceCanvas = document.createElement("canvas");
  sourceCanvas.width = dimensions.width;
  sourceCanvas.height = dimensions.height;
  const sourceCtx = sourceCanvas.getContext("2d", { willReadFrequently: true });
  if (!sourceCtx) throw new Error("Could not create game icon outline source canvas");
  sourceCtx.imageSmoothingEnabled = false;
  sourceCtx.drawImage(image, 0, 0);
  const source = sourceCtx.getImageData(0, 0, dimensions.width, dimensions.height);
  const outlinePixels = buildPixelIconOutlinePixels({
    sourcePixels: source.data,
    width: dimensions.width,
    height: dimensions.height,
    cells: gameIconIds().map(gameIconAtlasRect)
  });

  const outlineCanvas = document.createElement("canvas");
  outlineCanvas.width = dimensions.width;
  outlineCanvas.height = dimensions.height;
  const outlineCtx = outlineCanvas.getContext("2d");
  if (!outlineCtx) throw new Error("Could not create game icon outline canvas");
  const outline = outlineCtx.createImageData(dimensions.width, dimensions.height);
  outline.data.set(outlinePixels);
  outlineCtx.putImageData(outline, 0, 0);
  return outlineCanvas;
}

async function loadAlwaysVisibleAnimalImages() {
  const fish = await loadAssetImage(
    `${FISH_SPRITE_URL}?v=${ANIMAL_ASSET_VERSION}`,
    "fish image"
  );
  validateImageDimensions(fish, "fish image", FISH_SPRITE_SIZE, FISH_SPRITE_SIZE);
  return Object.freeze({ fish });
}

async function loadLandVehicleAssets(vehicleType) {
  if (!LAND_VEHICLE_ASSET_TYPES.has(vehicleType)) {
    throw new Error(`Unknown land-vehicle asset type: ${vehicleType}`);
  }
  if (BUILD_EDITION_ID === "demo") return loadDemoLandVehicleAssets(vehicleType);
  return Object.freeze(await Promise.all(Array.from(
    { length: LAND_CART_WALK_FRAME_COUNT },
    async (_, frameIndex) => {
      const diagnosticId = `${vehicleType} walk frame ${frameIndex}`;
      const prefix = `assets/vehicles/${vehicleType}/${vehicleType}-walk-${frameIndex}-${SHIP_SPRITE_HEADING_SUFFIX}`;
      const [image, lightImage, shadeImage, shadowImage] = await Promise.all([
        loadAssetImage(`${prefix}.png?v=${LAND_VEHICLE_ASSET_VERSION}`, diagnosticId),
        loadAssetImage(`${prefix}-light.png?v=${LAND_VEHICLE_ASSET_VERSION}`, `${diagnosticId} light`),
        loadAssetImage(`${prefix}-shade.png?v=${LAND_VEHICLE_ASSET_VERSION}`, `${diagnosticId} shade`),
        loadAssetImage(`${prefix}-shadow.png?v=${LAND_VEHICLE_ASSET_VERSION}`, `${diagnosticId} shadow`)
      ]);
      validateShipSpriteSheet(image, diagnosticId);
      return Object.freeze({
        image,
        lighting: Object.freeze({
          light: decodeDirectionalLightingMask(lightImage, SHIP_SHEET_FRAME_SIZE, `${diagnosticId} light`),
          shade: decodeDirectionalLightingMask(shadeImage, SHIP_SHEET_FRAME_SIZE, `${diagnosticId} shade`),
          shadow: decodeDirectionalLightingMask(shadowImage, SHIP_SHADOW_FRAME_SIZE, `${diagnosticId} shadow`)
        })
      });
    }
  )));
}

async function loadDemoLandVehicleAssets(vehicleType) {
  const prefix = `assets/vehicles/${vehicleType}/${vehicleType}-walk-atlas-${SHIP_SPRITE_HEADING_SUFFIX}`;
  const [imageAtlas, lightAtlas, shadeAtlas, shadowAtlas] = await Promise.all([
    loadAssetImage(`${prefix}.png?v=${LAND_VEHICLE_ASSET_VERSION}`, `${vehicleType} walk atlas`),
    loadAssetImage(`${prefix}-light.png?v=${LAND_VEHICLE_ASSET_VERSION}`, `${vehicleType} light atlas`),
    loadAssetImage(`${prefix}-shade.png?v=${LAND_VEHICLE_ASSET_VERSION}`, `${vehicleType} shade atlas`),
    loadAssetImage(`${prefix}-shadow.png?v=${LAND_VEHICLE_ASSET_VERSION}`, `${vehicleType} shadow atlas`)
  ]);
  const colorHeight = SHIP_SHEET_FRAME_SIZE * Math.ceil(SHIP_HEADING_COUNT / SHIP_SHEET_COLS);
  const lightingHeight = colorHeight * 2;
  const shadowHeight = SHIP_SHADOW_FRAME_SIZE * Math.ceil(SHIP_HEADING_COUNT / SHIP_SHEET_COLS) * 2;
  const colorWidth = SHIP_SHEET_FRAME_SIZE * SHIP_SHEET_COLS;
  const shadowWidth = SHIP_SHADOW_FRAME_SIZE * SHIP_SHEET_COLS;
  validateImageDimensions(
    imageAtlas,
    `${vehicleType} walk atlas`,
    colorWidth,
    colorHeight * LAND_CART_WALK_FRAME_COUNT
  );
  for (const [kind, atlas] of [["light", lightAtlas], ["shade", shadeAtlas]]) {
    validateImageDimensions(
      atlas,
      `${vehicleType} ${kind} atlas`,
      colorWidth,
      lightingHeight * LAND_CART_WALK_FRAME_COUNT
    );
  }
  validateImageDimensions(
    shadowAtlas,
    `${vehicleType} shadow atlas`,
    shadowWidth,
    shadowHeight * LAND_CART_WALK_FRAME_COUNT
  );
  return Object.freeze(Array.from({ length: LAND_CART_WALK_FRAME_COUNT }, (_, frameIndex) => {
    const diagnosticId = `${vehicleType} walk frame ${frameIndex}`;
    const image = stackedAtlasFrame(imageAtlas, frameIndex, colorWidth, colorHeight);
    const lightImage = stackedAtlasFrame(lightAtlas, frameIndex, colorWidth, lightingHeight);
    const shadeImage = stackedAtlasFrame(shadeAtlas, frameIndex, colorWidth, lightingHeight);
    const shadowImage = stackedAtlasFrame(shadowAtlas, frameIndex, shadowWidth, shadowHeight);
    validateShipSpriteSheet(image, diagnosticId);
    return Object.freeze({
      image,
      lighting: Object.freeze({
        light: decodeDirectionalLightingMask(lightImage, SHIP_SHEET_FRAME_SIZE, `${diagnosticId} light`),
        shade: decodeDirectionalLightingMask(shadeImage, SHIP_SHEET_FRAME_SIZE, `${diagnosticId} shade`),
        shadow: decodeDirectionalLightingMask(shadowImage, SHIP_SHADOW_FRAME_SIZE, `${diagnosticId} shadow`)
      })
    });
  }));
}

function stackedAtlasFrame(atlas, frameIndex, width, height) {
  const canvas = document.createElement("canvas");
  canvas.width = width;
  canvas.height = height;
  const frameCtx = canvas.getContext("2d");
  if (!frameCtx) throw new Error(`Could not extract stacked atlas frame ${frameIndex}`);
  frameCtx.imageSmoothingEnabled = false;
  frameCtx.drawImage(atlas, 0, frameIndex * height, width, height, 0, 0, width, height);
  return canvas;
}

