function handleCheatCodeKeyDown(event) {
  const available = cheatCodesAvailable();
  if (!cheatCodeInput.active && !available) return false;
  const result = processCheatCodeKey(cheatCodeInput, event);
  if (!result.handled) return false;
  event.preventDefault();
  if (result.status === "opened" || result.status === "edited") {
    showSurvivalNotice(`CHEAT CODE: ${cheatCodeInput.buffer || "_"}`, "good");
  } else if (result.status === "canceled") {
    showSurvivalNotice("CHEAT CODE CANCELED", "warn");
  } else if (result.status === "unknown") {
    showSurvivalNotice(`UNKNOWN CHEAT: ${result.code || "EMPTY"}`, "warn");
  } else if (result.command) {
    if (!available) throw new Error("Cannot apply a cheat code outside an active voyage");
    applyCheatCommand(result.command);
  }
  dirty = true;
  return true;
}

function cheatCodesAvailable() {
  return Boolean(!CAPTURE_SCENARIO && hasStartedVoyage && gameState && ship && !gameOverReason && !lakeBattleMode);
}

function applyCheatCommand(command) {
  if (command === CHEAT_COMMAND_DISCOVER_ALL) {
    const result = grantAllDiscoveriesForCheat(gameState, discoveryCatalog);
    showSurvivalNotice(
      result.granted > 0
        ? `${result.granted} DISCOVERIES UNLOCKED`
        : `ALL ${result.total} DISCOVERIES ALREADY FOUND`,
      "good"
    );
  } else if (command === CHEAT_COMMAND_MILLION_DOUBLOONS) {
    grantMillionDoubloonsForCheat(gameState);
    showSurvivalNotice("DOUBLOONS SET TO 1,000,000", "good");
    playCoinClinkSound();
  } else {
    throw new Error(`Unknown cheat command: ${command}`);
  }
  if (!saveVoyageNow(`cheat code: ${command}`)) {
    throw new Error(`Could not save voyage after cheat command: ${command}`);
  }
  console.info(`[pixel-globe] applied cheat command: ${command}`);
}

function numericQueryParam(params, name, fallback, min, max) {
  const raw = params.get(name);
  if (raw === null || raw === "") return fallback;
  const value = Number(raw);
  if (!Number.isFinite(value) || value < min || value > max) {
    throw new Error(`Invalid ${name} query param: ${raw}. Expected ${min}..${max}`);
  }
  return value;
}

function booleanQueryParam(params, name, fallback) {
  const raw = params.get(name);
  if (raw === null || raw === "") return fallback;
  const normalized = raw.trim().toLowerCase();
  if (["1", "true", "yes", "on"].includes(normalized)) return true;
  if (["0", "false", "no", "off"].includes(normalized)) return false;
  throw new Error(`Invalid ${name} query param: ${raw}. Expected true/false`);
}

function buildSpriteDominantColors(imageMap) {
  const colors = new Map();
  const sampleCanvas = document.createElement("canvas");
  const sampleCtx = sampleCanvas.getContext("2d", { willReadFrequently: true });
  if (!sampleCtx) throw new Error("Could not create terrain sprite sampling canvas");
  sampleCtx.imageSmoothingEnabled = false;

  for (const [key, img] of imageMap.entries()) {
    sampleCanvas.width = img.width;
    sampleCanvas.height = img.height;
    sampleCtx.clearRect(0, 0, img.width, img.height);
    sampleCtx.drawImage(img, 0, 0);
    colors.set(key, mostCommonOpaqueColor(key, sampleCtx.getImageData(0, 0, img.width, img.height)));
  }

  return colors;
}

function buildRiverColors(imageMap) {
  const frame1 = riverColorFrame("water_shallow_01", imageMap.get("water_shallow_01"));
  const frame2 = riverColorFrame("water_shallow_02", imageMap.get("water_shallow_02"));
  if (!frame1.main || !frame1.light || !frame2.main || !frame2.light) {
    throw new Error("Could not derive river colors from loaded terrain sprites");
  }
  return {
    base: frame1.main,
    frames: [frame1, frame2]
  };
}

function riverColorFrame(key, img) {
  const ranked = rankedImageColors(key, img, 10);
  const main = ranked[0];
  const mainBrightness = colorBrightness(main);
  const light = ranked
    .filter((c) => colorBrightness(c) > mainBrightness + 18)
    .reduce((best, c) => (colorBrightness(c) > colorBrightness(best) ? c : best), main);

  return {
    main: rgbToHex(main.r, main.g, main.b),
    light: rgbToHex(light.r, light.g, light.b)
  };
}

function rankedImageColors(key, img, limit) {
  if (!img) throw new Error(`Missing terrain image for color sampling: ${key}`);
  const sampleCanvas = document.createElement("canvas");
  const sampleCtx = sampleCanvas.getContext("2d", { willReadFrequently: true });
  if (!sampleCtx) throw new Error("Could not create river color sampling canvas");
  sampleCanvas.width = img.width;
  sampleCanvas.height = img.height;
  sampleCtx.clearRect(0, 0, img.width, img.height);
  sampleCtx.drawImage(img, 0, 0);
  const ranked = rankOpaqueColors(sampleCtx.getImageData(0, 0, img.width, img.height), limit);
  if (ranked.length === 0) throw new Error(`Terrain sprite has no opaque pixels: ${key}`);
  return ranked;
}

function colorBrightness(color) {
  return color.r * 0.299 + color.g * 0.587 + color.b * 0.114;
}

function edgeIndexTowardNeighbor(tileId, neighborId) {
  return worldEdgeIndexTowardNeighbor(graph, tileId, neighborId);
}

function chartProtectionTerrainClass(tileId) {
  const row = earthById?.[tileId];
  if (!row) throw new Error(`Chart protection is missing terrain for tile ${tileId}`);
  const surface = isWaterSurfaceRow(row) ? "water" : "land";
  return `${surface}:${row.t || "land"}:${terrainLevel(row, tileId)}`;
}

function chartProtectionFeatureTileIds() {
  if (
    !graph ||
    !cityByTileId ||
    !landRoadNetwork ||
    !riverMasks ||
    !riverToWaterMasks ||
    !mountainLandmarks
  ) {
    throw new Error("Chart protection features require initialized world geography");
  }
  const protectedIds = new Set(cityByTileId.keys());
  for (const target of colonizationTargetPlacements) protectedIds.add(target.tileId);
  for (const tileId of landRoadNetwork.segmentsByTileId.keys()) protectedIds.add(tileId);
  for (const tileId of mountainLandmarks.peakTileIds) protectedIds.add(tileId);
  for (const coral of coralReefs) protectedIds.add(coral.tileId);
  for (const discovery of discoveryCatalog) {
    if (Number.isInteger(discovery.tileId)) protectedIds.add(discovery.tileId);
    if (Number.isInteger(discovery.spriteTileId)) protectedIds.add(discovery.spriteTileId);
  }
  for (let tileId = 0; tileId < graph.tileCount; tileId++) {
    if ((riverMasks[tileId] || 0) !== 0 || (riverToWaterMasks[tileId] || 0) !== 0) {
      protectedIds.add(tileId);
    }
  }
  return protectedIds;
}

function buildWaterDepthBands() {
  const deepBand = WATER_DEPTH_GRADATION_COUNT + 1;
  const bands = new Uint8Array(graph.tileCount);
  bands.fill(deepBand);

  const queue = [];
  for (let id = 0; id < graph.tileCount; id++) {
    if (!isOceanWaterRow(earthById[id])) continue;
    for (const neighborId of graph.neighbors[id]) {
      if (isOceanWaterRow(earthById[neighborId])) continue;
      bands[id] = 1;
      queue.push(id);
      break;
    }
  }

  let head = 0;
  while (head < queue.length) {
    const id = queue[head++];
    const nextBand = bands[id] + 1;
    if (nextBand > WATER_DEPTH_GRADATION_COUNT) continue;
    for (const neighborId of graph.neighbors[id]) {
      if (!isOceanWaterRow(earthById[neighborId])) continue;
      if (bands[neighborId] <= nextBand) continue;
      bands[neighborId] = nextBand;
      queue.push(neighborId);
    }
  }

  console.info(`[pixel-globe] water depth bands: ${queue.length} coastal/intermediate ocean tiles`);
  return bands;
}

function isOceanWaterRow(row) {
  return row?.t === "water";
}

function mostCommonOpaqueColor(key, imageData) {
  const ranked = rankOpaqueColors(imageData, 1);
  if (ranked.length === 0) throw new Error(`Terrain sprite has no opaque pixels: ${key}`);
  const color = ranked[0];
  return rgbToHex(color.r, color.g, color.b);
}

function rankOpaqueColors(imageData, limit) {
  const counts = new Map();
  const data = imageData.data;
  for (let i = 0; i < data.length; i += 4) {
    if (data[i + 3] <= 50) continue;
    const colorKey = `${data[i]},${data[i + 1]},${data[i + 2]}`;
    counts.set(colorKey, (counts.get(colorKey) || 0) + 1);
  }

  return [...counts.entries()]
    .sort((a, b) => b[1] - a[1])
    .slice(0, limit)
    .map(([colorKey, count]) => {
      const [r, g, b] = colorKey.split(",").map(Number);
      return { r, g, b, count };
    });
}

function rgbToHex(r, g, b) {
  const parts = [r, g, b].map((v) => clamp(v, 0, 255).toString(16).padStart(2, "0"));
  return `#${parts.join("")}`;
}

function parseHexColor(hex) {
  const clean = hex.startsWith("#") ? hex.slice(1) : hex;
  if (!/^[0-9a-fA-F]{6}$/.test(clean)) throw new Error(`Expected 6-digit hex color, got: ${hex}`);
  const n = Number.parseInt(clean, 16);
  return {
    r: (n >> 16) & 255,
    g: (n >> 8) & 255,
    b: n & 255
  };
}

function rgbaFromHex(hex, alpha) {
  const { r, g, b } = parseHexColor(hex);
  return `rgba(${r}, ${g}, ${b}, ${alpha})`;
}

function easeInOut(t) {
  const x = clamp(t, 0, 1);
  return x * x * (3 - 2 * x);
}

function loop(nowMs) {
  const cadence = advanceFrameCadence({
    nowMs,
    nextFrameMs: nextGameFrameMs,
    bypass: Boolean(PERFORMANCE_BENCHMARK || CAPTURE_FRAME_PASS)
  });
  nextGameFrameMs = cadence.nextFrameMs;
  if (!cadence.run) {
    requestAnimationFrame(loop);
    return;
  }
  const benchmarkCpuStartMs = performanceBenchmarkState ? performance.now() : 0;
  try {
    runFrame(nowMs);
  } catch (error) {
    console.error(error);
    gameTelemetry.captureCrash(error, telemetryCrashContext());
    if (CAPTURE_AUTOMATIC || PERFORMANCE_BENCHMARK) {
      window.__PIXEL_GLOBE_CAPTURE_ERROR__ = error instanceof Error ? error.message : String(error);
    }
    if (PERFORMANCE_BENCHMARK) setPerformanceBenchmarkDomStatus({ error: error instanceof Error ? error.message : String(error) });
    drawFatalError(error, "Prototype runtime failure");
  } finally {
    if (performanceBenchmarkState) {
      try {
        updatePerformanceBenchmark(nowMs, performance.now() - benchmarkCpuStartMs);
      } catch (error) {
        const message = error instanceof Error ? error.message : String(error);
        window.__PIXEL_GLOBE_CAPTURE_ERROR__ = message;
        setPerformanceBenchmarkDomStatus({ error: message });
        console.error(error);
      }
    }
  }
}

function pollControllerDuringStartup(nowMs) {
  if (regularGameLoopStarted) return;
  if (telemetryConsentModal) pollGamepadControls(nowMs);
  requestAnimationFrame(pollControllerDuringStartup);
}

function telemetryCrashContext(screenOverride = null) {
  const screen = screenOverride || (
    lakeBattleMode ? `${lakeBattleMode.kind === "historical" ? "historical-battle" : "lake-battle"}:${lakeBattleMode.screen}` :
      gameOverReason ? "voyage-ended" :
        dialogueState ? `dialogue:${dialogueState.kind || "unknown"}` :
          optionsMenu.isOpen ? `options:${optionsMenu.view}` :
            shipInfoMenu.isOpen ? `ship-info:${shipInfoMenu.view}` :
              politicsMenu.isOpen ? "politics" :
                discoveriesMenu.isOpen ? "discoveries" :
                  achievementsMenu.isOpen ? "achievements" :
                    aboardMenu.isOpen ? "people-aboard" :
                      captainMenu.isOpen ? "captain-chart" :
                        startMenu ? "start-menu" :
                          anchored ? "anchored" : "sailing"
  );
  return {
    screen,
    mainQuest: gameState?.memory?.campaignGoal?.type || "none",
    ship: ship?.typeSlug || gameState?.ship?.slug || "none",
    redact: [gameState?.playerCharacter?.name].filter(Boolean)
  };
}

function runFrame(nowMs, { scheduleNextFrame = true, forceRender = false } = {}) {
  if (pendingWorldAssetError) {
    const error = pendingWorldAssetError;
    pendingWorldAssetError = null;
    throw error;
  }
  if (pendingWorldSimulationError) {
    const error = pendingWorldSimulationError;
    pendingWorldSimulationError = null;
    throw error;
  }
  if (frameRateOverlayEnabled && sampleFrameRate(frameRateMeter, nowMs)) dirty = true;
  pollGamepadControls(nowMs);
  const dt = clamp((nowMs - lastFrameMs) / 1000, 0, 0.05);
  const sessionFrameSeconds = Math.max(0, (nowMs - lastSessionFrameMs) / 1000);
  lastFrameMs = nowMs;
  lastSessionFrameMs = nowMs;
  if (captureDirector && !capturePlaybackPaused) updateCaptureDirectorFrame(nowMs);
  if (lakeBattleMode) {
    updateWaterAnimation(nowMs);
    updateLakeBattleModeFrame(dt, nowMs);
    updateMusicContext(nowMs);
    dirty = false;
    render(nowMs);
    lastStatusMs = nowMs;
    lastOverlayMs = nowMs;
    updatePlatformActivity();
    if (scheduleNextFrame) requestAnimationFrame(loop);
    return;
  }
  const simulationPaused = worldSimulationIsPaused({
    capturePlaybackPaused: Boolean(capturePlaybackPaused),
    menusOpen: menusAreOpen(),
    dialogueActive: Boolean(dialogueState),
    characterAlertActive: Boolean(captainAlertModal),
    playerIntroActive: Boolean(playerIntroModal),
    gameOver: Boolean(gameOverReason),
    goldTreasureActive: Boolean(goldTreasureSequence)
  });
  let chartRebuiltThisFrame = false;
  if (!simulationPaused) {
    advanceActivePlayTime(gameState, dt);
    if (!CAPTURE_SCENARIO && !PERFORMANCE_BENCHMARK) {
      gameTelemetry.recordActivePlaySeconds(activeSessionFrameSeconds(sessionActivityState, {
        nowMs,
        elapsedSeconds: sessionFrameSeconds,
        continuousInput: keys.size > 0 || pointerSteering.active || controllerSteering !== null
      }));
    }
    if (updatePlayerWind(dt)) dirty = true;
    if (fishingAction) {
      if (updateFishingAction(nowMs)) dirty = true;
    } else if (!anchored && !portWaitState && updateSailing(dt)) dirty = true;
    if (updateNavalWeapons(dt)) dirty = true;
    if (updateWaterAnimation(nowMs)) dirty = true;
    if (updateFishAnimation(nowMs)) dirty = true;
    if (measurePerformanceBenchmarkStage(
      "weather.masks",
      () => advancePendingWeatherMaskRefresh(nowMs)
    )) dirty = true;
    if (updateSurfaceIceTransition(nowMs)) dirty = true;
    if (presentPendingSurfaceIceEntrapment()) dirty = true;
    if (measurePerformanceBenchmarkStage("weather", () => updateWeather(dt, nowMs))) dirty = true;
    if (measurePerformanceBenchmarkStage(
      "weather.breakingWave",
      () => updateStormWaveHazard(dt)
    )) dirty = true;
    if (updateCampaignGoalReturnReminder()) dirty = true;
    if (updateWhiteWhaleSightingObjective()) dirty = true;
    if (updateColonizationQuest()) dirty = true;
    if (updateShoreScavenge(nowMs)) dirty = true;
    if (updateAnchoredAnimalEncounter()) dirty = true;
    chartRebuiltThisFrame = measurePerformanceBenchmarkStage("chart", () => ensureChart());
    const chartRepairCheckIsDue = nowMs - chartDriftMeasuredAtMs >= 1000;
    const chartDrift = measurePerformanceBenchmarkStage(
      "chart.drift",
      () => measureChartDriftAtInterval(nowMs)
    );
    if (chartRepairCheckIsDue && maybeStartChartVisualRepair(nowMs, chartDrift)) dirty = true;
    if (measurePerformanceBenchmarkStage("icebergs", () => updateIcebergs(dt))) dirty = true;
    if (measurePerformanceBenchmarkStage("whales", () => updateWhales(dt, nowMs))) dirty = true;
    if (updateDiscoveries(nowMs)) dirty = true;
    if (measurePerformanceBenchmarkStage("npcShips", () => updateNpcShips(dt))) dirty = true;
    if (updateSeagulls(dt, nowMs)) dirty = true;
    if (updateWindIndicator(dt)) dirty = true;
    if (measurePerformanceBenchmarkStage("precipitation", () => updatePrecipitationAnimation(nowMs))) dirty = true;
    if (updateStormLightning(stormLightningState, {
      nowMs,
      intensity: playerStormIntensity(),
      enabled: !captureUsesScriptedShipLightning()
    })) dirty = true;
    recordCapturePosition(nowMs);
  }
  if (updateChartVisualRepair(nowMs)) dirty = true;
  if (updateStormShipStrike(stormShipStrikeState, nowMs)) dirty = true;
  if (updateWorldShipSinkEffects(nowMs)) dirty = true;
  if (updateStatusPersonParticles(nowMs)) dirty = true;
  if (updateItemAcquisitionEffects(nowMs)) dirty = true;
  if (updateDepartureControlFeedback(nowMs)) dirty = true;
  updateAmbientAudio(dt);
  updateMusicContext(nowMs);
  if (!CAPTURE_SCENARIO && hasStartedVoyage && !surfaceIceEntrapmentActive &&
      nowMs - lastAutosaveMs >= AUTOSAVE_INTERVAL_MS) {
    schedulePeriodicAutosave(nowMs);
  }
  if (!simulationPaused && updateWorldSpriteAnimation(nowMs)) dirty = true;
  const renderDue = shouldRenderFrame({
    forceRender,
    dirty,
    continuousAnimation: Boolean(startMenu),
    simulationPaused,
    nowMs,
    lastStatusMs,
    statusIntervalMs: 1000
  });
  if (renderDue && (!chartRebuiltThisFrame || forceRender)) {
    dirty = false;
    measurePerformanceBenchmarkStage("render", () => render(nowMs));
    lastStatusMs = nowMs;
    lastOverlayMs = nowMs;
  } else if (!renderDue && !simulationPaused && !startMenu && !creditsMenu.isOpen && !playerIntroModal &&
      nowMs - lastOverlayMs > 250) {
    if (minimapShouldBeVisible()) drawMinimap(nowMs);
    drawSurvivalMeters();
    drawSavePersistenceWarning();
    drawSurvivalHudTooltip();
    drawStatusPersonParticles(nowMs);
    if (portWaitState) drawPortWaitControls(nowMs);
    else drawCaptainMenuButton();
    lastOverlayMs = nowMs;
  }
  updatePlatformActivity();
  if (scheduleNextFrame) requestAnimationFrame(loop);
}

function updatePlatformActivity() {
  if (!steamPlatformBridge ||
      lastFrameMs - lastPlatformActivityUpdateMs < PLATFORM_ACTIVITY_UPDATE_INTERVAL_MS) return;
  lastPlatformActivityUpdateMs = lastFrameMs;
  const activity = currentPlatformActivity();
  void platformActivityPublisher.publish(activity).catch((error) => {
    console.error("[steam] could not update activity", error);
  });
}

function currentPlatformActivity() {
  if (startMenu) return platformActivity("#Status_MainMenu", "In the main menu", PLATFORM_TIMELINE_MODE.MENUS);
  if (lakeBattleMode) {
    return platformActivity("#Status_ShipBattle", "Fighting a ship battle", PLATFORM_TIMELINE_MODE.PLAYING);
  }
  if (gameOverReason) {
    return platformActivity("#Status_VoyageEnded", "Reviewing a completed voyage", PLATFORM_TIMELINE_MODE.MENUS);
  }
  const port = platformActivityPort();
  if (port) {
    const place = cityLabelText(port);
    return platformActivity("#Status_InPort", `In port at ${place}`, PLATFORM_TIMELINE_MODE.MENUS, { place });
  }
  if (playerHasCombatEngagement()) {
    return platformActivity("#Status_InCombat", "Fighting at sea", PLATFORM_TIMELINE_MODE.PLAYING);
  }
  const vessel = ship?.typeSlug ? shipLabelForSlug(ship.typeSlug) : "ship";
  if (anchored) {
    return platformActivity("#Status_Anchored", `Anchored aboard a ${vessel}`, PLATFORM_TIMELINE_MODE.STAGING, {
      ship: vessel
    });
  }
  return platformActivity("#Status_Sailing", `Sailing a ${vessel}`, PLATFORM_TIMELINE_MODE.PLAYING, {
    ship: vessel
  });
}

function platformActivity(displayToken, description, mode, parameters = {}) {
  return {
    presence: {
      steam_display: displayToken,
      status: description,
      ...Object.fromEntries(Object.entries(parameters).map(([key, value]) => [key, String(value)]))
    },
    timeline: { description, mode }
  };
}

function platformActivityPort() {
  if (portWaitState) {
    return chartPortCallById(portWaitState.portId) || cityByTileId.get(portWaitState.cityTileId) || null;
  }
  if (dialogueState?.kind === "port") {
    return chartPortCallById(dialogueState.portId) || cityByTileId.get(dialogueState.cityTileId) || null;
  }
  return null;
}

function publishPlatformTimelineEvent(event) {
  void addPlatformTimelineEvent(steamPlatformBridge, event).catch((error) => {
    console.error("[steam] could not add timeline event", error);
  });
}

function measurePerformanceBenchmarkStage(name, callback) {
  if (!performanceBenchmarkState) return callback();
  const startedAtMs = performance.now();
  try {
    return callback();
  } finally {
    recordPerformanceBenchmarkStage(performanceBenchmarkState, name, performance.now() - startedAtMs);
  }
}

function updateWorldSpriteAnimation(nowMs) {
  const tick = Math.floor(nowMs / Math.min(CITY_FLAG_FRAME_MS, FIRE_FRAME_MS));
  if (tick === worldSpriteAnimationTick) return false;
  worldSpriteAnimationTick = tick;
  return true;
}

