function createCharacterAlertModal(character, message, expressionId = "neutral", {
  kind = "alert",
  buttonLabel = "CONTINUE",
  choices = null,
  leftCharacter = null,
  rightCharacter = null
} = {}) {
  if (!character) throw new Error("Character alert requires a character");
  if (!["alert", "birthday", "sequence", "choice"].includes(kind)) {
    throw new Error(`Unknown character alert kind: ${kind}`);
  }
  if (typeof buttonLabel !== "string" || buttonLabel.trim() === "") {
    throw new Error("Character alert requires a button label");
  }
  if (kind === "choice") {
    if (!Array.isArray(choices) || choices.length < 2 || choices.length > 3 || choices.some((choice) => (
      typeof choice?.label !== "string" || choice.label.trim() === "" || typeof choice.onSelect !== "function"
    ))) {
      throw new Error("Character choice alert requires two or three actionable choices");
    }
  } else if (choices !== null) {
    throw new Error(`Character alert kind ${kind} cannot have choices`);
  }
  const captain = gameState?.playerCharacter || null;
  const participants = leftCharacter
    ? dialoguePortraitPair(leftCharacter, rightCharacter, character)
    : captain && captain.id !== character.id
      ? dialoguePortraitPair(captain, character, character)
      : dialoguePortraitPair(character, null, character);
  return {
    kind,
    character,
    leftCharacter: participants.leftCharacter,
    rightCharacter: participants.rightCharacter,
    message,
    expressionId,
    buttonLabel,
    page: 0,
    hovered: false,
    buttonRect: captainAlertButtonRect(),
    choices: choices ? Object.freeze(choices.map((choice) => Object.freeze({ ...choice }))) : null,
    selectedChoiceIndex: 0,
    choiceRects: choices ? captainAlertChoiceRects(choices.length) : null
  };
}

