function createSoundPool(url, count, label) {
  return Array.from({ length: count }, () => {
    const audio = new Audio(`${url}?v=${SFX_ASSET_VERSION}`);
    audio.preload = "auto";
    audio.addEventListener("error", () => console.warn(`[pixel-globe] ${label} failed to load`));
    return audio;
  });
}

function createAmbientLoop(url, label) {
  const audio = new Audio(`${url}?v=${SFX_ASSET_VERSION}`);
  audio.preload = "auto";
  audio.loop = true;
  audio.volume = 0;
  audio.addEventListener("error", () => console.warn(`[pixel-globe] ${label} failed to load`));
  return {
    audio,
    label,
    currentVolume: 0,
    targetVolume: 0,
    started: false,
    startAttempting: false
  };
}

function createAmbientPlaylist(urls, label) {
  if (!Array.isArray(urls) || urls.length === 0) {
    throw new Error(`${label} requires at least one audio track`);
  }
  const tracks = urls.map((url, index) => {
    const audio = new Audio(`${url}?v=${SFX_ASSET_VERSION}`);
    audio.preload = "auto";
    audio.loop = false;
    audio.volume = 0;
    audio.addEventListener("error", () => console.warn(`[pixel-globe] ${label} track ${index + 1} failed to load`));
    return audio;
  });
  return {
    tracks,
    label,
    currentTrack: null,
    currentIndex: -1,
    lastIndex: -1,
    currentVolume: 0,
    targetVolume: 0,
    nextStartMs: 0,
    startAttempting: false
  };
}

function ensureGameAudioStarted(fromUserGesture = false) {
  if (fromUserGesture) gameAudioActivationAllowed = true;
  if (!gameAudioActivationAllowed) return;
  ensureThemeMusicStarted();
  ensureActiveAmbientLoopsStarted();
  ensureActiveAmbientPlaylistsStarted(performance.now());
}

function ensureThemeMusicStarted() {
  if (!gameAudioActivationAllowed) return;
  if (!themeMusic) return;
  themeMusic.activate().catch(reportThemeMusicFailure);
}

function playMusicTrack(trackKey, options = {}) {
  if (!themeMusic) return;
  const nextTrackKey = MUSIC_TRACK_SPECS[trackKey] ? trackKey : "ship";
  themeMusic.request(nextTrackKey, options).catch(reportThemeMusicFailure);
}

function reportThemeMusicFailure(error) {
  console.error("[pixel-globe] music playback failure", error);
}

function setBackgroundMusicTrack(trackKey, options = {}) {
  const nextTrackKey = MUSIC_TRACK_SPECS[trackKey] ? trackKey : "ship";
  backgroundMusicTrackKey = nextTrackKey;
  if (combatMusicIsActive(lastFrameMs) && !options.force) return;
  playMusicTrack(nextTrackKey, options);
}

function musicTrackForCity(city) {
  return CITY_TYPE_MUSIC_TRACK_KEYS[city?.cityType] || "ship";
}

function startCombatMusicForThreat() {
  const trackKey = "combat";
  combatMusicUntilMs = Math.max(combatMusicUntilMs, lastFrameMs + COMBAT_MUSIC_HOLD_MS);
  playMusicTrack(trackKey, { crossfadeSeconds: MUSIC_COMBAT_CROSSFADE_SECONDS });
}

function combatMusicIsActive(nowMs) {
  if (lakeBattleMode && (
    lakeBattleMode.battle?.phase === LAKE_BATTLE_PHASE_ACTIVE ||
    lakeBattleMode.screen === LAKE_BATTLE_SCREEN_SINKING
  )) return true;
  return nowMs < combatMusicUntilMs;
}

function isCombatMusicTrack(trackKey) {
  return trackKey === "combat" || trackKey === "combatSmall" || trackKey === "combatBig";
}

function updateMusicContext(nowMs) {
  if (!themeMusic) return;
  if (gameOverReason || dialogueState || combatMusicIsActive(nowMs)) {
    ensureThemeMusicContinuity();
    return;
  }
  const stormIntensity = playerStormIntensity();
  if (!stormMusicActive && stormIntensity >= STORM_MUSIC_ENTER_INTENSITY) {
    stormMusicActive = true;
  } else if (stormMusicActive && stormIntensity < STORM_MUSIC_EXIT_INTENSITY) {
    stormMusicActive = false;
  }
  if (stormMusicActive) {
    if (themeMusic.currentTrackKey !== "storm" && themeMusic.requestedTrackKey !== "storm") {
      playMusicTrack("storm", { crossfadeSeconds: MUSIC_COMBAT_CROSSFADE_SECONDS });
    }
    ensureThemeMusicContinuity();
    return;
  }
  if (
    isCombatMusicTrack(themeMusic.currentTrackKey)
    || isCombatMusicTrack(themeMusic.requestedTrackKey)
    || themeMusic.currentTrackKey === "storm"
    || themeMusic.requestedTrackKey === "storm"
  ) {
    playMusicTrack(backgroundMusicTrackKey || "ship", {
      crossfadeSeconds: MUSIC_RETURN_CROSSFADE_SECONDS
    });
  }
  ensureThemeMusicContinuity();
}

function ensureThemeMusicContinuity() {
  if (!themeMusic.requestedTrackKey || themeMusic.currentTrackKey || themeMusic.transitionPending) return;
  themeMusic.ensureRequestedTrack().catch(reportThemeMusicFailure);
}

function ensureActiveAmbientLoopsStarted() {
  for (const loop of ambientSoundLoops()) {
    if (loop.targetVolume > 0.001) ensureAmbientLoopStarted(loop);
  }
}

function ensureActiveAmbientPlaylistsStarted(nowMs) {
  for (const playlist of ambientSoundPlaylists()) {
    if (playlist.targetVolume > 0.001) ensureAmbientPlaylistStarted(playlist, nowMs);
  }
}

function ensureAmbientLoopStarted(loop) {
  if (!gameAudioActivationAllowed) return;
  if (!loop || loop.started || loop.startAttempting) return;
  loop.started = true;
  loop.startAttempting = true;
  loop.audio.currentTime = 0;
  loop.audio.playbackRate = randomizedSfxPlaybackRate();
  applyThemeAudioSettings();
  const playPromise = loop.audio.play();
  if (playPromise && typeof playPromise.catch === "function") {
    playPromise
      .catch(() => {
        loop.started = false;
      })
      .finally(() => {
        loop.startAttempting = false;
      });
  } else {
    loop.startAttempting = false;
  }
}

function ensureAmbientPlaylistStarted(playlist, nowMs) {
  if (!gameAudioActivationAllowed || playlist.currentTrack || playlist.startAttempting) return;
  if (playlist.targetVolume <= 0.001 || nowMs < playlist.nextStartMs) return;
  let index = Math.floor(Math.random() * playlist.tracks.length);
  if (playlist.tracks.length > 1 && index === playlist.lastIndex) {
    index = (index + 1 + Math.floor(Math.random() * (playlist.tracks.length - 1))) % playlist.tracks.length;
  }
  const audio = playlist.tracks[index];
  playlist.currentTrack = audio;
  playlist.currentIndex = index;
  playlist.lastIndex = index;
  playlist.currentVolume = 0;
  playlist.startAttempting = true;
  audio.currentTime = 0;
  audio.playbackRate = randomizedSfxPlaybackRate();
  applyThemeAudioSettings();
  const playPromise = audio.play();
  if (playPromise && typeof playPromise.catch === "function") {
    playPromise
      .catch(() => {
        playlist.currentTrack = null;
        playlist.currentIndex = -1;
        playlist.nextStartMs = nowMs + SFX_WHALE_SONG_MIN_GAP_MS;
      })
      .finally(() => {
        playlist.startAttempting = false;
      });
  } else {
    playlist.startAttempting = false;
  }
}

function applyThemeAudioSettings() {
  const musicVolume = CAPTURE_SCENARIO ? 0 : clamp(optionsMenu.musicVolume, 0, 1);
  if (themeMusic) themeMusic.setOutput(musicVolume, optionsMenu.muted);
  if (soundEffects) {
    for (const audio of [
      ...soundEffects.cannon,
      ...soundEffects.smallFirearm,
      ...soundEffects.bowFire,
      ...soundEffects.arrowHit,
      ...soundEffects.impact,
      ...soundEffects.armorGlance,
      ...soundEffects.sailDeploy,
      ...soundEffects.discoverySuccess,
      ...soundEffects.coinClink,
      ...soundEffects.fishing,
      ...soundEffects.stormWave,
      ...soundEffects.rowing,
      ...soundEffects.fishingSuccess,
      ...soundEffects.fishingFailure,
      ...soundEffects.scavengeSuccess,
      ...soundEffects.scavengeFailure,
      ...soundEffects.collection,
      ...soundEffects.lightning,
      ...soundEffects.whaleBlow,
      ...soundEffects.whaleKill
    ]) {
      audio.muted = optionsMenu.muted;
    }
    applyAmbientAudioSettings();
  }
}

function applyAmbientAudioSettings() {
  if (!soundEffects) return;
  const sfxVolume = clamp(optionsMenu.sfxVolume, 0, 1);
  for (const loop of ambientSoundLoops()) {
    setAudioElementMuted(loop.audio, optionsMenu.muted);
    setAudioElementVolume(loop.audio, optionsMenu.muted ? 0 : sfxVolume * loop.currentVolume);
  }
  for (const playlist of ambientSoundPlaylists()) {
    for (const track of playlist.tracks) {
      setAudioElementMuted(track, optionsMenu.muted);
      setAudioElementVolume(track, optionsMenu.muted || track !== playlist.currentTrack
        ? 0
        : sfxVolume * playlist.currentVolume);
    }
  }
}

function setAudioElementMuted(audio, muted) {
  if (audio.muted !== muted) audio.muted = muted;
}

function setAudioElementVolume(audio, volume) {
  const nextVolume = clamp(volume, 0, 1);
  if (Math.abs(audio.volume - nextVolume) > 0.0005) audio.volume = nextVolume;
}

function playSoundEffect(pool, volume, playbackRate = 1) {
  if (!pool || pool.length === 0) return;
  if (CAPTURE_FRAME_PASS && (
    CAPTURE_SCENARIO?.sequence?.kind === "sail" || pool === soundEffects?.sailDeploy
  )) return;
  if (!CAPTURE_FRAME_PASS && (optionsMenu.muted || optionsMenu.sfxVolume <= 0)) return;
  const audio = pool.find((item) => item.paused || item.ended) || pool[0];
  audio.pause();
  audio.currentTime = 0;
  audio.playbackRate = clamp(randomizedSfxPlaybackRate(playbackRate), 0.75, 1.25);
  const outputVolume = CAPTURE_FRAME_PASS ? volume : optionsMenu.sfxVolume * volume;
  audio.volume = clamp(outputVolume, 0, 1);
  audio.muted = CAPTURE_FRAME_PASS ? false : optionsMenu.muted;
  if (CAPTURE_FRAME_PASS) {
    emitCaptureEvent("capture-sfx", {
      assetPath: captureSfxAssetPath(audio),
      volume: audio.volume,
      playbackRate: audio.playbackRate
    });
    return;
  }
  const playPromise = audio.play();
  if (playPromise && typeof playPromise.catch === "function") playPromise.catch(() => {});
}

function captureSfxAssetPath(audio) {
  const url = new URL(audio.currentSrc || audio.src, window.location.href);
  const appUrl = new URL("./", window.location.href);
  const assetPath = url.pathname.startsWith(appUrl.pathname)
    ? url.pathname.slice(appUrl.pathname.length)
    : "";
  if (url.origin !== appUrl.origin || !assetPath.startsWith("assets/sfx/")) {
    throw new Error(`Capture SFX must be a local game asset: ${url}`);
  }
  return assetPath;
}

function playCannonShotSound(broadsideCount, distancePx = 0) {
  const countGain = 0.72 + Math.min(0.28, Math.max(0, broadsideCount - 1) * 0.025);
  const distanceGain = cannonShotDistanceGain(distancePx);
  playSoundEffect(
    soundEffects?.cannon,
    SFX_CANNON_VOLUME * countGain * distanceGain
  );
}

function playLightningStrikeSound() {
  playSoundEffect(soundEffects?.lightning, SFX_LIGHTNING_VOLUME, 1);
}

function playCrewDeathSound() {
  playSoundEffect(soundEffects?.crewDeath, SFX_CREW_DEATH_VOLUME);
}

function playWhaleBlowSound() {
  playSoundEffect(soundEffects?.whaleBlow, SFX_WHALE_BLOW_VOLUME);
}

function playWhaleKillSound() {
  playSoundEffect(soundEffects?.whaleKill, SFX_WHALE_KILL_VOLUME);
}

function playWhaleLineBreakSound() {
  playSoundEffect(soundEffects?.sailDeploy, 0.36, 1.2);
}

function playBowFireSound() {
  playSoundEffect(soundEffects?.bowFire, SFX_BOW_FIRE_VOLUME);
}

function playArrowHitSound() {
  playSoundEffect(soundEffects?.arrowHit, SFX_ARROW_HIT_VOLUME);
}

function playNavalAttackSound(weapon, broadsideCount, distancePx = 0) {
  if (weapon.kind === NAVAL_WEAPON_ARROW) {
    playBowFireSound();
    return;
  }
  if (weapon.kind === NAVAL_WEAPON_CANNON) {
    playCannonShotSound(broadsideCount, distancePx);
    return;
  }
  throw new Error(`Unknown naval attack sound: ${weapon.kind}`);
}

function playShoreBatteryAttackSound(weapon, gunCount, distancePx) {
  if (weapon.kind !== NAVAL_WEAPON_CANNON) {
    playNavalAttackSound(weapon, gunCount, distancePx);
    return;
  }
  // A fortified gun remains clearly audible throughout its firing range.
  playCannonShotSound(
    gunCount,
    Math.min(distancePx, SHORE_BATTERY_CANNON_SOUND_DISTANCE_CAP_PX)
  );
}

function playPortableWeaponAttackSound(weapon, count, distancePx = 0) {
  const soundKind = portableWeaponSoundKind(weapon);
  if (soundKind === PORTABLE_WEAPON_SOUND_BOW) {
    playBowFireSound();
    return;
  }
  const distanceGain = cannonShotDistanceGain(distancePx);
  if (soundKind === PORTABLE_WEAPON_SOUND_SMALL_FIREARM) {
    const volleyGain = 0.72 + Math.min(0.28, Math.max(0, count - 1) * 0.04);
    playSoundEffect(
      soundEffects?.smallFirearm,
      SFX_SMALL_FIREARM_VOLUME * volleyGain * distanceGain
    );
    return;
  }
  if (soundKind === PORTABLE_WEAPON_SOUND_CANNON) {
    playSoundEffect(soundEffects?.cannon, SFX_CANNON_VOLUME * 0.42 * distanceGain, 1.28);
    return;
  }
  throw new Error(`Unknown portable weapon sound kind: ${soundKind}`);
}

function playNavalImpactSound(projectile) {
  if (projectile.kind === NAVAL_WEAPON_ARROW) {
    playArrowHitSound();
    return;
  }
  playCannonImpactSound(Math.hypot(
    projectile.targetX - projectile.startX,
    projectile.targetY - projectile.startY
  ));
}

function playCannonImpactSound(distancePx = 0) {
  const distanceGain = clamp(1 - distancePx / CANNON_RANGE_PX, 0.35, 1);
  playSoundEffect(soundEffects?.impact, SFX_IMPACT_VOLUME * distanceGain, 0.96);
}

function playArmorGlanceSound(distancePx = 0) {
  const distanceGain = clamp(1 - distancePx / CANNON_RANGE_PX, 0.35, 1);
  playSoundEffect(soundEffects?.armorGlance, SFX_ARMOR_GLANCE_VOLUME * distanceGain, 1.02);
}

function playIceDigOutSound() {
  playSoundEffect(soundEffects?.impact, SFX_IMPACT_VOLUME * 0.82, 1.18);
}

function playSailDeploySound() {
  playSoundEffect(soundEffects?.sailDeploy, SFX_SAIL_DEPLOY_VOLUME);
}

function playDiscoverySuccessSound() {
  playSoundEffect(soundEffects?.discoverySuccess, SFX_DISCOVERY_SUCCESS_VOLUME);
}

function playCoinClinkSound() {
  playSoundEffect(soundEffects?.coinClink, SFX_COIN_CLINK_VOLUME);
}

function playFishingSound() {
  playSoundEffect(soundEffects?.fishing, SFX_FISHING_VOLUME);
}

function playStormWaveCrashSound(impact, sweptCrewCount) {
  playSoundEffect(
    soundEffects?.stormWave,
    stormWaveImpactSoundVolume({ intensity: impact.intensity, sweptCrewCount })
  );
}

function playManOverboardSplashSound() {
  playSoundEffect(soundEffects?.fishing, SFX_FISHING_VOLUME * 0.58, 1.12);
}

function playRowingStrokeSound(spec) {
  playSoundEffect(
    soundEffects?.rowing,
    spec.volume * SFX_ROWING_SPLASH_VOLUME_SCALE,
    spec.playbackRate
  );
}

function playFishingSuccessSound() {
  playSoundEffect(soundEffects?.fishingSuccess, SFX_FISHING_SUCCESS_VOLUME);
}

function playFishingFailureSound() {
  playSoundEffect(soundEffects?.fishingFailure, SFX_FISHING_FAILURE_VOLUME);
}

function playScavengeSuccessSound() {
  playSoundEffect(soundEffects?.scavengeSuccess, SFX_SCAVENGE_SUCCESS_VOLUME);
}

function playScavengeFailureSound() {
  playSoundEffect(soundEffects?.scavengeFailure, SFX_SCAVENGE_FAILURE_VOLUME);
}

function playCollectionDingSound() {
  playSoundEffect(soundEffects?.collection, SFX_COLLECTION_VOLUME, 1.02);
}

function playAchievementDingSound() {
  playSoundEffect(soundEffects?.collection, 0.78, 1.12);
}

function updateAmbientAudio(dt) {
  if (!soundEffects) return;
  ambientAudioUpdateAccumulator = Math.min(
    AMBIENT_AUDIO_UPDATE_INTERVAL_SECONDS * 2,
    ambientAudioUpdateAccumulator + dt
  );
  if (ambientAudioUpdateAccumulator < AMBIENT_AUDIO_UPDATE_INTERVAL_SECONDS) return;
  const elapsed = ambientAudioUpdateAccumulator;
  ambientAudioUpdateAccumulator = 0;
  ambientAudioContextAccumulator = Math.min(
    AMBIENT_AUDIO_CONTEXT_INTERVAL_SECONDS * 2,
    ambientAudioContextAccumulator + elapsed
  );
  if (!ambientAudioContext ||
      ambientAudioContextAccumulator >= AMBIENT_AUDIO_CONTEXT_INTERVAL_SECONDS) {
    const contextElapsed = ambientAudioContextAccumulator;
    ambientAudioContextAccumulator = 0;
    const nearestLand = nearestLandForAmbientContext();
    ambientAudioContext = Object.freeze({
      shore: shoreProximity(nearestLand),
      sailing: sailingAmbientTargets(contextElapsed, nearestLand),
      storm: playerStormIntensity(),
      fire: visibleFireSoundPresence()
    });
  }
  ambientAudioWildlifeAccumulator = Math.min(
    AMBIENT_AUDIO_WILDLIFE_INTERVAL_SECONDS * 2,
    ambientAudioWildlifeAccumulator + elapsed
  );
  if (!ambientAudioWildlife ||
      ambientAudioWildlifeAccumulator >= AMBIENT_AUDIO_WILDLIFE_INTERVAL_SECONDS) {
    ambientAudioWildlifeAccumulator = 0;
    ambientAudioWildlife = Object.freeze({
      seagulls: seagullAmbientPresence(),
      whales: visibleUnderwaterWhaleSongPresence()
    });
  }
  const { shore, sailing, storm, fire } = ambientAudioContext;
  const repairFogWind = chartRepairFog
    ? chartRepairFogWindPresence(chartRepairFogFrame(
      chartRepairFog.animation,
      lastFrameMs,
      chartRepairFog.release
    ))
    : 0;
  updateRowingStrokeAudio(elapsed, sailing.rowing);
  let changed = false;
  changed = updateAmbientLoop(
    soundEffects.harbour,
    dialogueState ? SFX_HARBOUR_MAX_VOLUME : 0,
    SFX_HARBOUR_MAX_VOLUME,
    elapsed
  ) || changed;
  changed = updateAmbientLoop(
    soundEffects.seagulls,
    ambientAudioWildlife.seagulls * SFX_SEAGULLS_MAX_VOLUME,
    SFX_SEAGULLS_MAX_VOLUME,
    elapsed,
    SFX_SEAGULL_FADE_PER_SECOND
  ) || changed;
  changed = updateAmbientLoop(
    soundEffects.shoreWaves,
    shore * SFX_SHORE_WAVES_MAX_VOLUME,
    SFX_SHORE_WAVES_MAX_VOLUME,
    elapsed
  ) || changed;
  changed = updateAmbientLoop(
    soundEffects.harshWind,
    sailing.harshWind * SFX_HARSH_WIND_MAX_VOLUME,
    SFX_HARSH_WIND_MAX_VOLUME,
    elapsed,
    SFX_WIND_FADE_PER_SECOND
  ) || changed;
  changed = updateAmbientLoop(
    soundEffects.winterWind,
    Math.max(sailing.winterWind, repairFogWind) * SFX_WINTER_WIND_MAX_VOLUME,
    SFX_WINTER_WIND_MAX_VOLUME,
    elapsed,
    SFX_WIND_FADE_PER_SECOND
  ) || changed;
  changed = updateAmbientLoop(
    soundEffects.desertWind,
    sailing.desertWind * SFX_DESERT_WIND_MAX_VOLUME,
    SFX_DESERT_WIND_MAX_VOLUME,
    elapsed,
    SFX_WIND_FADE_PER_SECOND
  ) || changed;
  changed = updateAmbientLoop(
    soundEffects.storm,
    storm * SFX_STORM_MAX_VOLUME,
    SFX_STORM_MAX_VOLUME,
    elapsed,
    SFX_STORM_FADE_PER_SECOND
  ) || changed;
  changed = updateAmbientLoop(
    soundEffects.sailFlap,
    sailing.sailFlap * SFX_SAIL_FLAP_MAX_VOLUME,
    SFX_SAIL_FLAP_MAX_VOLUME,
    elapsed,
    SFX_SAIL_FLAP_FADE_PER_SECOND
  ) || changed;
  changed = updateAmbientLoop(
    soundEffects.underway,
    sailing.underway * SFX_UNDERWAY_MAX_VOLUME,
    SFX_UNDERWAY_MAX_VOLUME,
    elapsed,
    SFX_UNDERWAY_FADE_PER_SECOND
  ) || changed;
  changed = updateAmbientLoop(
    soundEffects.fire,
    fire * SFX_FIRE_MAX_VOLUME,
    SFX_FIRE_MAX_VOLUME,
    elapsed,
    SFX_FIRE_FADE_PER_SECOND
  ) || changed;
  changed = updateAmbientPlaylist(
    soundEffects.whaleSongs,
    ambientAudioWildlife.whales * SFX_WHALE_SONG_MAX_VOLUME,
    SFX_WHALE_SONG_MAX_VOLUME,
    elapsed,
    lastFrameMs,
    SFX_WHALE_SONG_FADE_PER_SECOND
  ) || changed;
  if (changed) applyAmbientAudioSettings();
}

function updateRowingStrokeAudio(dt, active) {
  const spec = ship ? ROWING_SHIP_ANIMATION_SPECS.get(ship.typeSlug) : null;
  if (!spec) {
    advanceRowingCadence(rowingCadenceState, { active: false, dt, periodSeconds: 1 });
    return;
  }
  const stroke = advanceRowingCadence(rowingCadenceState, {
    active,
    dt,
    periodSeconds: spec.frames * spec.frameMs / 1000
  });
  if (stroke) playRowingStrokeSound(spec);
}

function updateAmbientLoop(loop, targetVolume, maxVolume, dt, fadePerSecond = SFX_AMBIENT_FADE_PER_SECOND) {
  if (!loop) return false;
  loop.targetVolume = clamp(targetVolume, 0, maxVolume);
  if (loop.targetVolume > 0.001) ensureAmbientLoopStarted(loop);
  const maxStep = fadePerSecond * dt;
  const delta = clamp(loop.targetVolume - loop.currentVolume, -maxStep, maxStep);
  let changed = false;
  if (Math.abs(delta) > 0.0005) {
    loop.currentVolume = clamp(loop.currentVolume + delta, 0, maxVolume);
    changed = true;
  }
  if (loop.currentVolume <= 0.0005 && loop.started && loop.targetVolume <= 0.0005) {
    loop.audio.pause();
    loop.started = false;
    changed = true;
  }
  return changed;
}

function updateAmbientPlaylist(playlist, targetVolume, maxVolume, dt, nowMs, fadePerSecond) {
  if (!playlist) return false;
  playlist.targetVolume = clamp(targetVolume, 0, maxVolume);
  let changed = false;
  const maxStep = fadePerSecond * dt;
  const delta = clamp(playlist.targetVolume - playlist.currentVolume, -maxStep, maxStep);
  if (Math.abs(delta) > 0.0005) {
    playlist.currentVolume = clamp(playlist.currentVolume + delta, 0, maxVolume);
    changed = true;
  }
  if (playlist.currentTrack?.ended) {
    playlist.currentTrack = null;
    playlist.currentIndex = -1;
    playlist.nextStartMs = nowMs + randomWhaleSongGapMs();
    changed = true;
  }
  if (playlist.targetVolume <= 0.0005 && playlist.currentVolume <= 0.0005) {
    if (playlist.currentTrack) {
      playlist.currentTrack.pause();
      playlist.currentTrack.currentTime = 0;
      playlist.currentTrack = null;
      playlist.currentIndex = -1;
      playlist.nextStartMs = nowMs + SFX_WHALE_SONG_MIN_GAP_MS;
      changed = true;
    }
    return changed;
  }
  if (!playlist.currentTrack && nowMs >= playlist.nextStartMs) {
    ensureAmbientPlaylistStarted(playlist, nowMs);
    changed = Boolean(playlist.currentTrack) || changed;
  }
  return changed;
}

function ambientSoundLoops() {
  if (!soundEffects) return [];
  return [
    soundEffects.harbour,
    soundEffects.seagulls,
    soundEffects.shoreWaves,
    soundEffects.harshWind,
    soundEffects.winterWind,
    soundEffects.desertWind,
    soundEffects.storm,
    soundEffects.sailFlap,
    soundEffects.underway,
    soundEffects.fire
  ].filter(Boolean);
}

function ambientSoundPlaylists() {
  return soundEffects?.whaleSongs ? [soundEffects.whaleSongs] : [];
}

function randomWhaleSongGapMs() {
  return SFX_WHALE_SONG_MIN_GAP_MS +
    Math.random() * (SFX_WHALE_SONG_MAX_GAP_MS - SFX_WHALE_SONG_MIN_GAP_MS);
}

function visibleUnderwaterWhaleSongPresence() {
  if (!gameState?.memory?.whales || !chart || !localLayout || !ship) return 0;
  for (const match of worldSpatialMatches(
    localLayout.viewX,
    localLayout.viewY,
    SFX_WHALE_SONG_FAR_PX,
    [WORLD_SPATIAL_KIND.WHALE]
  )) {
    const whale = match.entry.value;
    const call = whaleInteractionCall(whale);
    if (!call) continue;
    const distancePx = Math.hypot(call.x - SCREEN_W / 2, call.y - SCREEN_H / 2);
    if (underwaterWhaleSongPresence(
      whale,
      distancePx,
      SFX_WHALE_SONG_NEAR_PX,
      SFX_WHALE_SONG_FAR_PX
    ) > 0) return 1;
  }
  return 0;
}

function visibleFireSoundPresence() {
  if (!chart || !localLayout || !ship) return 0;
  let nearestDistanceSquared = Infinity;
  for (const source of visibleWorldFireSources()) {
    nearestDistanceSquared = Math.min(
      nearestDistanceSquared,
      distance2(localLayout.viewX, localLayout.viewY, source.x, source.y)
    );
  }
  return Number.isFinite(nearestDistanceSquared)
    ? fireSoundPresence(Math.sqrt(nearestDistanceSquared))
    : 0;
}

function sailingAmbientTargets(dt, nearestLand) {
  if (!ship || !graph) {
    throw new Error("Cannot update sailing ambience before the ship and globe are initialized");
  }
  const wind = windForShip();
  const windFlow = windFlowVectorAtShip(wind);
  const alignment = clamp(dot3(ship.heading, windFlow), -1, 1);
  const angleFromWindRad = Math.acos(clamp(-alignment, -1, 1));
  const targets = updateSailingAudioState(sailingAudioState, {
    dt,
    paused: Boolean(dialogueState || captainAlertModal || menusAreOpen() || gameOverReason),
    heading: ship.heading,
    speedPx: vectorLength(ship.velocity) * PIXELS_PER_RADIAN,
    isRiver: shipIsInRiverWater(),
    windStrength: wind.strength,
    windContext: sailingWindContext(nearestLand),
    angleFromWindRad,
    stallAngleRad: currentPlayerEffectiveShipStats().upwindStallAngleRad
  });
  const paused = Boolean(dialogueState || captainAlertModal || menusAreOpen() || gameOverReason);
  const rowing = !paused && playerShipIsRowing();
  if (!anchored) {
    return {
      ...targets,
      sailFlap: ship.stats.propulsion !== SHIP_PROPULSION_OAR && !rowing ? targets.sailFlap : 0,
      underway: rowing ? 0 : targets.underway,
      rowing
    };
  }
  return {
    ...targets,
    sailFlap: 0,
    underway: 0,
    rowing: false
  };
}

function sailingWindContext(nearestLand) {
  const tileId = ship.tileId;
  const flags = weatherFlagsForTile(tileId);
  if (seaIceMask?.[tileId] || freshwaterIceMask?.[tileId] || (flags & TILE_DAY_SNOW_FALL) !== 0) {
    return SAILING_WIND_CONTEXT_WINTER;
  }

  const nearbyLand = nearestLand?.distanceSquared <=
    SFX_WIND_TERRAIN_RADIUS_PX * SFX_WIND_TERRAIN_RADIUS_PX
    ? nearestLand.call
    : null;
  if (nearbyLand) {
    const terrain = nearbyLand.row.t || "";
    if (snowGroundMask?.[nearbyLand.id] || terrain.includes("ice") || terrain.includes("snow") || terrain.includes("tundra") || terrain.includes("cold")) {
      return SAILING_WIND_CONTEXT_WINTER;
    }
    if (terrain.includes("desert") || terrain.includes("steppe")) {
      return SAILING_WIND_CONTEXT_DESERT;
    }
  }
  if (Math.abs(graph.latDeg[tileId]) >= 58) return SAILING_WIND_CONTEXT_WINTER;
  return SAILING_WIND_CONTEXT_GENERAL;
}

function seagullAmbientPresence() {
  if (!chart || !animalImages) return 0;
  const offset = chartOffsetPixels(chart);
  const calls = seagullDrawCalls(chart, lastFrameMs).map((call) => ({
    x: call.x + offset.x,
    y: call.y + offset.y
  }));
  return seagullScreenPresence(calls, {
    screenWidth: SCREEN_W,
    screenHeight: SCREEN_H,
    spriteSize: SEAGULL_FRAME_SIZE,
    fadeMargin: SEAGULL_AUDIO_FADE_MARGIN_PX,
    fullPresenceCount: SEAGULL_AUDIO_FULL_PRESENCE_COUNT
  }) > 0 ? 1 : 0;
}

function shoreProximity(nearestLand) {
  if (!chart || !localLayout || !ship) return 0;
  const origin = { x: localLayout.viewX, y: localLayout.viewY };
  let nearest = nearestLand?.distanceSquared ?? Infinity;
  for (const call of chart.cityCalls || []) {
    nearest = Math.min(nearest, distance2(origin.x, origin.y, call.x, call.y) * 0.72);
  }

  if (!Number.isFinite(nearest)) return 0;
  const distance = Math.sqrt(nearest);
  if (distance <= SFX_HARBOUR_NEAR_PX) return 1;
  if (distance >= SFX_HARBOUR_FAR_PX) return 0;
  const t = (distance - SFX_HARBOUR_NEAR_PX) / (SFX_HARBOUR_FAR_PX - SFX_HARBOUR_NEAR_PX);
  return 1 - easeInOut(t);
}

function nearestLandForAmbientContext() {
  if (!chart?.waterIndex?.tileRows || !localLayout) return null;
  const maxDistanceSquared = SFX_HARBOUR_FAR_PX * SFX_HARBOUR_FAR_PX;
  const bx = Math.floor(localLayout.viewX / WAKE_WATER_BUCKET_PX);
  const by = Math.floor(localLayout.viewY / WAKE_WATER_BUCKET_PX);
  const range = Math.ceil(SFX_HARBOUR_FAR_PX / WAKE_WATER_BUCKET_PX);
  let nearest = null;
  let nearestDistanceSquared = maxDistanceSquared;
  for (let yy = by - range; yy <= by + range; yy++) {
    const row = chart.waterIndex.tileRows.get(yy);
    if (!row) continue;
    for (let xx = bx - range; xx <= bx + range; xx++) {
      const calls = row.get(xx);
      if (!calls) continue;
      for (const call of calls) {
        if (isWaterSurfaceRow(call.row)) continue;
        const candidateDistanceSquared = distance2(
          localLayout.viewX,
          localLayout.viewY,
          call.x,
          call.y
        );
        if (candidateDistanceSquared >= nearestDistanceSquared) continue;
        nearest = call;
        nearestDistanceSquared = candidateDistanceSquared;
      }
    }
  }
  return nearest ? { call: nearest, distanceSquared: nearestDistanceSquared } : null;
}

function distance2(ax, ay, bx, by) {
  const dx = ax - bx;
  const dy = ay - by;
  return dx * dx + dy * dy;
}

function loadStoredVolume(storageKey, defaultVolume) {
  const raw = readLocalStorage(storageKey);
  if (raw === null) return defaultVolume;
  const value = Number(raw);
  return Number.isFinite(value) ? clamp(value, 0, 1) : defaultVolume;
}

function loadStoredAudioMuted() {
  return readLocalStorage(AUDIO_MUTED_STORAGE_KEY) === "true";
}

function loadStoredControlScheme() {
  const raw = readLocalStorage(CONTROL_SCHEME_STORAGE_KEY);
  try {
    return normalizeControlScheme(raw);
  } catch (error) {
    console.warn("[pixel-globe] discarded invalid stored control scheme", error);
    return CONTROL_SCHEME_ABSOLUTE;
  }
}

function readLocalStorage(key) {
  return gameStorage.getItem(key);
}

function writeLocalStorage(key, value) {
  gameStorage.setItem(key, value);
}

async function saveRequestedScreenshot() {
  if (await triggerPlatformScreenshot(steamPlatformBridge)) {
    return { width: canvas.width, height: canvas.height };
  }
  return saveShareScreenshot(compositePresentationCanvas());
}

function compositePresentationCanvas() {
  const output = document.createElement("canvas");
  output.width = SCREEN_W;
  output.height = SCREEN_H;
  const outputCtx = output.getContext("2d", { alpha: false });
  if (!outputCtx) throw new Error("Could not create presentation capture canvas");
  outputCtx.imageSmoothingEnabled = false;
  outputCtx.drawImage(worldRenderer.captureFrameCanvas(), 0, 0);
  outputCtx.drawImage(canvas, 0, 0);
  return output;
}

function uiText(key, replacements = {}) {
  return translate(currentLanguage, key, replacements);
}

function renderedUiText(text) {
  const rendered = localizeProperNouns(currentLanguage, localizeText(currentLanguage, text));
  if (CAPTURE_FRAME_PASS && currentLanguage !== LANGUAGE_ENGLISH &&
      !captureLocalizedTextOutputs.has(text)) {
    const key = `${text}\u0000${rendered}`;
    captureRenderedTextRecords.set(key, { source: text, rendered });
  }
  if (rendered !== text) captureLocalizedTextOutputs.add(rendered);
  return rendered;
}

function setInterfaceLanguage(language, { persist = true } = {}) {
  const normalized = normalizeLanguage(language);
  currentLanguage = normalized;
  currentLanguageProfile = languageFontProfile(normalized);
  PIXEL_FONT_SMALL_8 = currentLanguageProfile.smallFont;
  PIXEL_FONT_DIALOGUE_8 = currentLanguageProfile.dialogueFont;
  PIXEL_FONT_SMALL_INK_TOP_OFFSET = languageUsesTallPixelMetrics(normalized) ? 1 : 3;
  optionsMenu.language = normalized;
  telemetryMetadata.locale = normalized;
  optionsMenu.fullscreenError = null;
  optionsMenu.returnError = null;
  document.documentElement.lang = normalized;
  if (persist) writeLocalStorage(INTERFACE_LANGUAGE_STORAGE_KEY, normalized);
  pixelTextRasterCache.clear();
  pixelTextWidthCache.clear();
  syncCanvasAriaLabel();
  dirty = true;
}

function localizedLineHeight(englishHeight = 10) {
  return languageUsesTallPixelMetrics(currentLanguage)
    ? Math.max(englishHeight, currentLanguageProfile.lineHeight)
    : englishHeight;
}

function resolvedPixelFont(font, text) {
  if (currentLanguageProfile.fontSize === 8 || !font.includes(`"${currentLanguageProfile.fontFamily}"`)) return font;
  if (textUsesLocaleGlyphs(currentLanguage, text) || !/[A-Za-z]/.test(text)) return font;
  return font === currentLanguageProfile.dialogueFont
    ? PIXEL_FONT_LATIN_DIALOGUE_8
    : PIXEL_FONT_LATIN_SMALL_8;
}

function playerCharacterIdentityKey() {
  if (CAPTURE_SCENARIO) return CAPTURE_SCENARIO.seed;
  const querySeed = new URLSearchParams(window.location.search).get("captainSeed");
  return resolvePlayerCharacterIdentityKey({
    querySeed,
    generatedSeed: randomPlayerCharacterIdentitySeed()
  });
}

function capturePlayerCharacter(character, scenarioValue) {
  const faction = factionById(scenarioValue.player.factionId);
  const captureCharacter = scenarioValue.player.characterPortraitSourceId
    ? generatePlayerCharacter({
      identityKey: scenarioValue.seed,
      homePort: captureCityByName(scenarioValue.player.homeCityName),
      portraitSourceId: scenarioValue.player.characterPortraitSourceId,
      manifest: characterPortraitManifest,
      usedNames: usedCharacterNames
    })
    : character;
  return Object.freeze({
    ...captureCharacter,
    nationalityId: faction.id,
    nationalityName: faction.name,
    nationalityAdjective: faction.adjective,
    homePortRealmName: faction.name
  });
}

function applyCaptureShipHeading(playerShip, headingDeg) {
  if (!playerShip?.position) throw new Error("Cannot set capture heading before creating the player ship");
  const heading = captureHeadingVector(playerShip.position, headingDeg);
  playerShip.heading = heading;
  playerShip.targetHeading = heading.slice();
}

function captureHeadingVector(position, headingDeg) {
  const frame = northUpCamera(position);
  const radians = headingDeg * Math.PI / 180;
  return normalizeTangentOrFallback([
    frame.right[0] * Math.cos(radians) + frame.up[0] * Math.sin(radians),
    frame.right[1] * Math.cos(radians) + frame.up[1] * Math.sin(radians),
    frame.right[2] * Math.cos(radians) + frame.up[2] * Math.sin(radians)
  ], position, frame.right);
}

function applyCaptureIcebergs(state, specs = []) {
  if (specs.length === 0) return;
  const memory = state?.memory?.icebergs;
  if (!memory || memory.individuals.length < specs.length) {
    throw new Error("Capture iceberg staging requires a seeded iceberg population");
  }
  for (let index = 0; index < specs.length; index++) {
    const spec = specs[index];
    const position = latLonToDirection(spec.lat, spec.lon);
    const environment = icebergEnvironmentAtPosition(position);
    if (!environment.navigable || environment.frozen) {
      throw new Error(`Capture iceberg is not in open navigable water: ${spec.lat},${spec.lon}`);
    }
    Object.assign(memory.individuals[index], {
      variantId: spec.variantId,
      tileId: environment.tileId,
      position,
      heading: captureHeadingVector(position, spec.headingDeg),
      integrity: 1
    });
  }
}

function applyCaptureDiplomacy(state, relations) {
  const diplomacy = state?.relations?.diplomacy;
  if (!diplomacy) throw new Error("Capture scenario cannot configure missing world diplomacy");
  for (const relation of relations) {
    diplomacy.overrides[diplomacyPairKey(relation.factionAId, relation.factionBId)] = relation.relation;
  }
  validateWorldDiplomacy(diplomacy);
}

function setupPerformanceBenchmark() {
  if (!PERFORMANCE_BENCHMARK || !CAPTURE_SCENARIO) {
    throw new Error("Performance benchmark requires a capture scenario");
  }
  applyResponsiveViewport(CAPTURE_VIEWPORT.width, CAPTURE_VIEWPORT.height);
  document.body.classList.add("capture-mode", "performance-benchmark-mode");
  chart = buildChart(camera);
  const stagedCartCount = stageVisibleLandCartTraffic(
    landTradeSystem,
    chart.visibleSet,
    weatherClockMinutes,
    PERFORMANCE_BENCHMARK.targetLandCarts
  );
  ship.velocity = scaleVector(ship.heading, currentPlayerEffectiveShipStats().topSpeedRad * 0.62);
  playerIntroModal = null;
  captainAlertModal = null;
  dialogueState = null;
  dialogueShipMotionPause = null;
  resetDistantWorldWorkerSchedule();
  chartVisualRepairStats = createChartVisualRepairStats();
  lastFrameMs = performance.now();
  performanceBenchmarkState = createPerformanceBenchmarkState(PERFORMANCE_BENCHMARK, lastFrameMs);
  performanceBenchmarkState.stagedCartCount = stagedCartCount;
  window.__PIXEL_GLOBE_BENCHMARK_READY__ = true;
  window.__PIXEL_GLOBE_BENCHMARK_RESULT__ = null;
  setPerformanceBenchmarkDomStatus({ ready: true });
  console.info(
    `[pixel-globe] benchmark ${PERFORMANCE_BENCHMARK.id}: ` +
      `${CAPTURE_SCENARIO.encounters.length} seeded ships, ${stagedCartCount} staged carts`
  );
}

function updatePerformanceBenchmark(nowMs, cpuMs) {
  const state = performanceBenchmarkState;
  if (!state || state.result) return;
  const result = recordPerformanceBenchmarkFrame(
    state,
    nowMs,
    cpuMs,
    worldRenderCount,
    () => performanceBenchmarkSceneSnapshot(state)
  );
  if (!result) return;
  window.__PIXEL_GLOBE_BENCHMARK_RESULT__ = Object.freeze({
    ...result,
    viewport: Object.freeze({ width: SCREEN_W, height: SCREEN_H }),
    environment: Object.freeze({
      hardwareConcurrency: navigator.hardwareConcurrency || null,
      deviceMemoryGb: navigator.deviceMemory || null,
      userAgent: navigator.userAgent
    })
  });
  capturePlaybackPaused = true;
  setPerformanceBenchmarkDomStatus({ result: window.__PIXEL_GLOBE_BENCHMARK_RESULT__ });
  console.info("[pixel-globe] performance benchmark complete", window.__PIXEL_GLOBE_BENCHMARK_RESULT__);
}

function setPerformanceBenchmarkDomStatus({ ready = false, result = null, error = null }) {
  let status = document.getElementById("pixel-globe-performance-benchmark");
  if (!status) {
    status = document.createElement("script");
    status.id = "pixel-globe-performance-benchmark";
    status.type = "application/json";
    status.hidden = true;
    document.body.appendChild(status);
  }
  if (ready) status.dataset.ready = "true";
  if (error) status.dataset.error = error;
  if (result) status.textContent = JSON.stringify(result);
}

function performanceBenchmarkSceneSnapshot(state) {
  const offset = chartOffsetPixels(chart);
  return {
    configuredNpcShips: CAPTURE_SCENARIO.encounters.length,
    activeVisualNpcShips: npcVisualShips.size,
    stagedLandCarts: state.stagedCartCount,
    totalLandCarts: landTradeSystem.carts.length,
    chartTiles: chart.tileCalls.length,
    renderedChartTiles: chart.tileCalls.reduce(
      (count, call) => count + (chartTileCallNearViewport(call, offset) ? 1 : 0),
      0
    ),
    chartFaces: chart.faceCalls.length,
    chartDrift: Object.freeze({ ...chartNorthUpDrift }),
    playerLatitudeDeg: Math.round(latitudeDegForDirection(ship.position) * 100) / 100,
    visibleCities: chart.cityCalls.length,
    cloudSprites: renderedCloudSpriteCount,
    precipitationParticles: precipParticles.length,
    flyingSeagulls: seagulls.length,
    wakeParticles: ship.wakeParticles.length,
    navalProjectiles: ship.navalProjectiles.length + npcCombatProjectiles.length,
    smokeBursts: cannonSmokeBursts.length,
    gpuRenderedNpcShips: gpuShipDrawCommands.reduce(
      (count, command) => count + Number(command.kind === "ship" && command.drawCall.kind === "npc"),
      0
    ),
    gpuRenderedPlayerShip: gpuShipDrawCommands.some(
      (command) => command.kind === "ship" && command.drawCall.kind === "player"
    ),
    chartVisualRepairs: Object.freeze({
      ...chartVisualRepairStats,
      ...chartVisualRepairBurden(chartVisualRepairStats)
    }),
    gpuRenderer: worldRenderer.stats()
  };
}

function setupCaptureMode() {
  if (!CAPTURE_SCENARIO) throw new Error("Capture mode requires a scenario");
  applyResponsiveViewport(CAPTURE_VIEWPORT.width, CAPTURE_VIEWPORT.height);
  document.body.classList.add("capture-mode");
  if (CAPTURE_SCENARIO.sequence) {
    captureDirector = createCaptureDirector(CAPTURE_SCENARIO.sequence);
    stageCaptureSequence();
  }
  if (CAPTURE_FRAME_PASS) {
    if (!captureDirector) throw new Error("Automatic frame capture requires a scripted sequence");
    setupAutomaticFramePass();
    return;
  }
  captureRecorder = new CaptureRecorder({
    canvas,
    scenario: CAPTURE_SCENARIO,
    maxSeconds: CAPTURE_MAX_SECONDS,
    simMinute: () => weatherClockMinutes
  });
  createCaptureControls({
    shell,
    scenario: CAPTURE_SCENARIO,
    recorder: captureRecorder,
    onRecordingStarted: captureRecordingStarted
  });
}

function captureRecordingStarted() {
  capturePlaybackPaused = false;
  ensureGameAudioStarted(true);
  emitCaptureEvent("scenario-start", captureScenarioStartEventData());
  dirty = true;
}

function emitCaptureEvent(type, data = {}) {
  if (deterministicCaptureEvents) {
    if (typeof type !== "string" || type.trim() === "") {
      throw new Error("Capture event type is required");
    }
    const elapsedMs = captureFrameStepper
      ? Math.round(captureFrameStepper.nextIndex * 1000 / captureFrameStepper.frameRate)
      : 0;
    deterministicCaptureEvents.push(Object.freeze({
      t: elapsedMs,
      simMinute: Math.round(weatherClockMinutes * 100) / 100,
      type,
      data: JSON.parse(JSON.stringify(data))
    }));
    return true;
  }
  return captureRecorder?.recordEvent(type, data) || false;
}

function captureScenarioStartEventData() {
  return {
    playerShip: ship.typeSlug,
    playerFaction: ship.factionId,
    encounterIds: CAPTURE_SCENARIO.encounters.map((encounter) => encounter.id),
    sequence: CAPTURE_SCENARIO.sequence || null
  };
}

function recordCapturePosition(nowMs) {
  if (!captureRecorder || captureRecorder.state !== "recording" || nowMs - captureLastPositionEventMs < 1000) {
    return;
  }
  captureLastPositionEventMs = nowMs;
  emitCaptureEvent("position", capturePositionEventData());
}

function capturePositionEventData() {
  return {
    lat: Math.round(latitudeDegForDirection(ship.position) * 10000) / 10000,
    lon: Math.round(longitudeDegForDirection(ship.position) * 10000) / 10000,
    tileId: ship.tileId,
    speed: Math.round(Math.hypot(...ship.velocity) * 1e7) / 1e7,
    heading: shipHeadingFrame()
  };
}

function setupAutomaticFramePass() {
  capturePlaybackPaused = false;
  captureFrameStepper = createAutomaticFrameStepper(captureDirector.sequence.durationSeconds);
  deterministicCaptureEvents = [];
  lastFrameMs = 0;
  captureDirector.lastWallClockMs = 0;
  emitCaptureEvent("capture-start", {
    viewport: { width: canvas.width, height: canvas.height },
    frameRate: captureFrameStepper.frameRate,
    method: "deterministic-frame-step"
  });
  emitCaptureEvent("scenario-start", captureScenarioStartEventData());
  window.__PIXEL_GLOBE_CAPTURE_TOTAL_FRAMES__ = captureFrameStepper.totalFrames;
  window.__PIXEL_GLOBE_CAPTURE_STEP__ = stepAutomaticCaptureFrame;
  window.__PIXEL_GLOBE_CAPTURE_SET_LANGUAGE__ = rerenderAutomaticCaptureLanguage;
  window.__PIXEL_GLOBE_CAPTURE_READY__ = true;
}

function rerenderAutomaticCaptureLanguage(language) {
  if (!CAPTURE_FRAME_PASS) {
    throw new Error("Capture language switching is unavailable outside the frame pass");
  }
  setInterfaceLanguage(language, { persist: false });
  captureRenderedTextRecords = new Map();
  captureLocalizedTextOutputs = new Set();
  runFrame(lastFrameMs, { scheduleNextFrame: false, forceRender: true });
  window.__PIXEL_GLOBE_CAPTURE_RENDERED_TEXT__ = [...captureRenderedTextRecords.values()];
  return document.documentElement.lang;
}

function stepAutomaticCaptureFrame(frameIndex) {
  if (!CAPTURE_FRAME_PASS) throw new Error("Frame stepping is unavailable outside the frame pass");
  const step = advanceAutomaticFrameStepper(captureFrameStepper, frameIndex);
  runFrame(step.nowMs, { scheduleNextFrame: false, forceRender: true });
  if (!step.complete && captureFrameStepper.nextIndex % captureFrameStepper.frameRate === 0) {
    emitCaptureEvent("position", capturePositionEventData());
  }
  const complete = captureDirectorComplete(captureDirector);
  if (complete !== step.complete) {
    throw new Error(
      `Capture completion mismatch at ${captureFrameStepper.nextIndex}/` +
      `${captureFrameStepper.totalFrames}: ${complete}`
    );
  }
  return Object.freeze({
    frameIndex,
    totalFrames: captureFrameStepper.totalFrames,
    complete
  });
}

function stageCaptureSequence() {
  if (!captureDirector) throw new Error("Cannot stage capture without a director");
  const sequence = captureDirector.sequence;
  gameState.memory.flags.oarTutorialShown = true;
  gameState.memory.flags.sailingBasicsTutorialShown = true;
  gameState.memory.flags.tackingTutorialShown = true;
  stageCaptureDiscoveryMemory(sequence);
  if (sequence.kind === "explore") {
    const discovery = captureDiscoveryByName(sequence.discoveryName);
    if (sequence.riverStart) placeCapturePlayerNearRiverCoordinates(sequence.riverStart);
    captureDirector.steeringTarget = captureSequenceSailingTarget(sequence) || discoveryDirection(discovery);
  } else if (sequence.kind === "trade") {
    const city = captureCityByName(sequence.cityName);
    placeCapturePlayerNearTile(city.tileId);
    gameState.doubloons = 12_000;
    if (sequence.variant === "sell") {
      const good = tradeGoodById(sequence.goodId);
      const quantity = sequence.transactionCount;
      if (quantity * good.unitSize > cargoFree(gameState)) {
        throw new Error(`Capture ship has no room for ${quantity} ${good.label} transactions`);
      }
      gameState.cargo[good.id] = quantity;
      gameState.accounts.cargoCostBasis[good.id] = quantity * Math.max(1, Math.round(good.basePrice * 0.2));
    }
    syncShipCargoFromGameState();
  } else if (sequence.kind === "fish") {
    stageCaptureFishingGround();
  } else if (sequence.kind === "whale") {
    stageCaptureWhale(sequence);
  } else if (sequence.kind === "sail") {
    stageCaptureSailing(sequence);
  } else if (sequence.kind === "fight") {
    maximizeCaptureCombatLoadout();
  } else if (sequence.kind === "pillage") {
    stageCapturePillage(sequence);
  } else if (sequence.kind === "colonize") {
    stageCaptureColonization(sequence);
  } else if (sequence.kind === "survive") {
    stageCaptureSurvival(sequence);
  } else if (sequence.kind === "panda") {
    stageCapturePanda(sequence);
  } else {
    throw new Error(`Unknown capture sequence kind: ${sequence.kind}`);
  }
  dirty = true;
}

function captureSequenceSailingTarget(sequence) {
  const target = sequence.sailingTarget;
  return target ? latLonToDirection(target.lat, target.lon) : null;
}

function stageCaptureDiscoveryMemory(sequence) {
  const featuredDiscovery = sequence.kind === "explore"
    ? captureDiscoveryByName(sequence.discoveryName)
    : null;
  for (const discovery of discoveryCatalog) {
    if (discovery.id === featuredDiscovery?.id) continue;
    recordDiscovery(gameState, discovery);
  }
}

function updateCaptureDirectorFrame(nowMs) {
  if (CAPTURE_FRAME_PASS) {
    captureDirector.elapsedSeconds = captureFrameStepper.nextIndex / captureFrameStepper.frameRate;
    captureDirector.lastWallClockMs = nowMs;
  } else {
    advanceCaptureDirectorClock(captureDirector, nowMs);
  }
  const sequence = captureDirector.sequence;
  if (sequence.kind === "explore") updateCaptureExplore(sequence, nowMs);
  else if (sequence.kind === "trade") updateCaptureTrade(sequence);
  else if (sequence.kind === "fish") updateCaptureFishing(sequence);
  else if (sequence.kind === "whale") updateCaptureWhale(sequence);
  else if (sequence.kind === "sail") updateCaptureSailing(sequence);
  else if (sequence.kind === "fight") updateCaptureFight(sequence);
  else if (sequence.kind === "pillage") updateCapturePillage(sequence);
  else if (sequence.kind === "colonize") updateCaptureColonization(sequence);
  else if (sequence.kind === "survive") updateCaptureSurvival(sequence);
  else if (sequence.kind === "panda") updateCapturePanda(sequence);
  else throw new Error(`Unknown capture sequence kind: ${sequence.kind}`);

  if (!captureDirector.stopping && captureDirectorComplete(captureDirector)) {
    captureDirector.stopping = true;
    capturePlaybackPaused = true;
    if (CAPTURE_FRAME_PASS) {
      emitCaptureEvent("capture-stop", { reason: "sequence-complete" });
      window.__PIXEL_GLOBE_CAPTURE_SIDECAR__ = Object.freeze({
        version: 2,
        scenario: CAPTURE_SCENARIO,
        durationMs: Math.round(captureDirector.sequence.durationSeconds * 1000),
        events: deterministicCaptureEvents.slice()
      });
      window.__PIXEL_GLOBE_CAPTURE_COMPLETE__ = true;
      return;
    }
    throw new Error("Scripted capture completed outside deterministic frame mode");
  }
}

function updateCaptureExplore(sequence, nowMs) {
  if (captureCue("approach", 0.3)) {
    emitCaptureEvent("capture-beat", { action: "approach-discovery", name: sequence.discoveryName });
  }
  if (captureCue("discover", 3.2)) {
    const discovery = captureDiscoveryByName(sequence.discoveryName);
    if (!queueDiscovery(discovery, nowMs)) {
      throw new Error(`Capture discovery was already recorded: ${sequence.discoveryName}`);
    }
  }
  if (captureCue("dismiss-discovery", 5.4) && captainAlertModal) closeCaptainAlertModal();
}

function updateCaptureTrade(sequence) {
  if (captureCue("open-market", 0.7)) {
    const cityCall = capturePortCallByName(sequence.cityName);
    dialogueState = createPortDialogueSession(cityCall, {
      initialNodeId: sequence.variant === "buy" ? "buy" : "sell",
      admittedToPort: true
    });
    dialogueLayout = createDialogueLayoutState();
    stopShipForDialogue();
    ensureDialoguePortraitLoaded();
    emitCaptureEvent("capture-beat", { action: `market-${sequence.variant}`, city: sequence.cityName });
    dirty = true;
  }
  for (let index = 0; index < sequence.transactionCount; index += 1) {
    const atSeconds = 1.45 + index * 0.36;
    if (captureCue(`trade-${index + 1}`, atSeconds)) captureChooseTradeGood(sequence);
  }
}

function updateCaptureFishing(sequence) {
  if (captainAlertModal) closeCaptainAlertModal();
  if (!captureCue("cast-net", 1.0)) return;
  const call = activeFishCall();
  if (!call) throw new Error(`Capture ${sequence.variant} fishing ground has no fish in reach`);
  if (!catchFishAtFishery(call)) throw new Error(`Capture ${sequence.variant} fishing cast could not start`);
  fishingAction.catchSucceeded = true;
  emitCaptureEvent("capture-beat", { action: "fish", species: call.label, variant: sequence.variant });
}

function updateCaptureWhale(sequence) {
  if (sequence.variant === "harpoon") {
    if (captureCue("harpoon", 1.1)) {
      const call = activeWhaleCall();
      if (!call) throw new Error(`Capture whale is not harpoonable: ${sequence.speciesId}`);
      if (!startWhaleHarpoon(call)) throw new Error(`Capture harpoon could not be thrown: ${sequence.speciesId}`);
      emitCaptureEvent("capture-beat", { action: "harpoon-whale", speciesId: sequence.speciesId });
    }
    if (captureCue("dismiss-tow", 5.2) && captainAlertModal) closeCaptainAlertModal();
    return;
  }
  if (captureCue("exhaust-whale", 2.2)) {
    const whale = exhaustTetheredWhale(gameState.memory.whales);
    openCaptainAlertModal(WHALE_EXHAUSTED_MESSAGE, WHALE_EXHAUSTED_EXPRESSION_ID);
    emitCaptureEvent("capture-beat", { action: "exhaust-whale", speciesId: whale.speciesId });
  }
  if (captureCue("dismiss-exhausted", 3.2) && captainAlertModal) closeCaptainAlertModal();
  if (captureCue("killing-blow", 4.0)) {
    const hunt = gameState.memory.whales.activeHunt;
    if (!hunt) throw new Error("Capture finishing shot lost its whale hunt");
    const whale = whaleById(gameState.memory.whales, hunt.whaleId);
    if (whale.phase !== WHALE_PHASE_EXHAUSTED) {
      throw new Error(`Capture whale did not exhaust on cue: ${whale.phase}`);
    }
    landWhaleKillingBlow();
    emitCaptureEvent("capture-beat", { action: "land-whale-killing-blow", speciesId: sequence.speciesId });
  }
  if (captureCue("dismiss-kill", 7.0) && captainAlertModal) closeCaptainAlertModal();
}

function updateCaptureSailing(sequence) {
  dismissCaptureOverlays();
  if (!captureCue("beam-reach", 0.1)) return;
  const performance = captureBeamReachPerformance();
  emitCaptureEvent("capture-beat", {
    action: "beam-reach",
    shipSlug: ship.typeSlug,
    beamSide: sequence.beamSide,
    angleFromWindDeg: Math.round(performance.angleFromWindDeg * 10) / 10,
    attainableSpeedRatio: Math.round(performance.attainableSpeedRatio * 1000) / 1000,
    hullTopSpeedRatio: Math.round(performance.hullTopSpeedRatio * 1000) / 1000
  });
}

function updateCaptureFight(sequence) {
  if (captureDirector.elapsedSeconds >= 1.2) dismissCaptureOverlays();
  const target = npcVisualShips.get(sequence.encounterId);
  if (!target) return;
  if (captureCue("engage", 0.8)) {
    forceShipEngagement(shipCombatState, PLAYER_COMBAT_ID, target.id);
    emitCaptureEvent("capture-beat", { action: "engage-ship", targetId: target.id });
  }
  captureDirector.steeringTarget = captureCombatOrbitTarget(target);
  if (captureDirector.elapsedSeconds >= 1.4) {
    fireBroadside("port");
    fireBroadside("starboard");
  }
}

function dismissCaptureOverlays() {
  if (!dialogueState && !captainAlertModal) return false;
  dialogueState = null;
  dialogueLayout = createDialogueLayoutState();
  captainAlertModal = null;
  resumeShipAfterOverlayIfReady();
  dirty = true;
  return true;
}

function updateCapturePillage(sequence) {
  const cityCall = capturePortCallByName(sequence.cityName);
  const battery = ensureShoreBatteryState(cityCall);
  if (sequence.variant === "bombard") {
    battery.engagedTargetIds.add(PLAYER_COMBAT_ID);
    if (captureCue("fire-on-port", 1.0)) {
      fireBroadside("port");
      fireBroadside("starboard");
      emitCaptureEvent("capture-beat", { action: "bombard-port", city: sequence.cityName });
    }
    if (captureCue("disable-battery", 2.6)) {
      damageShoreBattery(
        battery,
        gameState.memory.flags,
        Math.max(1, battery.hitPoints),
        Math.floor(weatherClockMinutes),
        shoreBatteryAttackerShipLabel(PLAYER_COMBAT_ID)
      );
      showSurvivalNotice(shoreBatteryDisabledNotice(battery), "good");
      dirty = true;
    }
    return;
  }
  if (captureCue("open-assault", 2.2)) openPortDialogue(cityCall);
  if (captureCue("land-marines", 2.3)) {
    attemptPlayerPortConquest(cityCall, () => 0);
    emitCaptureEvent("capture-beat", { action: "land-marines", city: sequence.cityName });
  }
  if (captureCue("dismiss-conquest", 4.3)) {
    if (captainAlertModal) closeCaptainAlertModal();
    if (dialogueState) closeDialogue();
  }
}

function updateCaptureColonization(sequence) {
  if (captureCue("open-colony", 2.2)) openPortDialogue(capturePortCallByName(sequence.cityName));
  if (captureCue("complete-colony-action", 2.3)) {
    const actionType = sequence.variant === "found" ? "land-colonists" : "deliver-colony-resupply";
    captureChooseDialogueAction(actionType);
    playSoundEffect(soundEffects?.discoverySuccess, 0.68, 1);
    emitCaptureEvent("capture-beat", { action: actionType, city: sequence.cityName });
  }
  if (captureCue("reveal-colony", 4.3)) {
    if (captainAlertModal) closeCaptainAlertModal();
    if (dialogueState) closeDialogue();
  }
}

function updateCaptureSurvival(sequence) {
  if (sequence.variant === "lightning") {
    if (captureCue("clear-warning", 0.8) && captainAlertModal) closeCaptainAlertModal();
    if (captureCue("lightning-strike", 1.7)) {
      if (!triggerStormShipStrike(stormShipStrikeState, lastFrameMs)) {
        throw new Error("Capture lightning strike was still on cooldown");
      }
      const damage = Math.max(1, Math.round(ship.maxHitPoints * 0.16));
      ship.hitPoints = Math.max(1, ship.hitPoints - damage);
      stormDamageNotice = {
        damage,
        intensity: 0.96,
        expiresAtMs: lastFrameMs + NOTICE_DURATION_MS.stormDamage
      };
      emitCaptureEvent("storm-damage", {
        damage,
        intensity: 0.96,
        remainingHitPoints: ship.hitPoints
      });
      emitCaptureEvent("capture-beat", { action: "lightning-strike" });
      dirty = true;
    }
    if (captureCue("steady-after-strike", 6.0) && captainAlertModal) closeCaptainAlertModal();
    return;
  }
  if (captureCue("out-of-water", 0.3)) {
    showSurvivalNotice("NO FRESH WATER", "warn");
    playSoundEffect(soundEffects?.scavengeFailure, 0.55, 0.9);
    emitCaptureEvent("capture-beat", { action: "fresh-water-empty" });
  }
  if (captureDirector.elapsedSeconds >= 1.0 && captainAlertModal) closeCaptainAlertModal();
}

function updateCapturePanda(sequence) {
  if (sequence.variant === "sail") {
    if (captureCue("panda-sailing", 0.1)) {
      emitCaptureEvent("capture-beat", {
        action: "sail-with-panda",
        shipSlug: ship.typeSlug,
        beamSide: sequence.beamSide
      });
    }
    return;
  }
  if (sequence.variant === "fish") {
    if (!captureCue("panda-fishing", 1.0)) return;
    const call = activeFishCall();
    if (!call) throw new Error("Panda trailer fishing ground has no fish in reach");
    if (!catchFishAtFishery(call)) throw new Error("Panda trailer fishing cast could not start");
    fishingAction.catchSucceeded = true;
    emitCaptureEvent("capture-beat", { action: "fish-with-panda", species: call.label });
    return;
  }
  if (sequence.variant === "encounter") {
    if (captureCue("meet-panda", 1.0)) {
      if (!recordAnimalEncounter(gameState.memory.animals, "panda")) {
        throw new Error("Panda trailer could not record the panda encounter");
      }
      presentAnchoredAnimalEncounter(ANIMAL_CATALOG_BY_ID.get("panda"));
      emitCaptureEvent("capture-beat", { action: "meet-panda", city: sequence.cityName });
    }
    for (const [cueId, atSeconds] of [
      ["panda-call-read", 4.0],
      ["panda-commentary-read", 7.0],
      ["panda-reaction-read", 10.0]
    ]) {
      if (captureCue(cueId, atSeconds)) closeRequiredCaptureAlert(cueId);
    }
    if (captureCue("welcome-panda", 13.0)) {
      if (captainAlertModal?.kind !== "choice") {
        throw new Error("Panda trailer recruitment choice did not open");
      }
      activateCaptainAlertChoice();
      emitCaptureEvent("capture-beat", { action: "welcome-panda-aboard" });
    }
    if (captureCue("panda-aboard-call-read", 16.3)) {
      closeRequiredCaptureAlert("panda-aboard-call-read");
    }
    return;
  }
  if (sequence.variant === "port-reaction") {
    if (captureCue("panda-port-reaction", 0.8)) {
      const cityCall = capturePortCallByName(sequence.cityName);
      if (!maybeOpenAnimalCompanionNpcReaction(`capture:panda:${sequence.cityName}`, cityCall.character)) {
        throw new Error(`Panda trailer could not open the ${sequence.cityName} reaction`);
      }
      emitCaptureEvent("capture-beat", { action: "panda-port-reaction", city: sequence.cityName });
    }
    if (captureCue("panda-port-line-read", 4.4)) {
      closeRequiredCaptureAlert("panda-port-line-read");
    }
    return;
  }
  if (sequence.variant === "naturalist") {
    if (captureCue("naturalist-offer", 0.8)) {
      const cityCall = capturePortCallByName(sequence.cityName);
      if (!maybeOpenNaturalistPortDialogue(cityCall)) {
        throw new Error("Panda trailer could not open the naturalist offer");
      }
      emitCaptureEvent("capture-beat", { action: "naturalist-offers-for-panda", city: sequence.cityName });
    }
    for (const [cueId, atSeconds] of [
      ["naturalist-intro-read", 4.1],
      ["panda-naturalist-reply-read", 6.8],
      ["naturalist-price-read", 10.6]
    ]) {
      if (captureCue(cueId, atSeconds)) closeRequiredCaptureAlert(cueId);
    }
    return;
  }
  throw new Error(`Unknown panda capture variant: ${sequence.variant}`);
}

function closeRequiredCaptureAlert(cueId) {
  if (!captainAlertModal) throw new Error(`Capture cue ${cueId} has no alert to advance`);
  closeCaptainAlertModal();
}

function captureCue(id, atSeconds) {
  return captureDirectorCue(captureDirector, id, atSeconds);
}

function captureAutopilotHeading() {
  const target = captureDirector?.steeringTarget;
  if (!target || !ship?.position) return null;
  const toward = projectTangentVector([
    target[0] - ship.position[0],
    target[1] - ship.position[1],
    target[2] - ship.position[2]
  ], ship.position);
  return normalizeTangentOrFallback(toward, ship.position, ship.heading);
}

function captureCombatOrbitTarget(target) {
  const toward = normalizeOrNull(projectTangentVector([
    target.vector[0] - ship.position[0],
    target.vector[1] - ship.position[1],
    target.vector[2] - ship.position[2]
  ], ship.position));
  if (!toward) return target.vector;
  const port = normalizeOrNull(cross3(ship.position, toward));
  if (!port) return target.vector;
  const starboard = scaleVector(port, -1);
  const orbitHeading = dot3(ship.heading, port) >= dot3(ship.heading, starboard) ? port : starboard;
  return normalize3([
    ship.position[0] + orbitHeading[0] * 0.08,
    ship.position[1] + orbitHeading[1] * 0.08,
    ship.position[2] + orbitHeading[2] * 0.08
  ]);
}

function captureDiscoveryByName(name) {
  const matches = discoveryCatalog.filter((entry) => entry.displayName === name);
  if (matches.length !== 1) throw new Error(`Capture discovery ${name} matched ${matches.length} entries`);
  return matches[0];
}

function captureCityByName(name) {
  const matches = portCities.filter((city) => cityLabelText(city) === name || city.city === name);
  if (matches.length !== 1) throw new Error(`Capture city ${name} matched ${matches.length} ports`);
  return matches[0];
}

function capturePortCallByName(name) {
  const matches = (chart?.cityCalls || []).filter((city) => cityLabelText(city) === name || city.city === name);
  if (matches.length !== 1) throw new Error(`Capture city ${name} matched ${matches.length} visible calls`);
  return matches[0];
}

function placeCapturePlayerNearTile(tileId) {
  if (!Number.isInteger(tileId)) throw new Error(`Invalid capture destination tile: ${tileId}`);
  const candidates = [tileId, ...(graph.neighbors[tileId] || [])];
  const navigableTileId = candidates.find((candidate) => isShipBaseNavigableTile(candidate));
  if (!Number.isInteger(navigableTileId)) {
    throw new Error(`Capture destination has no navigable tile: ${tileId}`);
  }
  placeCapturePlayerOnTile(navigableTileId);
}

function placeCapturePlayerNearRiverCoordinates(coordinates) {
  const requested = latLonToDirection(coordinates.lat, coordinates.lon);
  const requestedTileId = findNearestTileId(graph, directionIndex, requested);
  const riverTileId = nearestTileMatching(requestedTileId, shipTileHasRiver);
  if (!Number.isInteger(riverTileId)) {
    throw new Error(`Capture river start has no river tile near ${coordinates.lat}, ${coordinates.lon}`);
  }
  const distancePx = vectorArcDistance(requested, tileCenterVector(riverTileId)) * PIXELS_PER_RADIAN;
  if (distancePx > 48) {
    throw new Error(
      `Capture river start resolved ${distancePx.toFixed(1)}px from ${coordinates.lat}, ${coordinates.lon}`
    );
  }
  placeCapturePlayerOnTile(riverTileId);
}

function placeCapturePlayerOnTile(navigableTileId) {
  if (!isShipBaseNavigableTile(navigableTileId)) {
    throw new Error(`Capture player tile is not navigable: ${navigableTileId}`);
  }
  ship.position = tileCenterVector(navigableTileId);
  ship.tileId = navigableTileId;
  ship.velocity = [0, 0, 0];
  applyCaptureShipHeading(ship, CAPTURE_SCENARIO.player.headingDeg);
  camera = northUpCamera(ship.position);
  centerTileId = ship.tileId;
  localLayout = createLocalLayout(centerTileId);
  chart = buildChart(camera);
  refreshWeatherState(true);
  resetPlayerWindState();
}

function stageCaptureFishingGround() {
  const fishingTile = chart.tileCalls
    .filter((call) => fisheryForTileCall(call))
    .map((call) => ({
      call,
      distance: Math.acos(clamp(dot3(ship.position, tileCenterVector(call.id)), -1, 1))
    }))
    .sort((a, b) => a.distance - b.distance)[0]?.call;
  if (!fishingTile) throw new Error("Capture location has no visible fishery");
  placeCapturePlayerNearTile(fishingTile.id);
  if (!hasShipItem(gameState, SHIP_ITEM_FISHING_NET)) {
    throw new Error("Capture fishing ship has no fishing net");
  }
}

function stageCaptureWhale(sequence) {
  gameState.inventory.whaleHarpoonId = BASIC_WHALE_HARPOON_ID;
  const whale = gameState.memory.whales.individuals.find((entry) => (
    entry.speciesId === sequence.speciesId && entry.lifeStage === "adult" && entry.id !== WHITE_WHALE_ID
  ));
  if (!whale) throw new Error(`Capture whale species is unavailable: ${sequence.speciesId}`);
  const placement = captureWhalePlacement();
  whale.position = placement.position;
  whale.tileId = placement.tileId;
  whale.heading = normalizeTangentOrFallback(scaleVector(camera.right, -1), whale.position, ship.heading);
  whale.phase = WHALE_PHASE_SURFACED;
  whale.phaseElapsedSeconds = 0;
  whale.phaseDurationSeconds = 30;
  captureDirector.steeringTarget = whale.position;
  if (sequence.variant === "finish") {
    const harpoon = playerWhaleHarpoon(gameState);
    tetherWhale(gameState.memory.whales, whale.id, harpoon);
    gameState.memory.whales.activeHunt.remainingSeconds = 8;
  }
}

function stageCaptureSailing(sequence) {
  const windFlow = windFlowVectorAtShip(windForShip());
  const starboardBeam = normalizeOrNull(cross3(ship.position, windFlow));
  if (!starboardBeam) throw new Error("Capture beam reach could not resolve a sailing heading");
  const beamHeading = sequence.beamSide === "starboard"
    ? starboardBeam
    : scaleVector(starboardBeam, -1);
  ship.heading = beamHeading;
  ship.targetHeading = beamHeading.slice();
  const performance = captureBeamReachPerformance();
  ship.velocity = scaleVector(beamHeading, performance.attainableSpeedRad * 0.96);
  captureDirector.steeringTarget = normalize3([
    ship.position[0] + beamHeading[0] * 0.4,
    ship.position[1] + beamHeading[1] * 0.4,
    ship.position[2] + beamHeading[2] * 0.4
  ]);
}

function captureBeamReachPerformance() {
  const stats = currentPlayerEffectiveShipStats();
  const wind = windForShip();
  const windFlow = windFlowVectorAtShip(wind);
  const alignment = clamp(dot3(ship.heading, windFlow), -1, 1);
  const propulsion = shipPropulsionPerformance(stats, {
    windStrength: wind.strength,
    sailEfficiency: sailingEfficiencyForStats(stats, ship.heading, windFlow),
    minimumSailSpeed: SHIP_MINIMUM_POWERED_SPEED_RAD,
    rowerRatio: playerRowerRatio()
  });
  const speedRad = vectorLength(ship.velocity);
  return {
    angleFromWindDeg: Math.acos(clamp(-alignment, -1, 1)) * 180 / Math.PI,
    attainableSpeedRad: propulsion.maxSpeedRad,
    attainableSpeedRatio: speedRad / propulsion.maxSpeedRad,
    hullTopSpeedRatio: speedRad / stats.topSpeedRad
  };
}

function captureWhalePlacement() {
  const directions = [camera.right, scaleVector(camera.right, -1), camera.up, scaleVector(camera.up, -1)];
  for (const radiusPx of [24, 20, 16, 28, 32]) {
    for (const direction of directions) {
      const position = normalize3([
        ship.position[0] + direction[0] * radiusPx / PIXELS_PER_RADIAN,
        ship.position[1] + direction[1] * radiusPx / PIXELS_PER_RADIAN,
        ship.position[2] + direction[2] * radiusPx / PIXELS_PER_RADIAN
      ]);
      const navigation = whaleNavigationAtPosition(position);
      if (navigation.ok && navigation.canSurface) return { position, tileId: navigation.tileId };
    }
  }
  throw new Error("Capture whale could not be placed in visible open water");
}

function maximizeCaptureCombatLoadout() {
  gameState.ship.crew = gameState.ship.crewCapacity;
  gameState.ship.cannons = gameState.ship.cannonCapacity;
  syncShipCargoFromGameState();
}

function stageCapturePillage(sequence) {
  const city = captureCityByName(sequence.cityName);
  placeCapturePlayerNearTile(city.tileId);
  maximizeCaptureCombatLoadout();
  const call = capturePortCallByName(sequence.cityName);
  const battery = ensureShoreBatteryState(call);
  markPlayerPortAssault(gameState.memory.flags, call, weatherClockMinutes + WEATHER_MINUTES_PER_DAY);
  if (sequence.variant === "assault") {
    damageShoreBattery(
      battery,
      gameState.memory.flags,
      battery.maxHitPoints,
      Math.floor(weatherClockMinutes),
      shoreBatteryAttackerShipLabel(PLAYER_COMBAT_ID)
    );
    const status = playerPortConquestStatus(call);
    if (!status.canAttempt) {
      throw new Error(
        `Capture assault is ineligible at ${sequence.cityName}: ` +
        `crew ${gameState.ship.crew}/${gameState.ship.crewCapacity}, battery disabled ${status.batteryDisabled}`
      );
    }
  }
}

function stageCaptureColonization(sequence) {
  const memory = gameState.memory.colonization;
  if (!colonizationQuestView(gameState, { currentMinute: weatherClockMinutes }).target) {
    const target = colonizationTargetPlacements.find((candidate) => candidate.city === sequence.cityName);
    const origin = portCities.find((candidate) => candidate.city === "Bordeaux" && candidate.country === "France");
    if (!target || !origin) throw new Error("Capture colonization requires Port Royal and Bordeaux");
    assignColonizationQuest(memory, { target, origin });
    colonizationTargetTileId = target.tileId;
    ensureColonizationOrganizer(gameState, origin);
  }
  for (const stage of COLONIZATION_FETCH_STAGES) completeColonizationFetchStage(memory, stage.id);
  if (memory.stage !== COLONIZATION_STAGE_READY) {
    throw new Error(`Capture colonization fetch setup ended at ${memory.stage}`);
  }
  reserveCargoSpace(gameState, COLONIZATION_CARGO_RESERVATION_ID, 24);
  beginColonizationExpedition(memory);
  if (sequence.variant === "establish") {
    releaseCargoSpace(gameState, COLONIZATION_CARGO_RESERVATION_ID);
    landColonists(memory, Math.floor(weatherClockMinutes) - WEATHER_MINUTES_PER_DAY * 30);
    advanceColonizationQuest(memory, Math.floor(weatherClockMinutes), { awayFromColony: true });
    gameState.cargo[COLONIZATION_RESUPPLY.goodId] = COLONIZATION_RESUPPLY.quantity;
    gameState.accounts.cargoCostBasis[COLONIZATION_RESUPPLY.goodId] = 120;
  }
  syncColonizationWorldState(gameState, { startMinute: weatherClockMinutes });
  placeCapturePlayerNearTile(memory.targetTileId);
  steerCapturePlayerIntoClearWater(memory.targetTileId);
  syncShipCargoFromGameState();
}

function steerCapturePlayerIntoClearWater(tileId) {
  const shore = tileCenterVector(tileId);
  const preferredHeading = normalizeOrNull(projectTangentVector([
    ship.position[0] - shore[0],
    ship.position[1] - shore[1],
    ship.position[2] - shore[2]
  ], ship.position));
  if (!preferredHeading) throw new Error(`Capture could not resolve a departure heading from ${tileId}`);
  const originalHeading = ship.heading;
  let clearHeading = null;
  for (const degrees of [0, 30, -30, 60, -60, 90, -90, 120, -120, 150, -150, 180]) {
    const candidate = rotateTangentDirection(preferredHeading, ship.position, degrees * Math.PI / 180);
    ship.heading = candidate;
    const step = scaleVector(candidate, 36 / PIXELS_PER_RADIAN);
    if (attemptShipStep(ship.position, ship.tileId, step).ok) {
      clearHeading = candidate;
      break;
    }
  }
  if (!clearHeading) {
    ship.heading = originalHeading;
    throw new Error(`Capture could not find 36px of clear departure water from ${tileId}`);
  }
  ship.heading = clearHeading;
  ship.targetHeading = clearHeading.slice();
  ship.velocity = [0, 0, 0];
  captureDirector.steeringTarget = normalize3([
    ship.position[0] + clearHeading[0] * 0.25,
    ship.position[1] + clearHeading[1] * 0.25,
    ship.position[2] + clearHeading[2] * 0.25
  ]);
}

function stageCaptureSurvival(sequence) {
  if (sequence.variant === "lightning") {
    captureDirector.steeringTarget = normalize3([
      ship.position[0] + ship.heading[0] * 0.1,
      ship.position[1] + ship.heading[1] * 0.1,
      ship.position[2] + ship.heading[2] * 0.1
    ]);
    return;
  }
  gameState.survival.freshWater = 0;
  gameState.ship.crew = Math.min(6, gameState.ship.crewCapacity);
  survivalDeprivationTimers.waterNextMinute = weatherClockMinutes + SURVIVAL_DEHYDRATION_INTERVAL_MINUTES;
  syncShipCargoFromGameState();
}

function stageCapturePanda(sequence) {
  if (sequence.variant === "encounter") {
    const city = captureCityByName(sequence.cityName);
    placeCapturePlayerNearTile(city.tileId);
    anchored = true;
    initialAnimalEncounterRollPending = false;
    gameState.memory.animals.nextRollMinute = weatherClockMinutes + WEATHER_MINUTES_PER_DAY;
    stopShipMotion();
    return;
  }

  if (sequence.pandaAboard !== false) stageCapturePandaAboard();
  if (sequence.variant === "sail") {
    stageCaptureSailing(sequence);
    return;
  }
  if (sequence.variant === "fish") {
    stageCaptureFishingGround();
    return;
  }
  if (sequence.variant === "port-reaction") {
    placeCapturePlayerNearTile(captureCityByName(sequence.cityName).tileId);
    return;
  }
  if (sequence.variant === "naturalist") {
    const city = captureCityByName(sequence.cityName);
    const memory = gameState.memory.quests.naturalist;
    memory.portTileId = city.tileId;
    memory.met = true;
    memory.reportedAnimalIds = [...ANIMAL_CATALOG_BY_ID.keys()];
    memory.completionRewarded = true;
    naturalistCharacter = null;
    ensureNaturalistCharacter(gameState, {
      portraitSourceId: sequence.naturalistPortraitSourceId || null
    });
    placeCapturePlayerNearTile(city.tileId);
    return;
  }
  throw new Error(`Unknown panda capture staging variant: ${sequence.variant}`);
}

function stageCapturePandaAboard() {
  if (!gameState.memory.animals.encountered.panda) {
    if (!recordAnimalEncounter(gameState.memory.animals, "panda")) {
      throw new Error("Panda trailer could not record the panda encounter");
    }
  }
  if (!aboardAnimalCompanionIds(gameState.memory.animalCompanions).includes("panda")) {
    beginAnimalCompanionRecruitment(gameState.memory.animalCompanions, "panda");
    acceptAnimalCompanion(gameState.memory.animalCompanions, "panda", weatherClockMinutes);
  }
}

function captureChooseTradeGood(sequence) {
  if (!dialogueState) throw new Error("Capture trade menu closed before the transaction");
  const view = currentDialogueView();
  const index = view.options.findIndex((entry) => (
    entry.action?.type === sequence.variant && entry.action.goodId === sequence.goodId && !entry.disabled
  ));
  if (index < 0) {
    throw new Error(`Capture market has no enabled ${sequence.variant} action for ${sequence.goodId}`);
  }
  chooseDialogueOption(index);
  emitCaptureEvent("capture-beat", {
    action: sequence.variant,
    city: sequence.cityName,
    goodId: sequence.goodId
  });
}

function captureChooseDialogueAction(actionType) {
  if (!dialogueState) throw new Error(`Capture dialogue closed before ${actionType}`);
  const view = currentDialogueView();
  const index = view.options.findIndex((entry) => entry.action?.type === actionType && !entry.disabled);
  if (index < 0) throw new Error(`Capture dialogue has no enabled ${actionType} action`);
  chooseDialogueOption(index);
}

function randomPlayerCharacterIdentitySeed() {
  const values = new Uint32Array(3);
  if (window.crypto?.getRandomValues) {
    window.crypto.getRandomValues(values);
  } else {
    for (let i = 0; i < values.length; i++) {
      values[i] = Math.floor(Math.random() * 0x100000000) >>> 0;
    }
  }
  return Array.from(values, (value) => value.toString(36)).join("-");
}

function setMusicVolume(value) {
  optionsMenu.musicVolume = Math.round(clamp(value, 0, 1) * 100) / 100;
  writeLocalStorage(MUSIC_VOLUME_STORAGE_KEY, String(optionsMenu.musicVolume));
  applyThemeAudioSettings();
  ensureGameAudioStarted();
  dirty = true;
}

function setSfxVolume(value) {
  optionsMenu.sfxVolume = Math.round(clamp(value, 0, 1) * 100) / 100;
  writeLocalStorage(SFX_VOLUME_STORAGE_KEY, String(optionsMenu.sfxVolume));
  applyThemeAudioSettings();
  ensureGameAudioStarted();
  dirty = true;
}

function setControllerGlyphPreference(value) {
  const normalized = normalizeControllerGlyphPreference(value);
  optionsMenu.controllerGlyphPreference = normalized;
  writeLocalStorage(CONTROLLER_GLYPH_STORAGE_KEY, normalized);
  activeControllerFamily = controllerFamilyForGamepad(
    activeControllerGamepad,
    normalized,
    activeControllerGamepad
      ? steamInputTypeFromBridge(window.marqueSteamInput ?? null, activeControllerGamepad.index)
      : null
  );
  dirty = true;
}

function setControlScheme(value) {
  const normalized = normalizeControlScheme(value);
  optionsMenu.controlScheme = normalized;
  optionsMenu.controlSchemeSelectedIndex = normalized === CONTROL_SCHEME_RELATIVE ? 1 : 0;
  writeLocalStorage(CONTROL_SCHEME_STORAGE_KEY, normalized);
  dirty = true;
}

function setAudioMuted(muted) {
  optionsMenu.muted = !!muted;
  writeLocalStorage(AUDIO_MUTED_STORAGE_KEY, String(optionsMenu.muted));
  applyThemeAudioSettings();
  ensureGameAudioStarted();
  dirty = true;
}

function toggleAudioMuted() {
  setAudioMuted(!optionsMenu.muted);
}

async function loadShipAssetSet(slug) {
  if (!shipLightingAssetStore) throw new Error("Ship lighting asset store is not initialized");
  const [spriteAsset, loadedShipLighting] = await Promise.all([
    requestShipVisualAssets(slug),
    shipLightingAssetStore.request(slug)
  ]);
  return Object.freeze({
    ...spriteAsset,
    lighting: loadedShipLighting
  });
}

function applyPlayerShipType(slug, stats, assets, { stateAlreadyUpdated = false } = {}) {
  shipImage = assets.image;
  shipSinkDepthImage = assets.sinkDepthImage;
  shipWakeAnchors = requiredShipWakeAnchors(slug);
  shipLighting = assets.lighting;
  if (ship) {
    if (gameState && !stateAlreadyUpdated) setPlayerShipStats(gameState, stats);
    ship.typeSlug = slug;
    ship.stats = stats;
    ship.hitPoints = stats.hitPoints;
    ship.maxHitPoints = stats.hitPoints;
    ship.cargoCapacity = gameState?.cargoCapacity || stats.cargoCapacity;
    ship.cargoUsed = gameState ? cargoUsed(gameState) : Math.min(ship.cargoUsed || 0, stats.cargoCapacity);
    ship.wakeParticles = [];
    ship.lastWakeEmit = null;
    ship.navalProjectiles = [];
    ship.cannonSplashes = [];
    cannonSmokeBursts = [];
    hullSplinterBursts = [];
    ship.cannonCooldowns = {
      port: 0,
      starboard: 0
    };
    ship.portableWeaponCooldowns = {};
    ship.woundedCrew = 0;
  }
  syncShipSlugToLocation(slug);
  dirty = true;
}

function syncShipSlugToLocation(slug) {
  const url = new URL(window.location.href);
  url.searchParams.set("ship", slug);
  window.history.replaceState(null, "", url);
}

function loadShipInfoImage(slug) {
  const cached = shipInfoImages.get(slug);
  if (cached) return Promise.resolve(cached);
  const pending = shipInfoImagePromises.get(slug);
  if (pending) return pending;
  shipStatsForSlug(slug);
  const promise = loadAssetImage(
    `assets/vehicles/unity-ships/side-views/${slug}.png?v=${SHIP_INFO_ASSET_VERSION}`,
    `ship side view: ${slug}`
  ).then((image) => {
    validateImageDimensions(
      image,
      `Ship side view: ${slug}`,
      SHIP_INFO_SIDE_VIEW_W,
      SHIP_INFO_SIDE_VIEW_H
    );
    shipInfoImages.set(slug, image);
    shipInfoImagePromises.delete(slug);
    return image;
  }).catch((error) => {
    shipInfoImagePromises.delete(slug);
    throw error;
  });
  shipInfoImagePromises.set(slug, promise);
  return promise;
}

function openShipInfoMenu() {
  if (!ship || !gameState) throw new Error("Cannot open ship information before the game is ready");
  closeOptionsMenu();
  closeDiscoveriesMenu();
  closeAchievementsMenu();
  closePoliticsMenu();
  closeNavigationMenu();
  shipInfoMenu.isOpen = true;
  shipInfoMenu.view = "vessel";
  shipInfoMenu.cargoPage = 0;
  shipInfoMenu.ledgerPage = 0;
  shipInfoMenu.papersPage = 0;
  shipInfoMenu.paperSelectedIndex = 0;
  shipInfoMenu.paperSelectionActive = false;
  shipInfoMenu.paperDetailIndex = null;
  shipInfoMenu.paperDetailScrollY = 0;
  shipInfoMenu.paperDetailMaxScrollY = 0;
  shipInfoMenu.error = null;
  keys.clear();
  clearPointerSteering();
  const slug = ship.typeSlug;
  if (!shipInfoImages.has(slug)) {
    shipInfoMenu.loadingSlug = slug;
    void loadShipInfoImage(slug).then(() => {
      if (shipInfoMenu.loadingSlug === slug) shipInfoMenu.loadingSlug = null;
      dirty = true;
    }).catch((error) => {
      console.error(new Error(`Failed to load ${shipLabelForSlug(slug)} side view`, { cause: error }));
      if (shipInfoMenu.loadingSlug === slug) shipInfoMenu.loadingSlug = null;
      shipInfoMenu.error = `MISSING SHIP ART: ${shipLabelForSlug(slug)}`;
      dirty = true;
    });
  }
  dirty = true;
}

function closeShipInfoMenu() {
  shipInfoMenu.isOpen = false;
  canvas.style.cursor = "default";
  shipInfoMenu.closeButtonRect = null;
  shipInfoMenu.vesselTabRect = null;
  shipInfoMenu.ledgerTabRect = null;
  shipInfoMenu.papersTabRect = null;
  shipInfoMenu.paperRowRects = [];
  shipInfoMenu.paperSelectionActive = false;
  shipInfoMenu.paperDetailBackRect = null;
  shipInfoMenu.paperDetailUpRect = null;
  shipInfoMenu.paperDetailDownRect = null;
  shipInfoMenu.previousPageRect = null;
  shipInfoMenu.nextPageRect = null;
  dirty = true;
}

function handleShipInfoKeyDown(event) {
  event.preventDefault();
  if (event.key === "Escape" || event.key === "i" || event.key === "I") {
    if (shipInfoMenu.paperDetailIndex !== null) {
      closeShipPaperDetail();
      return;
    }
    closeShipInfoMenu();
    return;
  }
  if (event.key === "Tab") {
    stepShipInfoView(1);
    return;
  }
  if (event.key === "l" || event.key === "L") {
    setShipInfoView("ledger");
    return;
  }
  if (event.key === "v" || event.key === "V") {
    setShipInfoView("vessel");
    return;
  }
  if (event.key === "p" || event.key === "P") {
    setShipInfoView("papers");
    return;
  }
  if (shipInfoMenu.view === "papers") {
    if (shipInfoMenu.paperDetailIndex !== null) {
      if (event.key === "ArrowUp" || event.key === "PageUp") scrollShipPaperDetail(-1);
      else if (event.key === "ArrowDown" || event.key === "PageDown") scrollShipPaperDetail(1);
      else if (event.key === "Backspace" || event.key === "Enter" || event.key === " ") closeShipPaperDetail();
      return;
    }
    if (event.key === "Enter" || event.key === " ") {
      shipInfoMenu.paperSelectionActive = true;
      openSelectedShipPaperDetail();
      return;
    }
    if (event.key === "ArrowUp") {
      stepShipPaperSelection(-1);
      return;
    }
    if (event.key === "ArrowDown") {
      stepShipPaperSelection(1);
      return;
    }
  }
  if (["ArrowLeft", "ArrowUp", "PageUp"].includes(event.key)) {
    stepShipInfoPage(-1);
  } else if (["ArrowRight", "ArrowDown", "PageDown"].includes(event.key)) {
    stepShipInfoPage(1);
  }
}

function stepShipInfoPage(direction) {
  if (shipInfoMenu.view === "ledger") {
    const page = shipLedgerPage(gameState, shipInfoMenu.ledgerPage + direction, shipLedgerRowsPerPage());
    shipInfoMenu.ledgerPage = page.page;
    dirty = true;
    return;
  }
  const view = createShipInfoView(ship, gameState);
  if (shipInfoMenu.view === "papers") {
    const page = shipPapersPage(view, shipInfoMenu.papersPage + direction, shipPapersRowsPerPage());
    shipInfoMenu.papersPage = page.page;
    shipInfoMenu.paperSelectedIndex = clamp(shipInfoMenu.paperSelectedIndex, 0, Math.max(0, page.rows.length - 1));
    shipInfoMenu.paperDetailIndex = null;
    dirty = true;
    return;
  }
  const panel = captainNotebookPagePanel({
    x: SHIP_INFO_PANEL_X,
    y: SHIP_INFO_PANEL_Y,
    w: SHIP_INFO_PANEL_W,
    h: SHIP_INFO_PANEL_H
  });
  const page = shipInfoCargoPage(
    view,
    shipInfoMenu.cargoPage + direction,
    shipInfoCargoRowsPerPage(panel)
  );
  shipInfoMenu.cargoPage = page.page;
  dirty = true;
}

function shipLedgerRowsPerPage(panel = captainNotebookPagePanel({
  x: SHIP_INFO_PANEL_X,
  y: SHIP_INFO_PANEL_Y,
  w: SHIP_INFO_PANEL_W,
  h: SHIP_INFO_PANEL_H
})) {
  return shipLedgerRowsPerPageForPanel({
    width: panel.w,
    height: panel.h,
    tallMetrics: languageUsesTallPixelMetrics(currentLanguage),
    lineHeight: localizedLineHeight(9),
    pagerHeight: UI_PAGER_BUTTON_H
  });
}

function shipPapersRowsPerPage(panel = captainNotebookPagePanel({
  x: SHIP_INFO_PANEL_X,
  y: SHIP_INFO_PANEL_Y,
  w: SHIP_INFO_PANEL_W,
  h: SHIP_INFO_PANEL_H
})) {
  return shipPapersRowsPerPageForPanel({
    width: panel.w,
    height: panel.h,
    tallMetrics: languageUsesTallPixelMetrics(currentLanguage),
    lineHeight: localizedLineHeight(9),
    pagerHeight: UI_PAGER_BUTTON_H
  });
}

function setShipInfoView(view) {
  if (!["vessel", "ledger", "papers"].includes(view)) throw new Error(`Unknown ship information view: ${view}`);
  shipInfoMenu.view = view;
  shipInfoMenu.paperSelectionActive = false;
  if (view !== "papers") {
    shipInfoMenu.paperDetailIndex = null;
    shipInfoMenu.paperDetailScrollY = 0;
    shipInfoMenu.paperDetailMaxScrollY = 0;
  }
  shipInfoMenu.paperRowRects = [];
  shipInfoMenu.paperDetailBackRect = null;
  dirty = true;
}

function stepShipPaperSelection(direction) {
  if (!Number.isInteger(direction) || direction === 0) throw new Error(`Invalid inventory selection direction: ${direction}`);
  const view = createShipInfoView(ship, gameState);
  if (view.papers.length === 0) return;
  const rowsPerPage = shipPapersRowsPerPage();
  const page = shipPapersPage(view, shipInfoMenu.papersPage, rowsPerPage);
  const pageStart = page.page * rowsPerPage;
  const current = Math.min(
    view.papers.length - 1,
    pageStart + shipInfoMenu.paperSelectedIndex
  );
  const next = stepShipPaperSelectionIndex({
    currentIndex: current,
    direction,
    minIndex: shipInfoMenu.paperSelectionActive ? 0 : pageStart,
    maxIndex: shipInfoMenu.paperSelectionActive ? view.papers.length - 1 : pageStart + page.rows.length - 1,
    active: shipInfoMenu.paperSelectionActive
  });
  shipInfoMenu.papersPage = Math.floor(next / rowsPerPage);
  shipInfoMenu.paperSelectedIndex = next % rowsPerPage;
  shipInfoMenu.paperSelectionActive = true;
  dirty = true;
}

function openSelectedShipPaperDetail() {
  const view = createShipInfoView(ship, gameState);
  if (view.papers.length === 0) return;
  const rowsPerPage = shipPapersRowsPerPage();
  const index = shipInfoMenu.papersPage * rowsPerPage + shipInfoMenu.paperSelectedIndex;
  if (!view.papers[index]) throw new Error(`Selected inventory entry does not exist: ${index}`);
  shipInfoMenu.paperDetailIndex = index;
  shipInfoMenu.paperDetailScrollY = 0;
  shipInfoMenu.paperDetailMaxScrollY = 0;
  shipInfoMenu.paperRowRects = [];
  dirty = true;
}

function closeShipPaperDetail() {
  shipInfoMenu.paperDetailIndex = null;
  shipInfoMenu.paperDetailScrollY = 0;
  shipInfoMenu.paperDetailMaxScrollY = 0;
  shipInfoMenu.paperDetailBackRect = null;
  shipInfoMenu.paperDetailUpRect = null;
  shipInfoMenu.paperDetailDownRect = null;
  dirty = true;
}

function scrollShipPaperDetail(direction) {
  if (!Number.isInteger(direction) || direction === 0) throw new Error(`Invalid inventory detail scroll: ${direction}`);
  const next = clamp(
    shipInfoMenu.paperDetailScrollY + Math.sign(direction) * localizedLineHeight(18),
    0,
    shipInfoMenu.paperDetailMaxScrollY
  );
  if (next === shipInfoMenu.paperDetailScrollY) return;
  shipInfoMenu.paperDetailScrollY = next;
  dirty = true;
}

function createLakeBattleModeState() {
  const playerIndex = LAKE_BATTLE_SHIP_SLUGS.indexOf("brigantine");
  const enemyIndex = LAKE_BATTLE_ENEMY_SLUGS.indexOf("caravel");
  if (playerIndex < 0 || enemyIndex < 0) throw new Error("Lake battle default ships are missing from the armed roster");
  return {
    kind: "skirmish",
    screen: LAKE_BATTLE_SCREEN_SETUP,
    playerIndex,
    enemyIndex,
    selectedIndex: LAKE_BATTLE_SETUP_PLAYER_ROW,
    battle: null,
    sinkEffects: [],
    resultReadyAtMs: null,
    loading: false,
    error: null,
    hoverPoint: null,
    rowRects: [],
    leftArrowRects: [],
    rightArrowRects: [],
    actionRects: [],
    pauseButtonRect: null
  };
}

function createHistoricalBattleModeState() {
  const scenario = HISTORICAL_BATTLE_SCENARIOS[0];
  if (!scenario) throw new Error("Historical battle catalog is empty");
  const side = scenario.sides[0];
  if (!side?.squadrons?.[0]) throw new Error(`Historical battle has no playable squadrons: ${scenario.id}`);
  return {
    kind: "historical",
    screen: LAKE_BATTLE_SCREEN_SETUP,
    scenarioIndex: 0,
    sideIndex: 0,
    squadronIndex: 0,
    selectedIndex: HISTORICAL_BATTLE_SETUP_SCENARIO_ROW,
    battle: null,
    camera: null,
    sinkEffects: [],
    cannonSmokeBursts: [],
    resultReadyAtMs: null,
    loading: false,
    error: null,
    hoverPoint: null,
    rowRects: [],
    leftArrowRects: [],
    rightArrowRects: [],
    actionRects: [],
    pauseButtonRect: null,
    pendingFirePort: false,
    pendingFireStarboard: false,
    pendingUnitCommand: null,
    selectedShipIndex: -1,
    commandSelectedIndex: 0,
    commandRects: [],
    replay: null,
    resultRecorded: false
  };
}

function openLakeBattleMode() {
  lakeBattleMode = createLakeBattleModeState();
  startMenu = null;
  keys.clear();
  clearPointerSteering();
  syncCanvasAriaLabel();
  preloadLakeBattleShipAsset(selectedLakeBattleSlug("player"));
  preloadLakeBattleShipAsset(selectedLakeBattleSlug("enemy"));
  dirty = true;
}

function openHistoricalBattleMode() {
  lakeBattleMode = createHistoricalBattleModeState();
  startMenu = null;
  keys.clear();
  clearPointerSteering();
  syncCanvasAriaLabel();
  preloadHistoricalBattleAssets(selectedHistoricalBattleScenario());
  dirty = true;
}

function selectedHistoricalBattleScenario() {
  if (lakeBattleMode?.kind !== "historical") {
    throw new Error("Historical battle mode is not open");
  }
  const scenario = HISTORICAL_BATTLE_SCENARIOS[lakeBattleMode.scenarioIndex];
  if (!scenario) throw new Error(`Historical battle selection is invalid: ${lakeBattleMode.scenarioIndex}`);
  return scenario;
}

function selectedHistoricalBattleSide() {
  const scenario = selectedHistoricalBattleScenario();
  const side = scenario.sides[lakeBattleMode.sideIndex];
  if (!side) throw new Error(`Historical battle side selection is invalid: ${lakeBattleMode.sideIndex}`);
  return side;
}

function selectedHistoricalBattleSquadron() {
  const side = selectedHistoricalBattleSide();
  const squadron = side.squadrons[lakeBattleMode.squadronIndex];
  if (!squadron) {
    throw new Error(`Historical battle squadron selection is invalid: ${lakeBattleMode.squadronIndex}`);
  }
  return squadron;
}

function stepHistoricalBattleSelection(kind, direction) {
  if (lakeBattleMode?.kind !== "historical") throw new Error("Historical battle mode is not open");
  if (!Number.isInteger(direction) || direction === 0) {
    throw new Error(`Invalid historical battle selection step: ${direction}`);
  }
  if (kind === "scenario") {
    lakeBattleMode.scenarioIndex = wrapIndex(
      lakeBattleMode.scenarioIndex + direction,
      HISTORICAL_BATTLE_SCENARIOS.length
    );
    lakeBattleMode.sideIndex = 0;
    lakeBattleMode.squadronIndex = 0;
    preloadHistoricalBattleAssets(selectedHistoricalBattleScenario());
  } else if (kind === "side") {
    lakeBattleMode.sideIndex = wrapIndex(
      lakeBattleMode.sideIndex + direction,
      selectedHistoricalBattleScenario().sides.length
    );
    lakeBattleMode.squadronIndex = 0;
  } else if (kind === "squadron") {
    lakeBattleMode.squadronIndex = wrapIndex(
      lakeBattleMode.squadronIndex + direction,
      selectedHistoricalBattleSide().squadrons.length
    );
  } else {
    throw new Error(`Unknown historical battle selector: ${kind}`);
  }
  lakeBattleMode.error = null;
  dirty = true;
}

function preloadHistoricalBattleAssets(scenario) {
  const slugs = new Set();
  for (const side of scenario.sides) {
    for (const squadron of side.squadrons) {
      for (const group of squadron.shipGroups) slugs.add(group.shipSlug);
    }
  }
  for (const slug of slugs) preloadLakeBattleShipAsset(slug);
}

async function beginHistoricalBattle() {
  if (lakeBattleMode?.kind !== "historical" || lakeBattleMode.loading) return;
  const mode = lakeBattleMode;
  mode.loading = true;
  mode.error = null;
  dirty = true;
  try {
    const scenario = selectedHistoricalBattleScenario();
    const side = selectedHistoricalBattleSide();
    const squadron = selectedHistoricalBattleSquadron();
    const slugs = new Set();
    for (const scenarioSide of scenario.sides) {
      for (const scenarioSquadron of scenarioSide.squadrons) {
        for (const group of scenarioSquadron.shipGroups) slugs.add(group.shipSlug);
      }
    }
    await Promise.all([...slugs].map((slug) => ensureLakeBattleShipAsset(slug)));
    if (lakeBattleMode !== mode) return;
    mode.battle = createHistoricalBattle({
      scenarioId: scenario.id,
      playerSideId: side.id,
      playerSquadronId: squadron.id,
      shipFootprints: shipFootprintsBySlug,
      shipWakeAnchorsBySlug
    });
    const player = historicalBattlePlayerShip(mode.battle);
    mode.camera = { x: player.x, y: player.y };
    mode.screen = LAKE_BATTLE_SCREEN_ACTIVE;
    mode.sinkEffects = [];
    mode.cannonSmokeBursts = [];
    mode.resultReadyAtMs = null;
    mode.replay = null;
    mode.resultRecorded = false;
    mode.selectedIndex = 0;
    mode.loading = false;
    mode.pauseButtonRect = null;
    clearHistoricalBattlePendingActions();
    keys.clear();
    clearPointerSteering();
    startCombatMusicForThreat("big");
  } catch (error) {
    if (lakeBattleMode !== mode) return;
    mode.loading = false;
    mode.error ||= uiText("historical.couldNotStart");
    console.error("[pixel-globe] historical battle could not start", error);
  }
  dirty = true;
}

function restartHistoricalBattle({ replay = null } = {}) {
  if (lakeBattleMode?.kind !== "historical") return;
  const scenario = selectedHistoricalBattleScenario();
  const side = selectedHistoricalBattleSide();
  const squadron = selectedHistoricalBattleSquadron();
  lakeBattleMode.battle = createHistoricalBattle({
    scenarioId: scenario.id,
    playerSideId: side.id,
    playerSquadronId: squadron.id,
    shipFootprints: shipFootprintsBySlug,
    shipWakeAnchorsBySlug,
    ...(replay ? { seed: replay.seed } : {})
  });
  const player = historicalBattlePlayerShip(lakeBattleMode.battle);
  lakeBattleMode.camera = { x: player.x, y: player.y };
  lakeBattleMode.screen = LAKE_BATTLE_SCREEN_ACTIVE;
  lakeBattleMode.sinkEffects = [];
  lakeBattleMode.cannonSmokeBursts = [];
  lakeBattleMode.resultReadyAtMs = null;
  lakeBattleMode.replay = replay;
  lakeBattleMode.resultRecorded = false;
  lakeBattleMode.selectedIndex = 0;
  clearHistoricalBattlePendingActions();
  keys.clear();
  clearPointerSteering();
  startCombatMusicForThreat("big");
  dirty = true;
}

function returnHistoricalBattleToSetup() {
  if (lakeBattleMode?.kind !== "historical") return;
  lakeBattleMode.screen = LAKE_BATTLE_SCREEN_SETUP;
  lakeBattleMode.battle = null;
  lakeBattleMode.camera = null;
  lakeBattleMode.sinkEffects = [];
  lakeBattleMode.resultReadyAtMs = null;
  lakeBattleMode.selectedIndex = HISTORICAL_BATTLE_SETUP_SCENARIO_ROW;
  lakeBattleMode.error = null;
  lakeBattleMode.replay = null;
  lakeBattleMode.resultRecorded = false;
  clearHistoricalBattlePendingActions();
  combatMusicUntilMs = 0;
  keys.clear();
  clearPointerSteering();
  dirty = true;
}

function wrapIndex(value, length) {
  if (!Number.isInteger(length) || length <= 0) throw new Error(`Cannot wrap index over ${length} entries`);
  return ((value % length) + length) % length;
}

function clearHistoricalBattlePendingActions() {
  if (lakeBattleMode?.kind !== "historical") return;
  lakeBattleMode.pendingFirePort = false;
  lakeBattleMode.pendingFireStarboard = false;
  lakeBattleMode.pendingUnitCommand = null;
  lakeBattleMode.selectedShipIndex = -1;
  lakeBattleMode.commandSelectedIndex = 0;
  lakeBattleMode.commandRects = [];
}

function closeLakeBattleModeToStartMenu() {
  lakeBattleMode = null;
  lakeBattleTerrainChart = null;
  lakeBattleTerrainChartKey = "";
  combatMusicUntilMs = 0;
  startMenu = createStartMenuState();
  syncCanvasAriaLabel();
  keys.clear();
  clearPointerSteering();
  dirty = true;
}

function selectedLakeBattleSlug(side) {
  if (!lakeBattleMode) throw new Error("Lake battle mode is not open");
  if (side === "player") return LAKE_BATTLE_SHIP_SLUGS[lakeBattleMode.playerIndex];
  if (side === "enemy") return LAKE_BATTLE_ENEMY_SLUGS[lakeBattleMode.enemyIndex];
  throw new Error(`Unknown lake battle selection side: ${side}`);
}

function stepLakeBattleShipSelection(side, direction) {
  if (!Number.isInteger(direction) || direction === 0) throw new Error(`Invalid lake battle selection step: ${direction}`);
  const key = side === "player" ? "playerIndex" : side === "enemy" ? "enemyIndex" : null;
  if (!key) throw new Error(`Unknown lake battle selection side: ${side}`);
  const length = side === "player" ? LAKE_BATTLE_SHIP_SLUGS.length : LAKE_BATTLE_ENEMY_SLUGS.length;
  lakeBattleMode[key] = ((lakeBattleMode[key] + direction) % length + length) % length;
  lakeBattleMode.error = null;
  preloadLakeBattleShipAsset(selectedLakeBattleSlug(side));
  dirty = true;
}

function preloadLakeBattleShipAsset(slug) {
  if (lakeBattleCombatantIsCity(slug)) return;
  void ensureLakeBattleShipAsset(slug).catch(() => {
    // ensureLakeBattleShipAsset reports the exact asset failure in the mode and console.
  });
}

async function ensureLakeBattleShipAsset(slug) {
  if (lakeBattleCombatantIsCity(slug)) throw new Error("A lake battle city does not use a ship asset");
  if (lakeBattleShipAssets.has(slug)) return lakeBattleShipAssets.get(slug);
  const residentAsset = residentShipVisualAsset(slug);
  if (residentAsset) {
    lakeBattleShipAssets.set(slug, residentAsset);
    return residentAsset;
  }
  const pending = lakeBattleShipAssetPromises.get(slug);
  if (pending) return pending;
  const promise = requestShipVisualAssets(slug)
    .then((asset) => {
      lakeBattleShipAssets.set(slug, asset);
      lakeBattleShipAssetPromises.delete(slug);
      dirty = true;
      return asset;
    })
    .catch((error) => {
      lakeBattleShipAssetPromises.delete(slug);
      if (lakeBattleMode) lakeBattleMode.error = `COULD NOT LOAD ${shipLabelForSlug(slug).toUpperCase()}`;
      console.error(`[pixel-globe] lake battle ship asset failed: ${slug}`, error);
      dirty = true;
      throw error;
    });
  lakeBattleShipAssetPromises.set(slug, promise);
  return promise;
}

async function beginLakeBattle() {
  if (!lakeBattleMode || lakeBattleMode.loading) return;
  const mode = lakeBattleMode;
  mode.loading = true;
  mode.error = null;
  dirty = true;
  try {
    const playerSlug = selectedLakeBattleSlug("player");
    const enemySlug = selectedLakeBattleSlug("enemy");
    const assets = [ensureLakeBattleShipAsset(playerSlug)];
    if (!lakeBattleCombatantIsCity(enemySlug)) assets.push(ensureLakeBattleShipAsset(enemySlug));
    await Promise.all(assets);
    if (lakeBattleMode !== mode) return;
    mode.battle = createLakeBattle({
      width: SCREEN_W,
      height: SCREEN_H,
      playerSlug,
      enemySlug,
      shipFootprints: shipFootprintsBySlug
    });
    mode.screen = LAKE_BATTLE_SCREEN_ACTIVE;
    mode.sinkEffects = [];
    mode.resultReadyAtMs = null;
    mode.selectedIndex = 0;
    mode.loading = false;
    mode.pauseButtonRect = null;
    keys.clear();
    clearPointerSteering();
    startCombatMusicForThreat(Math.max(
      lakeBattleCombatantStats(playerSlug).cannons,
      lakeBattleCombatantStats(enemySlug).cannons
    ) >= COMBAT_BIG_BROADSIDE_MIN_CANNONS ? "big" : "small");
  } catch (error) {
    if (lakeBattleMode !== mode) return;
    mode.loading = false;
    mode.error ||= "BATTLE COULD NOT START";
    console.error("[pixel-globe] lake battle could not start", error);
  }
  dirty = true;
}

function restartLakeBattle() {
  if (!lakeBattleMode) return;
  const playerSlug = selectedLakeBattleSlug("player");
  const enemySlug = selectedLakeBattleSlug("enemy");
  if (!lakeBattleShipAssets.has(playerSlug) ||
      (!lakeBattleCombatantIsCity(enemySlug) && !lakeBattleShipAssets.has(enemySlug))) {
    throw new Error("Cannot restart lake battle without both selected ship assets");
  }
  lakeBattleMode.battle = createLakeBattle({
    width: SCREEN_W,
    height: SCREEN_H,
    playerSlug,
    enemySlug,
    shipFootprints: shipFootprintsBySlug
  });
  lakeBattleMode.screen = LAKE_BATTLE_SCREEN_ACTIVE;
  lakeBattleMode.sinkEffects = [];
  lakeBattleMode.resultReadyAtMs = null;
  lakeBattleMode.selectedIndex = 0;
  keys.clear();
  clearPointerSteering();
  startCombatMusicForThreat(Math.max(
    lakeBattleCombatantStats(playerSlug).cannons,
    lakeBattleCombatantStats(enemySlug).cannons
  ) >= COMBAT_BIG_BROADSIDE_MIN_CANNONS ? "big" : "small");
  dirty = true;
}

function returnLakeBattleToSetup() {
  if (!lakeBattleMode) return;
  lakeBattleMode.screen = LAKE_BATTLE_SCREEN_SETUP;
  lakeBattleMode.battle = null;
  lakeBattleMode.sinkEffects = [];
  lakeBattleMode.resultReadyAtMs = null;
  lakeBattleMode.selectedIndex = LAKE_BATTLE_SETUP_PLAYER_ROW;
  lakeBattleMode.error = null;
  combatMusicUntilMs = 0;
  keys.clear();
  clearPointerSteering();
  dirty = true;
}

function updateLakeBattleModeFrame(dt, nowMs) {
  if (!lakeBattleMode || optionsMenu.isOpen) return false;
  if (lakeBattleMode.kind === "historical") {
    return updateHistoricalBattleModeFrame(dt, nowMs);
  }
  if (lakeBattleMode.screen === LAKE_BATTLE_SCREEN_SINKING) {
    if (!Number.isFinite(lakeBattleMode.resultReadyAtMs)) {
      throw new Error("Lake battle sinking screen has no result deadline");
    }
    if (nowMs >= lakeBattleMode.resultReadyAtMs) {
      lakeBattleMode.screen = LAKE_BATTLE_SCREEN_RESULT;
      lakeBattleMode.selectedIndex = 0;
    }
    dirty = true;
    return true;
  }
  if (lakeBattleMode.screen !== LAKE_BATTLE_SCREEN_ACTIVE) return false;
  const battle = lakeBattleMode.battle;
  if (!battle) throw new Error("Active lake battle screen has no battle state");
  updateLakeBattle(battle, dt, lakeBattleInputCommand());
  processLakeBattleEvents(battle);
  if (battle.phase !== LAKE_BATTLE_PHASE_ACTIVE) {
    startLakeBattleSinkSequence(battle, nowMs);
    keys.clear();
    clearPointerSteering();
  }
  dirty = true;
  return true;
}

function updateHistoricalBattleModeFrame(dt, nowMs) {
  if (lakeBattleMode?.kind !== "historical" || optionsMenu.isOpen) return false;
  if (lakeBattleMode.screen === LAKE_BATTLE_SCREEN_SINKING) {
    pruneHistoricalBattleSinkEffects(nowMs);
    if (!Number.isFinite(lakeBattleMode.resultReadyAtMs)) {
      throw new Error("Historical battle sinking screen has no result deadline");
    }
    if (nowMs >= lakeBattleMode.resultReadyAtMs) {
      lakeBattleMode.screen = LAKE_BATTLE_SCREEN_RESULT;
      lakeBattleMode.selectedIndex = 0;
    }
    dirty = true;
    return true;
  }
  if (lakeBattleMode.screen !== LAKE_BATTLE_SCREEN_ACTIVE) return false;
  const battle = lakeBattleMode.battle;
  if (!battle) throw new Error("Active historical battle screen has no battle state");
  const advanced = lakeBattleMode.replay
    ? updateHistoricalBattleReplay(battle, dt, lakeBattleMode.replay)
    : updateHistoricalBattle(battle, dt, historicalBattleInputCommand());
  lakeBattleMode.cannonSmokeBursts = advanceCannonSmokeBursts(
    lakeBattleMode.cannonSmokeBursts,
    dt
  );
  if (advanced && !lakeBattleMode.replay) {
    lakeBattleMode.pendingFirePort = false;
    lakeBattleMode.pendingFireStarboard = false;
    lakeBattleMode.pendingUnitCommand = null;
  }
  processHistoricalBattleEvents(battle, nowMs);
  pruneHistoricalBattleSinkEffects(nowMs);
  const player = historicalBattlePlayerShip(battle);
  const playerPose = historicalBattleInterpolatedShipPose(battle, player);
  if (!lakeBattleMode.camera) lakeBattleMode.camera = { x: playerPose.x, y: playerPose.y };
  const cameraCatchup = 1 - Math.exp(-dt * 9);
  lakeBattleMode.camera.x += (playerPose.x - lakeBattleMode.camera.x) * cameraCatchup;
  lakeBattleMode.camera.y += (playerPose.y - lakeBattleMode.camera.y) * cameraCatchup;
  clampHistoricalBattleCamera(lakeBattleMode.camera, battle.map);
  if (battle.phase !== HISTORICAL_BATTLE_PHASE_ACTIVE) {
    finishHistoricalBattlePresentation(nowMs);
    keys.clear();
    clearPointerSteering();
  }
  dirty = true;
  return true;
}

function historicalBattleInputCommand() {
  const battle = lakeBattleMode?.kind === "historical" ? lakeBattleMode.battle : null;
  if (!battle) return { desiredHeadingRad: null, rowingRequested: false };
  const oneShotActions = {
    firePort: lakeBattleMode.pendingFirePort === true,
    fireStarboard: lakeBattleMode.pendingFireStarboard === true,
    unitCommand: lakeBattleMode.pendingUnitCommand
  };
  const player = historicalBattlePlayerShip(battle);
  if (pointerSteering.active && pointerSteering.point) {
    const screenPoint = historicalBattleWorldToScreen(player);
    const px = pointerSteering.point.x - screenPoint.x;
    const py = pointerSteering.point.y - screenPoint.y;
    if (Math.hypot(px, py) >= POINTER_STEERING_DEADZONE_PX) {
      return {
        ...historicalBattleDirectionalInputCommand(battle, Math.atan2(py, px)),
        ...oneShotActions
      };
    }
  }
  const intent = steeringIntentForScheme({
    scheme: optionsMenu.controlScheme,
    left: keys.has(KEY_ACTION.STEER_LEFT),
    right: keys.has(KEY_ACTION.STEER_RIGHT),
    up: keys.has(KEY_ACTION.STEER_UP),
    down: keys.has(KEY_ACTION.STEER_DOWN),
    controllerX: controllerSteering?.dx * controllerSteering?.strength || 0,
    controllerY: controllerSteering?.dy * controllerSteering?.strength || 0
  });
  const canRow = shipCanUseOars(player.stats);
  if (intent.relativeBackward && canRow) {
    return {
      desiredHeadingRad: player.headingRad,
      rowingMode: SHIP_ROWING_MODE_ASTERN,
      ...oneShotActions
    };
  }
  if (intent.relativeTurn !== 0) {
    return {
      desiredHeadingRad: relativeHeadingAngle(player.headingRad, intent.relativeTurn),
      rowingMode: intent.relativeForward
        ? (canRow ? SHIP_ROWING_MODE_AHEAD : SHIP_ROWING_MODE_IDLE)
        : canRow
          ? (intent.relativeTurn > 0
              ? SHIP_ROWING_MODE_PIVOT_STARBOARD
              : SHIP_ROWING_MODE_PIVOT_PORT)
          : SHIP_ROWING_MODE_IDLE,
      ...oneShotActions
    };
  }
  if (intent.relativeForward) {
    return {
      desiredHeadingRad: player.headingRad,
      rowingMode: canRow ? SHIP_ROWING_MODE_AHEAD : SHIP_ROWING_MODE_IDLE,
      ...oneShotActions
    };
  }
  if (intent.absoluteX === 0 && intent.absoluteY === 0) {
    return { desiredHeadingRad: null, rowingMode: SHIP_ROWING_MODE_IDLE, ...oneShotActions };
  }
  return {
    ...historicalBattleDirectionalInputCommand(
      battle,
      Math.atan2(-intent.absoluteY, intent.absoluteX)
    ),
    ...oneShotActions
  };
}

function historicalBattleDirectionalInputCommand(battle, desiredHeadingRad) {
  const player = historicalBattlePlayerShip(battle);
  if (!shipCanUseOars(player.stats)) {
    return { desiredHeadingRad, rowingMode: SHIP_ROWING_MODE_IDLE };
  }
  const turn = Math.atan2(
    Math.sin(desiredHeadingRad - player.headingRad),
    Math.cos(desiredHeadingRad - player.headingRad)
  );
  if (Math.cos(turn) <= -Math.cos(35 * Math.PI / 180)) {
    return { desiredHeadingRad: player.headingRad, rowingMode: SHIP_ROWING_MODE_ASTERN };
  }
  const speedRatio = Math.abs(player.speedPx) / (player.stats.topSpeedRad * PIXELS_PER_RADIAN);
  if (speedRatio <= 0.2 && Math.abs(turn) > 20 * Math.PI / 180) {
    return {
      desiredHeadingRad,
      rowingMode: turn > 0 ? SHIP_ROWING_MODE_PIVOT_STARBOARD : SHIP_ROWING_MODE_PIVOT_PORT
    };
  }
  return { desiredHeadingRad, rowingMode: SHIP_ROWING_MODE_AHEAD };
}

function fireHistoricalBattlePlayerBroadside(sideName) {
  const battle = lakeBattleMode?.kind === "historical" ? lakeBattleMode.battle : null;
  if (!battle || lakeBattleMode.screen !== LAKE_BATTLE_SCREEN_ACTIVE || lakeBattleMode.replay) {
    return false;
  }
  if (sideName !== "port" && sideName !== "starboard") {
    throw new Error(`Unknown historical battle broadside: ${sideName}`);
  }
  lakeBattleMode[sideName === "port" ? "pendingFirePort" : "pendingFireStarboard"] = true;
  dirty = true;
  return true;
}

function cycleHistoricalBattleCommandTarget() {
  const battle = lakeBattleMode?.kind === "historical" ? lakeBattleMode.battle : null;
  if (!battle || lakeBattleMode.screen !== LAKE_BATTLE_SCREEN_ACTIVE || lakeBattleMode.replay) {
    return false;
  }
  const candidates = historicalBattleVisibleShips(
    battle,
    lakeBattleMode.camera,
    SCREEN_W,
    SCREEN_H
  ).filter((shipState) => shipState.active && !shipState.playerControlled)
    .sort((a, b) => a.sideIndex - b.sideIndex || a.id.localeCompare(b.id));
  if (candidates.length === 0) {
    lakeBattleMode.selectedShipIndex = -1;
    lakeBattleMode.commandSelectedIndex = 0;
    lakeBattleMode.commandRects = [];
    dirty = true;
    return false;
  }
  const current = battle.ships[lakeBattleMode.selectedShipIndex];
  const currentIndex = candidates.indexOf(current);
  const next = candidates[(currentIndex + 1) % candidates.length];
  lakeBattleMode.selectedShipIndex = battle.ships.indexOf(next);
  lakeBattleMode.commandSelectedIndex = 0;
  lakeBattleMode.commandRects = [];
  dirty = true;
  return true;
}

function processHistoricalBattleEvents(battle, nowMs) {
  const player = historicalBattlePlayerShip(battle);
  let attackSounds = 0;
  let impactSounds = 0;
  for (const event of drainHistoricalBattleEvents(battle)) {
    if (event.type === "fire") {
      const firingShip = battle.ships[event.shipIndex];
      if (!firingShip) throw new Error(`Historical battle fire event lost ship ${event.shipIndex}`);
      const distance = Math.hypot(firingShip.x - player.x, firingShip.y - player.y);
      if (distance <= Math.max(SCREEN_W, SCREEN_H) && attackSounds < 4) {
        const count = Math.max(1, event.count || event.cannonCount || 1);
        if (event.weaponId) {
          const portable = portableWeaponItemById(event.weaponId).weapon;
          if (!portable) throw new Error(`Historical battle fired a non-weapon item: ${event.weaponId}`);
          playPortableWeaponAttackSound(portable, count, distance);
        } else {
          playNavalAttackSound(
            { kind: event.weaponKind || NAVAL_WEAPON_CANNON },
            count,
            distance
          );
        }
        attackSounds += 1;
      }
      if (Array.isArray(event.smokeProjectiles) && historicalBattleShipNearViewport(firingShip)) {
        for (const projectile of event.smokeProjectiles) {
          lakeBattleMode.cannonSmokeBursts.push(createCannonSmokeBurst(projectile));
        }
        if (lakeBattleMode.cannonSmokeBursts.length > CANNON_MAX_SMOKE_BURSTS) {
          lakeBattleMode.cannonSmokeBursts.splice(
            0,
            lakeBattleMode.cannonSmokeBursts.length - CANNON_MAX_SMOKE_BURSTS
          );
        }
      }
    } else if (event.type === "hit") {
      const hitShip = battle.ships[event.shipIndex];
      if (!hitShip) throw new Error(`Historical battle hit event lost ship ${event.shipIndex}`);
      const distance = Math.hypot(hitShip.x - player.x, hitShip.y - player.y);
      if (distance <= Math.max(SCREEN_W, SCREEN_H) && impactSounds < 4) {
        if (event.weaponKind === NAVAL_WEAPON_ARROW) playArrowHitSound();
        else if (event.resisted) playArmorGlanceSound(distance);
        else if (event.weaponKind === NAVAL_WEAPON_CANNON) {
          playCannonImpactSound(Math.max(8, 18 - distance / 30));
        } else {
          playArrowHitSound();
        }
        impactSounds += 1;
      }
    } else if (event.type === "sunk") {
      const sunkShip = battle.ships[event.shipIndex];
      if (!sunkShip) throw new Error(`Historical battle sink event lost ship ${event.shipIndex}`);
      if (historicalBattleShipNearViewport(sunkShip) &&
          !lakeBattleMode.sinkEffects.some((entry) => entry.shipId === sunkShip.id)) {
        lakeBattleMode.sinkEffects.push({
          shipId: sunkShip.id,
          effect: createHistoricalBattleShipSinkEffect(battle, sunkShip, nowMs)
        });
      }
    } else if (event.type === "finished") {
      recordCompletedHistoricalBattle(battle);
    } else if (event.type === "collision") {
      const collisionShip = battle.ships[event.shipIndex];
      if (collisionShip && historicalBattleShipNearViewport(collisionShip) && impactSounds < 4) {
        playCannonImpactSound(8);
        impactSounds += 1;
      }
    } else if (event.type === "escaped" || event.type === "surrendered") {
      // Their visible state and the result screen present these aggregate fleet events.
    } else {
      throw new Error(`Unknown historical battle event: ${event.type}`);
    }
  }
}

function recordCompletedHistoricalBattle(battle) {
  if (lakeBattleMode.resultRecorded || lakeBattleMode.replay) return false;
  if (!historicalBattleRecords) {
    throw new Error("Cannot record a historical battle while its records are unavailable");
  }
  const enemy = battle.sides.find((side) => side.id !== battle.playerSideId);
  if (!enemy) throw new Error("Completed historical battle has no enemy side");
  const result = {
    scenarioId: battle.scenario.id,
    playerSideId: battle.playerSideId,
    playerSquadronId: battle.playerSquadronId,
    outcome: battle.outcome,
    enemyShipsDefeated: enemy.sunkShips + enemy.surrenderedShips,
    durationSeconds: battle.elapsedSeconds,
    endedAt: Date.now()
  };
  recordHistoricalBattleResult(
    historicalBattleRecords,
    result,
    createHistoricalBattleReplay(battle)
  );
  writeHistoricalBattleRecords(historicalBattleRecords);
  historicalBattleRecordsResult = {
    status: "ready",
    records: historicalBattleRecords,
    error: null
  };
  lakeBattleMode.resultRecorded = true;
  if (achievementProfile) {
    queueAchievementPlatformSync(steamStatValues(
      achievementProfile,
      createVoyageAchievementProgress(),
      currentAchievementSnapshot(),
      historicalBattleRecords
    ));
  }
  window.dispatchEvent(new CustomEvent("marque:historical-battle-complete", {
    detail: Object.freeze({ ...result })
  }));
  return true;
}

function historicalBattleResultActions() {
  const actions = ["REMATCH"];
  if (historicalBattleRecords?.latestReplay) actions.push("WATCH REPLAY");
  actions.push("CHOOSE BATTLE", "START MENU");
  return actions;
}

function historicalBattleScenarioText(scenario, field) {
  return uiText(["historical", "scenario", scenario.id, field].join("."));
}

function historicalBattleSideText(side) {
  return uiText(`historical.side.${side.id}`);
}

function historicalBattleSquadronText(squadron) {
  return uiText(`historical.squadron.${squadron.id}`);
}

function historicalBattleShipsText(count) {
  return uiText("historical.shipsCount", { count });
}

function selectedHistoricalBattleRecordText(scenario, side) {
  if (!historicalBattleRecords) return null;
  const record = historicalBattleRecords.byScenarioSide[
    historicalBattleRecordKey(scenario.id, side.id)
  ];
  return uiText("historical.record", {
    wins: record?.victories || 0,
    losses: record?.defeats || 0,
    draws: record?.draws || 0
  });
}

function watchLatestHistoricalBattleReplay() {
  const replay = historicalBattleRecords?.latestReplay;
  if (!replay) throw new Error("No historical battle replay is available");
  const scenarioIndex = HISTORICAL_BATTLE_SCENARIOS.findIndex(
    (scenario) => scenario.id === replay.scenarioId
  );
  if (scenarioIndex < 0) throw new Error(`Replay scenario is missing: ${replay.scenarioId}`);
  const scenario = HISTORICAL_BATTLE_SCENARIOS[scenarioIndex];
  const sideIndex = scenario.sides.findIndex((side) => side.id === replay.playerSideId);
  if (sideIndex < 0) throw new Error(`Replay side is missing: ${replay.playerSideId}`);
  const squadronIndex = scenario.sides[sideIndex].squadrons.findIndex(
    (squadron) => squadron.id === replay.playerSquadronId
  );
  if (squadronIndex < 0) throw new Error(`Replay squadron is missing: ${replay.playerSquadronId}`);
  lakeBattleMode.scenarioIndex = scenarioIndex;
  lakeBattleMode.sideIndex = sideIndex;
  lakeBattleMode.squadronIndex = squadronIndex;
  restartHistoricalBattle({ replay });
}

function historicalBattleShipNearViewport(shipState) {
  const point = historicalBattleWorldToScreen(shipState);
  return point.x >= -SHIP_SHEET_FRAME_SIZE && point.x <= SCREEN_W + SHIP_SHEET_FRAME_SIZE &&
    point.y >= -SHIP_SHEET_FRAME_SIZE && point.y <= SCREEN_H + SHIP_SHEET_FRAME_SIZE;
}

function pruneHistoricalBattleSinkEffects(nowMs) {
  lakeBattleMode.sinkEffects = lakeBattleMode.sinkEffects.filter(({ effect }) => (
    !shipSinkEffectComplete(effect, nowMs)
  ));
}

function finishHistoricalBattlePresentation(nowMs) {
  if (lakeBattleMode.sinkEffects.length === 0) {
    lakeBattleMode.resultReadyAtMs = null;
    lakeBattleMode.screen = LAKE_BATTLE_SCREEN_RESULT;
    lakeBattleMode.selectedIndex = 0;
    return;
  }
  lakeBattleMode.resultReadyAtMs = Math.max(...lakeBattleMode.sinkEffects.map(({ effect }) => (
    effect.startedAtMs + SHIP_SINK_EFFECT_DURATION_MS
  )));
  if (lakeBattleMode.resultReadyAtMs <= nowMs) {
    throw new Error("Historical battle sink presentation ended before it began");
  }
  lakeBattleMode.screen = LAKE_BATTLE_SCREEN_SINKING;
}

function clampHistoricalBattleCamera(cameraValue, map) {
  const halfWidth = Math.min(SCREEN_W / 2, map.width / 2);
  const halfHeight = Math.min(SCREEN_H / 2, map.height / 2);
  cameraValue.x = clamp(cameraValue.x, halfWidth, map.width - halfWidth);
  cameraValue.y = clamp(cameraValue.y, halfHeight, map.height - halfHeight);
}

function historicalBattleWorldToScreen(point) {
  const cameraValue = lakeBattleMode?.camera;
  if (!cameraValue) throw new Error("Historical battle camera is missing");
  return {
    x: point.x - cameraValue.x + SCREEN_W / 2,
    y: point.y - cameraValue.y + SCREEN_H / 2
  };
}

function startLakeBattleSinkSequence(battle, nowMs) {
  const defeatedCombatants = [battle.player, battle.enemy].filter((state) => (
    state.hitPoints <= 0 || state.surrendered
  ));
  if (defeatedCombatants.length === 0) throw new Error("Finished lake battle has no defeated combatant");
  const sunkShips = defeatedCombatants.filter((state) => (
    state.hitPoints <= 0 && !lakeBattleCombatantIsCity(state)
  ));
  if (sunkShips.length === 0) {
    lakeBattleMode.sinkEffects = [];
    lakeBattleMode.resultReadyAtMs = null;
    lakeBattleMode.screen = LAKE_BATTLE_SCREEN_RESULT;
    lakeBattleMode.selectedIndex = 0;
    return;
  }
  lakeBattleMode.sinkEffects = sunkShips.map((shipState) => ({
    shipId: shipState.id,
    effect: createLakeBattleShipSinkEffect(shipState, nowMs)
  }));
  lakeBattleMode.resultReadyAtMs = nowMs + SHIP_SINK_EFFECT_DURATION_MS;
  lakeBattleMode.screen = LAKE_BATTLE_SCREEN_SINKING;
}

function lakeBattleInputCommand() {
  const battle = lakeBattleMode?.battle;
  if (!battle) return { desiredHeadingRad: null, rowingMode: SHIP_ROWING_MODE_IDLE };
  if (pointerSteering.active && pointerSteering.point) {
    const px = pointerSteering.point.x - battle.player.x;
    const py = pointerSteering.point.y - battle.player.y;
    const length = Math.hypot(px, py);
    if (length >= POINTER_STEERING_DEADZONE_PX) {
      return lakeBattleDirectionalInputCommand(battle, Math.atan2(py, px));
    }
  }
  const intent = steeringIntentForScheme({
    scheme: optionsMenu.controlScheme,
    left: keys.has(KEY_ACTION.STEER_LEFT),
    right: keys.has(KEY_ACTION.STEER_RIGHT),
    up: keys.has(KEY_ACTION.STEER_UP),
    down: keys.has(KEY_ACTION.STEER_DOWN),
    controllerX: controllerSteering?.dx * controllerSteering?.strength || 0,
    controllerY: controllerSteering?.dy * controllerSteering?.strength || 0
  });
  const canRow = shipCanUseOars(battle.player.stats);
  if (intent.relativeBackward && canRow) {
    return {
      desiredHeadingRad: intent.relativeTurn === 0
        ? battle.player.headingRad
        : relativeHeadingAngle(battle.player.headingRad, intent.relativeTurn),
      rowingMode: SHIP_ROWING_MODE_ASTERN
    };
  }
  if (intent.relativeTurn !== 0) {
    return {
      desiredHeadingRad: relativeHeadingAngle(battle.player.headingRad, intent.relativeTurn),
      rowingMode: intent.relativeForward
        ? (canRow ? SHIP_ROWING_MODE_AHEAD : SHIP_ROWING_MODE_IDLE)
        : canRow
          ? (intent.relativeTurn > 0
              ? SHIP_ROWING_MODE_PIVOT_STARBOARD
              : SHIP_ROWING_MODE_PIVOT_PORT)
          : SHIP_ROWING_MODE_IDLE
    };
  }
  if (intent.relativeForward) {
    return {
      desiredHeadingRad: battle.player.headingRad,
      rowingMode: canRow ? SHIP_ROWING_MODE_AHEAD : SHIP_ROWING_MODE_IDLE
    };
  }
  if (intent.absoluteX === 0 && intent.absoluteY === 0) {
    return { desiredHeadingRad: null, rowingMode: SHIP_ROWING_MODE_IDLE };
  }
  return lakeBattleDirectionalInputCommand(
    battle,
    Math.atan2(-intent.absoluteY, intent.absoluteX)
  );
}

function lakeBattleDirectionalInputCommand(battle, desiredHeadingRad) {
  if (!shipCanUseOars(battle.player.stats)) {
    return { desiredHeadingRad, rowingMode: SHIP_ROWING_MODE_IDLE };
  }
  const turn = Math.atan2(
    Math.sin(desiredHeadingRad - battle.player.headingRad),
    Math.cos(desiredHeadingRad - battle.player.headingRad)
  );
  if (Math.cos(turn) <= -Math.cos(35 * Math.PI / 180)) {
    return {
      desiredHeadingRad: battle.player.headingRad,
      rowingMode: SHIP_ROWING_MODE_ASTERN
    };
  }
  const speedRatio = Math.abs(battle.player.speedPx) /
    (battle.player.stats.topSpeedRad * PIXELS_PER_RADIAN);
  if (speedRatio <= 0.2 && Math.abs(turn) > 20 * Math.PI / 180) {
    return {
      desiredHeadingRad,
      rowingMode: turn > 0
        ? SHIP_ROWING_MODE_PIVOT_STARBOARD
        : SHIP_ROWING_MODE_PIVOT_PORT
    };
  }
  return { desiredHeadingRad, rowingMode: SHIP_ROWING_MODE_AHEAD };
}

function fireLakeBattlePlayerBroadside(sideName) {
  const battle = lakeBattleMode?.battle;
  if (!battle || lakeBattleMode.screen !== LAKE_BATTLE_SCREEN_ACTIVE) return false;
  const fired = fireLakeBattleBroadside(battle, LAKE_BATTLE_PLAYER_ID, sideName);
  if (fired) processLakeBattleEvents(battle);
  dirty = dirty || fired;
  return fired;
}

function processLakeBattleEvents(battle) {
  for (const event of drainLakeBattleEvents(battle)) {
    if (event.type === "fire") {
      const firingShip = lakeBattleShipById(battle, event.shipId);
      const distanceFromPlayer = Math.hypot(
        firingShip.x - battle.player.x,
        firingShip.y - battle.player.y
      );
      if (event.weaponId) {
        const portable = portableWeaponItemById(event.weaponId).weapon;
        if (!portable) throw new Error(`Lake battle fired a non-weapon item: ${event.weaponId}`);
        playPortableWeaponAttackSound(portable, event.count, distanceFromPlayer);
      } else {
        playNavalAttackSound({ kind: event.weaponKind }, event.count, distanceFromPlayer);
      }
    } else if (event.type === "hit") {
      if (event.weaponKind === NAVAL_WEAPON_ARROW) playArrowHitSound();
      else if (event.resisted) playArmorGlanceSound(18);
      else playCannonImpactSound(18);
    } else if (event.type === "collision") {
      playCannonImpactSound(8);
    } else if (event.type !== "finished") {
      throw new Error(`Unknown lake battle event: ${event.type}`);
    }
  }
}

function handleLakeBattlePointerDown(pointerId, point) {
  if (lakeBattleMode?.kind === "historical") {
    handleHistoricalBattlePointerDown(pointerId, point);
    return;
  }
  lakeBattleMode.hoverPoint = point;
  if (lakeBattleMode.loading) return;
  if (lakeBattleMode.screen === LAKE_BATTLE_SCREEN_SINKING) return;
  if (lakeBattleMode.screen === LAKE_BATTLE_SCREEN_SETUP) {
    for (let row = 0; row <= LAKE_BATTLE_SETUP_ENEMY_ROW; row++) {
      if (pointInRect(point, lakeBattleMode.leftArrowRects[row])) {
        lakeBattleMode.selectedIndex = row;
        stepLakeBattleShipSelection(row === 0 ? "player" : "enemy", -1);
        return;
      }
      if (pointInRect(point, lakeBattleMode.rightArrowRects[row])) {
        lakeBattleMode.selectedIndex = row;
        stepLakeBattleShipSelection(row === 0 ? "player" : "enemy", 1);
        return;
      }
    }
    for (let row = 0; row < lakeBattleMode.rowRects.length; row++) {
      if (!pointInRect(point, lakeBattleMode.rowRects[row])) continue;
      lakeBattleMode.selectedIndex = row;
      if (row >= LAKE_BATTLE_SETUP_BEGIN_ROW) activateLakeBattleSetupRow();
      dirty = true;
      return;
    }
    return;
  }
  if (lakeBattleMode.screen === LAKE_BATTLE_SCREEN_ACTIVE) {
    if (pointInRect(point, lakeBattleMode.pauseButtonRect)) {
      lakeBattleMode.screen = LAKE_BATTLE_SCREEN_PAUSED;
      lakeBattleMode.selectedIndex = 0;
      keys.clear();
      clearPointerSteering();
      dirty = true;
      return;
    }
    if (lakeBattleMode.replay) return;
    const broadside = lakeBattleBroadsideSideAtPoint(point);
    dispatchSailingPointerAction({
      type: broadside ? WORLD_POINTER_ACTION.BROADSIDE : WORLD_POINTER_ACTION.STEER,
      sideName: broadside || undefined
    }, {
      fireBroadside: fireLakeBattlePlayerBroadside,
      beginSteering: () => beginPointerSteering(pointerId, point)
    });
    return;
  }
  const actions = lakeBattleMode.screen === LAKE_BATTLE_SCREEN_PAUSED
    ? LAKE_BATTLE_PAUSE_ACTIONS
    : LAKE_BATTLE_RESULT_ACTIONS;
  for (let index = 0; index < lakeBattleMode.actionRects.length; index++) {
    if (!pointInRect(point, lakeBattleMode.actionRects[index])) continue;
    lakeBattleMode.selectedIndex = index;
    activateLakeBattleAction(actions[index]);
    return;
  }
}

function handleLakeBattlePointerMove(event, point) {
  if (lakeBattleMode?.kind === "historical") {
    handleHistoricalBattlePointerMove(event, point);
    return;
  }
  lakeBattleMode.hoverPoint = point;
  if (lakeBattleMode.screen === LAKE_BATTLE_SCREEN_SINKING) {
    dirty = true;
    return;
  }
  if (lakeBattleMode.screen === LAKE_BATTLE_SCREEN_ACTIVE &&
      pointerSteering.active && pointerSteering.pointerId === event.pointerId) {
    event.preventDefault();
    updatePointerSteering(point);
  } else if (lakeBattleMode.screen === LAKE_BATTLE_SCREEN_SETUP) {
    for (let row = 0; row < lakeBattleMode.rowRects.length; row++) {
      if (pointInRect(point, lakeBattleMode.rowRects[row])) lakeBattleMode.selectedIndex = row;
    }
  } else if (lakeBattleMode.screen === LAKE_BATTLE_SCREEN_PAUSED ||
             lakeBattleMode.screen === LAKE_BATTLE_SCREEN_RESULT) {
    for (let index = 0; index < lakeBattleMode.actionRects.length; index++) {
      if (pointInRect(point, lakeBattleMode.actionRects[index])) lakeBattleMode.selectedIndex = index;
    }
  }
  dirty = true;
}

function lakeBattleBroadsideArc(sideName) {
  const battle = lakeBattleMode?.battle;
  if (!battle) throw new Error("Cannot create lake broadside arc without a battle");
  const heading = lakeBattleHeadingVector(battle.player);
  const frames = battle.shipFootprints?.get(battle.player.slug);
  if (!frames) throw new Error(`Lake battle is missing hull footprints for ${battle.player.slug}`);
  const origin = { x: battle.player.x, y: battle.player.y };
  return broadsideArcGeometry({
    screenWidth: SCREEN_W,
    screenHeight: SCREEN_H,
    heading,
    sideName,
    range: lakeBattleWeaponRange(battle.player),
    origin,
    hullFootprint: translatedShipFootprint(
      shipFootprintFrame(frames, heading),
      origin.x,
      origin.y
    )
  });
}

function lakeBattleBroadsideSideAtPoint(point) {
  if (!lakeBattleMode?.battle || lakeBattleMode.screen !== LAKE_BATTLE_SCREEN_ACTIVE) return null;
  if (!navalWeaponUsesBroadside(lakeBattleMode.battle.player.weapon)) return null;
  for (const sideName of ["port", "starboard"]) {
    if (pointInBroadsideArc(point, lakeBattleBroadsideArc(sideName), 5)) return sideName;
  }
  return null;
}

function handleLakeBattleKeyDown(event, keyAction) {
  if (!lakeBattleMode) return;
  event.preventDefault();
  if (lakeBattleMode.kind === "historical") {
    handleHistoricalBattleKeyDown(event, keyAction);
    return;
  }
  if (lakeBattleMode.loading) return;
  if (lakeBattleMode.screen === LAKE_BATTLE_SCREEN_SINKING) return;
  if (lakeBattleMode.screen === LAKE_BATTLE_SCREEN_SETUP) {
    handleLakeBattleSetupKeyDown(event.key);
    return;
  }
  if (lakeBattleMode.screen === LAKE_BATTLE_SCREEN_ACTIVE) {
    if (keyAction === KEY_ACTION.CAPTAIN_MENU) {
      lakeBattleMode.screen = LAKE_BATTLE_SCREEN_PAUSED;
      lakeBattleMode.selectedIndex = 0;
      keys.clear();
      clearPointerSteering();
    } else if (keyAction === KEY_ACTION.FIRE_PORT || keyAction === KEY_ACTION.FIRE_STARBOARD) {
      if (!event.repeat) fireLakeBattlePlayerBroadside(
        keyAction === KEY_ACTION.FIRE_PORT ? "port" : "starboard"
      );
    } else if (isSteeringKeyAction(keyAction)) {
      keys.press(event.code, keyAction);
    }
    dirty = true;
    return;
  }
  if (lakeBattleMode.screen === LAKE_BATTLE_SCREEN_PAUSED) {
    handleLakeBattleActionMenuKeyDown(event.key, LAKE_BATTLE_PAUSE_ACTIONS);
    return;
  }
  if (lakeBattleMode.screen === LAKE_BATTLE_SCREEN_RESULT) {
    handleLakeBattleActionMenuKeyDown(event.key, LAKE_BATTLE_RESULT_ACTIONS);
    return;
  }
  throw new Error(`Unknown lake battle screen: ${lakeBattleMode.screen}`);
}

function handleHistoricalBattlePointerDown(pointerId, point) {
  lakeBattleMode.hoverPoint = point;
  if (lakeBattleMode.loading) return;
  if (lakeBattleMode.screen === LAKE_BATTLE_SCREEN_SETUP) {
    const selectors = ["scenario", "side", "squadron"];
    for (let row = 0; row < selectors.length; row++) {
      if (pointInRect(point, lakeBattleMode.leftArrowRects[row])) {
        lakeBattleMode.selectedIndex = row;
        stepHistoricalBattleSelection(selectors[row], -1);
        return;
      }
      if (pointInRect(point, lakeBattleMode.rightArrowRects[row])) {
        lakeBattleMode.selectedIndex = row;
        stepHistoricalBattleSelection(selectors[row], 1);
        return;
      }
    }
    for (let row = 0; row < lakeBattleMode.rowRects.length; row++) {
      if (!pointInRect(point, lakeBattleMode.rowRects[row])) continue;
      lakeBattleMode.selectedIndex = row;
      if (row >= HISTORICAL_BATTLE_SETUP_BEGIN_ROW) activateHistoricalBattleSetupRow();
      dirty = true;
      return;
    }
    return;
  }
  if (lakeBattleMode.screen === LAKE_BATTLE_SCREEN_ACTIVE) {
    if (pointInRect(point, lakeBattleMode.pauseButtonRect)) {
      lakeBattleMode.screen = LAKE_BATTLE_SCREEN_PAUSED;
      lakeBattleMode.selectedIndex = 0;
      clearHistoricalBattlePendingActions();
      keys.clear();
      clearPointerSteering();
      dirty = true;
      return;
    }
    for (const command of lakeBattleMode.commandRects) {
      if (!pointInRect(point, command.rect)) continue;
      lakeBattleMode.pendingUnitCommand = {
        shipIndex: lakeBattleMode.selectedShipIndex,
        action: command.action
      };
      lakeBattleMode.selectedShipIndex = -1;
      lakeBattleMode.commandSelectedIndex = 0;
      lakeBattleMode.commandRects = [];
      dirty = true;
      return;
    }
    const worldPoint = historicalBattleScreenToWorld(point);
    const selectedShip = historicalBattleShipAtPoint(
      lakeBattleMode.battle,
      worldPoint.x,
      worldPoint.y,
      15
    );
    if (selectedShip && !selectedShip.playerControlled) {
      lakeBattleMode.selectedShipIndex = lakeBattleMode.battle.ships.indexOf(selectedShip);
      lakeBattleMode.commandSelectedIndex = 0;
      dirty = true;
      return;
    }
    lakeBattleMode.selectedShipIndex = -1;
    lakeBattleMode.commandSelectedIndex = 0;
    lakeBattleMode.commandRects = [];
    const broadside = historicalBattleBroadsideSideAtPoint(point);
    dispatchSailingPointerAction({
      type: broadside ? WORLD_POINTER_ACTION.BROADSIDE : WORLD_POINTER_ACTION.STEER,
      sideName: broadside || undefined
    }, {
      fireBroadside: fireHistoricalBattlePlayerBroadside,
      beginSteering: () => beginPointerSteering(pointerId, point)
    });
    return;
  }
  const actions = lakeBattleMode.screen === LAKE_BATTLE_SCREEN_PAUSED
    ? HISTORICAL_BATTLE_PAUSE_ACTIONS
    : historicalBattleResultActions();
  for (let index = 0; index < lakeBattleMode.actionRects.length; index++) {
    if (!pointInRect(point, lakeBattleMode.actionRects[index])) continue;
    lakeBattleMode.selectedIndex = index;
    activateHistoricalBattleAction(actions[index]);
    return;
  }
}

function historicalBattleScreenToWorld(point) {
  const cameraValue = lakeBattleMode?.camera;
  if (!cameraValue) throw new Error("Historical battle camera is missing");
  return {
    x: point.x + cameraValue.x - SCREEN_W / 2,
    y: point.y + cameraValue.y - SCREEN_H / 2
  };
}

function handleHistoricalBattlePointerMove(event, point) {
  lakeBattleMode.hoverPoint = point;
  if (lakeBattleMode.screen === LAKE_BATTLE_SCREEN_ACTIVE &&
      pointerSteering.active && pointerSteering.pointerId === event.pointerId) {
    event.preventDefault();
    updatePointerSteering(point);
  } else if (lakeBattleMode.screen === LAKE_BATTLE_SCREEN_ACTIVE) {
    for (let index = 0; index < lakeBattleMode.commandRects.length; index++) {
      if (pointInRect(point, lakeBattleMode.commandRects[index].rect)) {
        lakeBattleMode.commandSelectedIndex = index;
      }
    }
  } else if (lakeBattleMode.screen === LAKE_BATTLE_SCREEN_SETUP) {
    for (let row = 0; row < lakeBattleMode.rowRects.length; row++) {
      if (pointInRect(point, lakeBattleMode.rowRects[row])) lakeBattleMode.selectedIndex = row;
    }
  } else if (lakeBattleMode.screen === LAKE_BATTLE_SCREEN_PAUSED ||
             lakeBattleMode.screen === LAKE_BATTLE_SCREEN_RESULT) {
    for (let index = 0; index < lakeBattleMode.actionRects.length; index++) {
      if (pointInRect(point, lakeBattleMode.actionRects[index])) lakeBattleMode.selectedIndex = index;
    }
  }
  dirty = true;
}

function handleHistoricalBattleKeyDown(event, keyAction) {
  if (lakeBattleMode.loading) return;
  if (lakeBattleMode.screen === LAKE_BATTLE_SCREEN_SETUP) {
    handleHistoricalBattleSetupKeyDown(event.key);
    return;
  }
  if (lakeBattleMode.screen === LAKE_BATTLE_SCREEN_ACTIVE) {
    if (event.key === "Escape" && lakeBattleMode.selectedShipIndex >= 0) {
      lakeBattleMode.selectedShipIndex = -1;
      lakeBattleMode.commandSelectedIndex = 0;
      lakeBattleMode.commandRects = [];
    } else if (keyAction === KEY_ACTION.CAPTAIN_MENU || event.key === "Escape") {
      lakeBattleMode.screen = LAKE_BATTLE_SCREEN_PAUSED;
      lakeBattleMode.selectedIndex = 0;
      clearHistoricalBattlePendingActions();
      keys.clear();
      clearPointerSteering();
    } else if (lakeBattleMode.selectedShipIndex >= 0 &&
               (event.key === "ArrowUp" || event.key === "ArrowDown")) {
      const selectedShip = lakeBattleMode.battle.ships[lakeBattleMode.selectedShipIndex];
      const commandCount = historicalBattleCommandActions(
        lakeBattleMode.battle,
        selectedShip
      ).length;
      lakeBattleMode.commandSelectedIndex = stepMenuIndex(
        lakeBattleMode.commandSelectedIndex,
        event.key === "ArrowDown" ? 1 : -1,
        commandCount
      );
    } else if (lakeBattleMode.selectedShipIndex >= 0 &&
               (event.key === "Enter" || event.key === " ")) {
      const selectedShip = lakeBattleMode.battle.ships[lakeBattleMode.selectedShipIndex];
      const command = historicalBattleCommandActions(
        lakeBattleMode.battle,
        selectedShip
      )[lakeBattleMode.commandSelectedIndex];
      if (!command) throw new Error("Historical battle command menu has no selected command");
      lakeBattleMode.pendingUnitCommand = {
        shipIndex: lakeBattleMode.selectedShipIndex,
        action: command.action
      };
      lakeBattleMode.selectedShipIndex = -1;
      lakeBattleMode.commandSelectedIndex = 0;
      lakeBattleMode.commandRects = [];
    } else if (!lakeBattleMode.replay &&
               (keyAction === KEY_ACTION.FIRE_PORT || keyAction === KEY_ACTION.FIRE_STARBOARD)) {
      if (!event.repeat) fireHistoricalBattlePlayerBroadside(
        keyAction === KEY_ACTION.FIRE_PORT ? "port" : "starboard"
      );
    } else if (!lakeBattleMode.replay && isSteeringKeyAction(keyAction)) {
      keys.press(event.code, keyAction);
    }
    dirty = true;
    return;
  }
  const actions = lakeBattleMode.screen === LAKE_BATTLE_SCREEN_PAUSED
    ? HISTORICAL_BATTLE_PAUSE_ACTIONS
    : historicalBattleResultActions();
  handleHistoricalBattleActionMenuKeyDown(event.key, actions);
}

function handleHistoricalBattleSetupKeyDown(key) {
  if (key === "Escape") {
    closeLakeBattleModeToStartMenu();
    return;
  }
  if (key === "ArrowUp" || key === "ArrowDown") {
    lakeBattleMode.selectedIndex = stepMenuIndex(
      lakeBattleMode.selectedIndex,
      key === "ArrowDown" ? 1 : -1,
      HISTORICAL_BATTLE_SETUP_ROW_COUNT
    );
    dirty = true;
    return;
  }
  if (key === "ArrowLeft" || key === "ArrowRight") {
    const selector = ["scenario", "side", "squadron"][lakeBattleMode.selectedIndex];
    if (selector) stepHistoricalBattleSelection(selector, key === "ArrowRight" ? 1 : -1);
    return;
  }
  if (key === "Enter" || key === " ") activateHistoricalBattleSetupRow();
}

function activateHistoricalBattleSetupRow() {
  const selector = ["scenario", "side", "squadron"][lakeBattleMode.selectedIndex];
  if (selector) {
    stepHistoricalBattleSelection(selector, 1);
  } else if (lakeBattleMode.selectedIndex === HISTORICAL_BATTLE_SETUP_BEGIN_ROW) {
    void beginHistoricalBattle();
  } else if (lakeBattleMode.selectedIndex === HISTORICAL_BATTLE_SETUP_BACK_ROW) {
    closeLakeBattleModeToStartMenu();
  }
}

function handleHistoricalBattleActionMenuKeyDown(key, actions) {
  if (key === "Escape") {
    if (lakeBattleMode.screen === LAKE_BATTLE_SCREEN_PAUSED) {
      lakeBattleMode.screen = LAKE_BATTLE_SCREEN_ACTIVE;
      lakeBattleMode.selectedIndex = 0;
    } else {
      returnHistoricalBattleToSetup();
    }
    dirty = true;
    return;
  }
  if (key === "ArrowUp" || key === "ArrowDown") {
    lakeBattleMode.selectedIndex = stepMenuIndex(
      lakeBattleMode.selectedIndex,
      key === "ArrowDown" ? 1 : -1,
      actions.length
    );
    dirty = true;
    return;
  }
  if (key === "Enter" || key === " ") activateHistoricalBattleAction(actions[lakeBattleMode.selectedIndex]);
}

function activateHistoricalBattleAction(action) {
  if (action === "RESUME") {
    lakeBattleMode.screen = LAKE_BATTLE_SCREEN_ACTIVE;
  } else if (action === "RESTART" || action === "REMATCH") {
    restartHistoricalBattle();
  } else if (action === "WATCH REPLAY") {
    watchLatestHistoricalBattleReplay();
  } else if (action === "CHOOSE BATTLE") {
    returnHistoricalBattleToSetup();
  } else if (action === "OPTIONS") {
    openOptionsMenu();
  } else if (action === "START MENU") {
    closeLakeBattleModeToStartMenu();
  } else {
    throw new Error(`Unknown historical battle action: ${action}`);
  }
  dirty = true;
}

function historicalBattleBroadsideArc(sideName) {
  const battle = lakeBattleMode?.kind === "historical" ? lakeBattleMode.battle : null;
  if (!battle) throw new Error("Cannot create historical broadside arc without a battle");
  const player = historicalBattlePlayerShip(battle);
  const origin = historicalBattleWorldToScreen(player);
  const heading = { x: Math.cos(player.headingRad), y: Math.sin(player.headingRad) };
  const frames = battle.shipFootprints?.get(player.shipSlug);
  if (!frames) throw new Error(`Historical battle is missing hull footprints for ${player.shipSlug}`);
  return broadsideArcGeometry({
    screenWidth: SCREEN_W,
    screenHeight: SCREEN_H,
    heading,
    sideName,
    range: player.weaponRangePx,
    origin,
    hullFootprint: translatedShipFootprint(
      shipFootprintFrame(frames, heading),
      origin.x,
      origin.y
    )
  });
}

function historicalBattleBroadsideSideAtPoint(point) {
  if (lakeBattleMode?.kind !== "historical" ||
      !lakeBattleMode.battle || lakeBattleMode.screen !== LAKE_BATTLE_SCREEN_ACTIVE) return null;
  for (const sideName of ["port", "starboard"]) {
    if (pointInBroadsideArc(point, historicalBattleBroadsideArc(sideName), 5)) return sideName;
  }
  return null;
}

function handleLakeBattleSetupKeyDown(key) {
  if (key === "Escape") {
    closeLakeBattleModeToStartMenu();
    return;
  }
  if (key === "ArrowUp" || key === "ArrowDown") {
    lakeBattleMode.selectedIndex = stepMenuIndex(
      lakeBattleMode.selectedIndex,
      key === "ArrowDown" ? 1 : -1,
      LAKE_BATTLE_SETUP_ROW_COUNT
    );
    dirty = true;
    return;
  }
  if ((key === "ArrowLeft" || key === "ArrowRight") && lakeBattleMode.selectedIndex <= LAKE_BATTLE_SETUP_ENEMY_ROW) {
    stepLakeBattleShipSelection(
      lakeBattleMode.selectedIndex === LAKE_BATTLE_SETUP_PLAYER_ROW ? "player" : "enemy",
      key === "ArrowRight" ? 1 : -1
    );
    return;
  }
  if (key === "Enter" || key === " ") activateLakeBattleSetupRow();
}

function activateLakeBattleSetupRow() {
  if (lakeBattleMode.selectedIndex === LAKE_BATTLE_SETUP_PLAYER_ROW) {
    stepLakeBattleShipSelection("player", 1);
  } else if (lakeBattleMode.selectedIndex === LAKE_BATTLE_SETUP_ENEMY_ROW) {
    stepLakeBattleShipSelection("enemy", 1);
  } else if (lakeBattleMode.selectedIndex === LAKE_BATTLE_SETUP_BEGIN_ROW) {
    void beginLakeBattle();
  } else if (lakeBattleMode.selectedIndex === LAKE_BATTLE_SETUP_BACK_ROW) {
    closeLakeBattleModeToStartMenu();
  }
}

function handleLakeBattleActionMenuKeyDown(key, actions) {
  if (key === "Escape") {
    if (lakeBattleMode.screen === LAKE_BATTLE_SCREEN_PAUSED) {
      lakeBattleMode.screen = LAKE_BATTLE_SCREEN_ACTIVE;
      lakeBattleMode.selectedIndex = 0;
    } else {
      returnLakeBattleToSetup();
    }
    dirty = true;
    return;
  }
  if (key === "ArrowUp" || key === "ArrowDown") {
    lakeBattleMode.selectedIndex = stepMenuIndex(
      lakeBattleMode.selectedIndex,
      key === "ArrowDown" ? 1 : -1,
      actions.length
    );
    dirty = true;
    return;
  }
  if (key === "Enter" || key === " ") activateLakeBattleAction(actions[lakeBattleMode.selectedIndex]);
}

function activateLakeBattleAction(action) {
  if (action === "RESUME") {
    lakeBattleMode.screen = LAKE_BATTLE_SCREEN_ACTIVE;
  } else if (action === "RESTART" || action === "REMATCH") {
    restartLakeBattle();
  } else if (action === "CHOOSE SHIPS") {
    returnLakeBattleToSetup();
  } else if (action === "OPTIONS") {
    openOptionsMenu();
  } else if (action === "START MENU") {
    closeLakeBattleModeToStartMenu();
  } else {
    throw new Error(`Unknown lake battle action: ${action}`);
  }
  dirty = true;
}

function closeStartMenu() {
  startMenu = null;
  keys.clear();
  clearPointerSteering();
  dirty = true;
}

function startNewVoyage() {
  familyDebtReturnReminderDelivered = false;
  if (localSaveResult.status === "ready") {
    if (!archiveSavedVoyageBeforeStartingOver()) {
      throw new Error("Could not archive the current voyage before starting over");
    }
    const voyageWasStarted = hasStartedVoyage;
    hasStartedVoyage = false;
    try {
      clearLocalSave();
      const clearedSave = readLocalSave();
      if (clearedSave.status !== "empty") {
        throw new Error(`Local save was not empty after deletion: ${clearedSave.status}`);
      }
      localSaveResult = clearedSave;
    } catch (error) {
      hasStartedVoyage = voyageWasStarted;
      throw error;
    }
    window.location.reload();
    return;
  }
  sailingTutorialState = createSailingTutorialState();
  resetStormPassageState(stormPassageState);
  resetStormWaveState(stormWaveState);
  overboardCrew = [];
  playerBoundaryAssistContact = null;
  playerBoundaryProbeCache = null;
  playerNavigationRecoveryState = createPlayerShipRecoveryState();
  gameState.memory.flags.sailingBasicsElapsedSeconds = 0;
  reframeWorldNorthUp("new voyage");
  captureVoyageStartProfile(gameState);
  if (BUILD_EDITION_ID === "full" && achievementProfile) {
    recordCampaignVoyageStart(achievementProfile, gameState.memory.campaignGoal.type);
    writeAchievementProfile(achievementProfile);
    achievementProfileResult = { status: "ready", profile: achievementProfile, error: null };
  }
  hasStartedVoyage = true;
  gameTelemetry.recordVoyageStart(gameState, { force: true });
  closeStartMenu();
  revealMinimapFromChart(chart, chartOffsetPixels(chart));
  saveVoyageNow("new voyage");
}

function archiveSavedVoyageBeforeStartingOver() {
  const payload = localSaveResult.status === "ready" ? localSaveResult.save?.payload : null;
  if (!payload) return false;
  try {
    const { gameState: savedState } = migrateSavedVoyageCore(payload);
    const record = createPastVoyageRecord({
      state: savedState,
      playerShip: payload.playerShip,
      startMinute: payload.worldClock.voyageStartMinute,
      endMinute: payload.worldClock.currentMinute,
      outcome: "Voyage abandoned for a new expedition.",
      outcomeType: "quit"
    });
    if (!storePastVoyage(record)) {
      throw new Error("Could not store the abandoned voyage in voyage history");
    }
    return true;
  } catch (error) {
    console.warn("[pixel-globe] could not archive the abandoned voyage", error);
    return false;
  }
}

async function continueSavedVoyage() {
  if (!startMenu || startMenu.isLoading || localSaveResult.status !== "ready") return;
  const menu = startMenu;
  menu.isLoading = true;
  menu.message = "";
  dirty = true;
  try {
    const restoration = await restoreSavedVoyage(localSaveResult.save.payload);
    hasStartedVoyage = true;
    gameTelemetry.recordVoyageStart(gameState);
    closeStartMenu();
    revealMinimapFromChart(chart, chartOffsetPixels(chart));
    saveVoyageNow("continued voyage");
    if (restoration.grandfatheredWorldwideDemo) {
      showSurvivalNotice("WORLDWIDE VOYAGE GRANDFATHERED", "good");
    } else if (restoration.recoveredDerivedSystems.length > 0) {
      showSurvivalNotice("OLD SAVE UPDATED", "good");
    }
  } catch (error) {
    console.warn("[pixel-globe] could not continue the local save", error);
    gameTelemetry.captureCrash(error, telemetryCrashContext("save-restore"));
    localSaveResult = { status: "invalid", save: null, error };
    if (startMenu === menu) {
      menu.isLoading = false;
      menu.selectedIndex = 0;
      menu.message = "SAVE COULD NOT BE LOADED";
    }
    dirty = true;
  }
}

async function restoreSavedVoyage(payload) {
  resetStormPassageState(stormPassageState);
  resetStormWaveState(stormWaveState);
  const {
    savedShip,
    shipStats: stats,
    gameState: restoredGameState
  } = migrateSavedVoyageCore(payload);
  const restoredDemoVoyageScope = demoVoyageScopeForSavedGame({
    buildEditionId: BUILD_EDITION_ID,
    savedScope: payload.demoVoyageScope,
    savedGameStateVersion: payload.gameState?.version
  });
  const grandfatheredWorldwideDemo = BUILD_EDITION_ID === "demo" &&
    payload.demoVoyageScope === undefined &&
    restoredDemoVoyageScope !== DEMO_VOYAGE_SCOPE_MEDITERRANEAN;
  demoVoyageScope = restoredDemoVoyageScope;
  const restoredWorldClock = recoverSavedVoyageWorldClock(payload, restoredGameState);
  if (restoredWorldClock.recoveredDebtClockMinutes > 0) {
    console.warn(
      "[pixel-globe] repaired saved world clock behind family debt ledger:",
      restoredWorldClock.recoveredDebtClockMinutes
    );
  }
  const correctedPortraitMetadataCount = reconcileCharacterPortraitMetadata(
    restoredGameState,
    characterPortraitManifest
  );
  if (correctedPortraitMetadataCount > 0) {
    console.info("[pixel-globe] corrected portrait metadata for saved characters:", correctedPortraitMetadataCount);
  }
  const correctedCharacterNameCount = reconcileRegionalCharacterNameForms(restoredGameState);
  if (correctedCharacterNameCount > 0) {
    console.info("[pixel-globe] corrected cultural name forms for saved characters:", correctedCharacterNameCount);
  }
  ensureWhalePopulation(restoredGameState);
  gameState = restoredGameState;
  syncColonizationWorldState(restoredGameState, {
    startMinute: Number.isFinite(payload.economy?.lastMinute)
      ? payload.economy.lastMinute
      : restoredWorldClock.currentMinute
  });
  applyCurrentPortConquestOwnership({ refreshMaltaQuest: false });
  const assets = await loadShipAssetSet(savedShip.typeSlug);
  let recoveredDerivedSystems = restoreSavedDerivedWorld(payload, restoredGameState);

  ensureColonizationDefenseEncounter({ assignCaptains: false });
  ensureTreasureCampaignEncounters({ assignCaptains: false });
  pendingWineCaptainDialogues.length = 0;
  pendingFetchQuestCaptainDialogues.length = 0;
  initializeFetchQuestReadiness();
  consumedLandedSeagullIds.clear();
  familyDebtReturnReminderDelivered = false;
  restoreCartographyFromGameState();
  applyCurrentPortConquestOwnership({ refreshMaltaQuest: false });
  if (!gameState.memory.flags || typeof gameState.memory.flags !== "object") {
    gameState.memory.flags = {};
  }
  sailingTutorialState = createSailingTutorialState({
    earlyWindowSeconds: Number.isFinite(gameState.memory.flags.sailingBasicsElapsedSeconds)
      ? gameState.memory.flags.sailingBasicsElapsedSeconds
      : EARLY_SAILING_HELP_WINDOW_SECONDS
  });
  reconcileQuestPortTiles(gameState, portCities);
  shipImage = assets.image;
  shipSinkDepthImage = assets.sinkDepthImage;
  shipWakeAnchors = requiredShipWakeAnchors(savedShip.typeSlug);
  shipLighting = assets.lighting;
  weatherClockMinutes = restoredWorldClock.currentMinute;
  voyageStartClockMinutes = restoredWorldClock.voyageStartMinute;
  weatherParts = weatherClockParts(weatherClockMinutes);
  refreshHospitallerMaltaQuestState();
  refreshWeatherState(true);
  activeIcebergSpawnCandidatesDay = -1;
  activeIcebergSpawnCandidates = [];
  icebergCollisionMomentum.clear();
  ensureIcebergPopulation(gameState);

  const savedPosition = normalize3(savedShip.position.slice());
  const positionTileId = findNearestTileId(graph, directionIndex, savedPosition);
  const savedTileExists = Number.isInteger(savedShip.tileId) &&
    savedShip.tileId >= 0 &&
    savedShip.tileId < graph.tileCount;
  const savedTileNavigable = savedTileExists && isShipBaseNavigableTile(savedShip.tileId);
  const recoverySearchTileId = savedTileExists ? savedShip.tileId : positionTileId;
  const nearestNavigableTileId = savedTileNavigable
    ? undefined
    : (
      isShipBaseNavigableTile(positionTileId) && !isShipBlockedByIceTile(positionTileId)
        ? positionTileId
        : nearestTileMatching(
          recoverySearchTileId,
          (tileId) => isShipBaseNavigableTile(tileId) && !isShipBlockedByIceTile(tileId)
        )
    );
  const frozenSavedTile = savedTileNavigable && isShipBlockedByIceTile(savedShip.tileId);
  const nearestOpenWaterTileId = frozenSavedTile
    ? nearestTileMatching(savedShip.tileId, isShipOpenWaterTile)
    : undefined;
  const restorePlacement = restoredShipPlacementPlan({
    savedTileId: savedTileExists ? savedShip.tileId : positionTileId,
    positionTileId,
    savedTileNavigable,
    nearestNavigableTileId,
    frozen: frozenSavedTile,
    nearestOpenWaterTileId
  });
  if (!savedTileNavigable) {
    recoveredDerivedSystems = addDerivedSaveRecoveryLabel(
      recoveredDerivedSystems,
      "ship placement"
    );
  }
  const position = restorePlacement.recenter
    ? tileCenterVector(restorePlacement.tileId)
    : savedPosition;
  const savedLat = latitudeDegForDirection(position);
  const savedLon = longitudeDegForDirection(position);
  ship = createShip(savedLat, savedLon, savedShip.typeSlug, savedShip.factionId);
  ship.position = position;
  ship.tileId = restorePlacement.tileId;
  firstDayNightNoticeState = restoreFirstDayNightNoticeState(
    payload.firstDayNightNotices,
    dot3(ship.position, currentSunDirection())
  );
  ship.heading = normalizeTangentOrFallback(savedShip.heading, position, WORLD_NORTH);
  ship.targetHeading = normalizeTangentOrFallback(savedShip.targetHeading, position, ship.heading);
  ship.velocity = restorePlacement.stop ? [0, 0, 0] : savedShip.velocity.slice();
  const restoredHull = reconcileShipHullForCurrentStats(
    ship.stats,
    savedShip.hitPoints,
    savedShip.maxHitPoints
  );
  ship.hitPoints = restoredHull.hitPoints;
  ship.maxHitPoints = restoredHull.maxHitPoints;
  ship.wakeSeedCounter = savedShip.wakeSeedCounter || 0;
  ship.cannonSequence = savedShip.cannonSequence || 0;
  ship.cannonCooldowns = { port: 0, starboard: 0 };
  ship.portableWeaponCooldowns = {};
  ship.woundedCrew = 0;
  ship.wakeParticles = [];
  ship.lastWakeEmit = null;
  ship.navalProjectiles = [];
  ship.cannonSplashes = [];
  overboardCrew = restoreOverboardCrew(savedShip.overboardCrew);
  cannonSmokeBursts = [];
  hullSplinterBursts = [];

  anchored = payload.anchored;
  initialAnimalEncounterRollPending = false;
  survivalDeprivationTimers.waterNextMinute = finiteMinuteOrNull(payload.survivalDamageTimers?.waterNextMinute);
  survivalDeprivationTimers.foodNextMinute = finiteMinuteOrNull(payload.survivalDamageTimers?.foodNextMinute);
  playerIntroModal = gameState.memory.campaignGoal?.introSeen === false
    ? createPlayerIntroModal(gameState.playerCharacter)
    : null;
  captainAlertModal = null;
  dialogueState = null;
  dialogueShipMotionPause = null;
  dialogueLayout = createDialogueLayoutState();
  fishingAction = null;
  whaleHarpoonProjectile = null;
  whaleBlowBursts = [];
  whaleKillEffects = [];
  itemAcquisitionEffects = [];
  goldTreasureSequence = null;
  shoreScavengeAction = null;
  portWaitState = null;
  portWaitButtonRect = null;
  discoveryNotice = null;
  discoveryNoticeQueue.length = 0;
  fishCatchNotice = null;
  achievementNotice = null;
  achievementNoticeRect = null;
  achievementNoticeHoverPoint = null;
  achievementNoticeQueue.length = 0;
  gameOverReason = null;
  gameOverState = null;
  npcVisualShips.clear();
  npcVisualSnapshotCache.reset();
  shoreBatteryStates.clear();
  npcVisualMovementBucket = 0;
  shoreBatteryUpdateAccumulator = 0;
  whaleSimulationAccumulator = 0;
  whaleBackgroundMovementBucket = 0;
  whaleVisualPresentations.clear();
  ambientAudioUpdateAccumulator = 0;
  ambientAudioContextAccumulator = 0;
  ambientAudioWildlifeAccumulator = 0;
  ambientAudioContext = null;
  ambientAudioWildlife = null;
  resetWorldClockFrameSlices();
  pendingWeatherMaskRefresh = null;
  worldSimulationScheduler = createWorldSimulationScheduler();
  pendingDistantWorldEvents.length = 0;
  worldSpatialIndex.clear();
  worldSpatialChart = null;
  worldSpatialWildlifeChart = null;
  responsiveWhaleIds = new Set();
  npcCombatProjectiles = [];
  npcCombatSplashes = [];
  pendingNpcCombatHailId = null;
  shipCombatState.engagements.clear();
  clearFriendlyFireIncidents(playerFriendlyFireIncidents);
  playerFriendlyFirePenaltyFactionIds.clear();
  shipCollisionCooldowns.clear();
  shipCombatEntryCollisionGrace.clear();
  playerHaulBlockedSeconds = 0;
  playerBoundaryAssistContact = null;
  playerBoundaryProbeCache = null;
  playerNavigationRecoveryState = createPlayerShipRecoveryState();
  keys.clear();
  clearPointerSteering();

  assignPortCharactersForPlayer(gameState.playerCharacter, namedCrewMembers(gameState));
  // Regenerating factors clears special quest characters. Rebind the colony
  // organizer before the restored chart creates its interactive city calls.
  syncColonizationWorldState(gameState, { startMinute: weatherClockMinutes });
  ensureNaturalistCharacter(gameState);
  for (const character of pirateHideoutCharacters.values()) usedCharacterNames.add(character.name);
  campaignGoalContact = createCampaignGoalContact(gameState.playerCharacter, gameState.memory.campaignGoal);
  npcShipCaptains = assignNpcShipCaptains(
    npcSeaRoutes.ships,
    characterPortraitManifest,
    usedCharacterNames,
    { excludedSourceIds: playerPortraitSourceExclusions(gameState.playerCharacter) }
  );
  reconcileEnglishReformationCharacters();
  synchronizeTreasurePirateCaptains();
  await ensureCharacterPortraitLoaded(gameState.playerCharacter, characterExpression(gameState.playerCharacter));
  syncShipCargoFromGameState();
  camera = northUpCamera(ship.position);
  centerTileId = ship.tileId;
  localLayout = createLocalLayout(centerTileId);
  chart = buildChart(camera);
  reconcileRestoredShipDrawnNavigation(restorePlacement.reason);
  reframeWorldNorthUp("continued voyage");
  await loadInitialNearbyWorldAssets();
  resetDistantWorldWorkerSchedule();
  resetPlayerWindState();
  windIndicatorState = null;
  setBackgroundMusicTrack("ship", { force: true });
  lastAutosaveMs = performance.now();
  dirty = true;
  return { recoveredDerivedSystems, grandfatheredWorldwideDemo };
}

function restoreSavedDerivedWorld(payload, restoredGameState) {
  const recovered = [];
  const simulationMinute = Number.isFinite(payload.economy?.lastMinute)
    ? payload.economy.lastMinute
    : payload.worldClock.currentMinute;
  const seedKey = restoredGameState.voyageSeed;

  const economyResult = restoreOrRecreateDerivedSaveState({
    label: "world economy",
    current: worldEconomy,
    recreate: () => createSavedVoyageEconomy(simulationMinute, seedKey),
    restore: (candidate) => restoreWorldEconomy(candidate, payload.economy, { seedKey })
  });
  worldEconomy = economyResult.value;
  recordDerivedSaveRecovery(recovered, "world economy", economyResult.error);
  syncJapaneseMatchlockIndustry(restoredGameState);
  syncCaribbeanGingerIndustry(restoredGameState);

  const createLandTrade = () => createLandTradeSystem({
    roads: landRoadNetwork,
    economy: worldEconomy,
    cities: [...cityByTileId.values()],
    startMinute: simulationMinute,
    seedKey,
    relationBetween: currentDiplomacyBetween,
    foreignSettlementExpulsions: restoredGameState.relations.foreignSettlementExpulsions,
    sovereignTradeOpenToFaction: (policyId, factionId) => (
      sovereignTradeOpenToFaction(restoredGameState, policyId, factionId)
    ),
    suzeraintyMemory: restoredGameState.relations.diplomacy.suzerainties
  });
  landTradeSystem.economy = worldEconomy;
  if (payload.landTrade) {
    const landTradeResult = restoreOrRecreateDerivedSaveState({
      label: "land trade",
      current: landTradeSystem,
      recreate: createLandTrade,
      restore: (candidate) => restoreLandTradeSystem(candidate, payload.landTrade, {
        seedKey,
        relationBetween: currentDiplomacyBetween,
        foreignSettlementExpulsions: restoredGameState.relations.foreignSettlementExpulsions,
        sovereignTradeOpenToFaction: (policyId, factionId) => (
          sovereignTradeOpenToFaction(restoredGameState, policyId, factionId)
        ),
        suzeraintyMemory: restoredGameState.relations.diplomacy.suzerainties
      })
    });
    landTradeSystem = landTradeResult.value;
    recordDerivedSaveRecovery(recovered, "land trade", landTradeResult.error);
  } else {
    console.info("[pixel-globe] migrating voyage save: seeding land carts at the saved economy minute");
    landTradeSystem = createLandTrade();
  }

  const economyBeforeNpcRestore = snapshotWorldEconomy(worldEconomy);
  const npcRoutesResult = restoreOrRecreateDerivedSaveState({
    label: "NPC sea routes",
    current: npcSeaRoutes,
    recreate: () => {
      restoreWorldEconomy(worldEconomy, economyBeforeNpcRestore, { seedKey });
      return createSavedVoyageNpcRoutes(simulationMinute, restoredGameState);
    },
    restore: (candidate) => restoreNpcSeaRouteSystem(candidate, payload.npcRoutes, {
      economy: worldEconomy,
      fishState: restoredGameState,
      whaleMemory: restoredGameState.memory.whales,
      seedKey,
      relationBetween: currentDiplomacyBetween,
      foreignSettlementExpulsions: restoredGameState.relations.foreignSettlementExpulsions,
      sovereignTradeOpenToFaction: (policyId, factionId) => (
        sovereignTradeOpenToFaction(restoredGameState, policyId, factionId)
      ),
      suzeraintyMemory: restoredGameState.relations.diplomacy.suzerainties
    })
  });
  npcSeaRoutes = npcRoutesResult.value;
  recordDerivedSaveRecovery(recovered, "NPC sea routes", npcRoutesResult.error);
  return Object.freeze(recovered);
}

function createSavedVoyageEconomy(simulationMinute, seedKey) {
  const economy = createWorldEconomy({
    ports: [...cityByTileId.values()],
    shipyardPorts: portCities,
    startMinute: simulationMinute,
    seedKey
  });
  connectNearbyPortMarkets(economy, portCities, sailingDistanceBetweenPorts);
  return economy;
}

function createSavedVoyageNpcRoutes(simulationMinute, restoredGameState) {
  return createNpcSeaRouteSystem({
    ports: portCities,
    startMinute: simulationMinute,
    economy: worldEconomy,
    fishState: restoredGameState,
    fishingGroundIsNavigable: npcFishingGroundIsNavigable,
    whaleMemory: restoredGameState.memory.whales,
    seedKey: restoredGameState.voyageSeed,
    relationBetween: currentDiplomacyBetween,
    foreignSettlementExpulsions: restoredGameState.relations.foreignSettlementExpulsions,
    sovereignTradeOpenToFaction: (policyId, factionId) => (
      sovereignTradeOpenToFaction(restoredGameState, policyId, factionId)
    ),
    suzeraintyMemory: restoredGameState.relations.diplomacy.suzerainties,
    onForeignPortCall: recordNpcDiplomaticPortCall
  });
}

function npcFishingGroundIsNavigable({ lat, lon }) {
  if (!Number.isFinite(lat) || !Number.isFinite(lon)) {
    throw new Error(`NPC fishing ground requires finite coordinates: ${lat},${lon}`);
  }
  const tileId = findNearestTileId(graph, directionIndex, latLonToDirection(lat, lon));
  return earthById[tileId]?.t === "water";
}

function recordDerivedSaveRecovery(recovered, label, error) {
  if (!error) return;
  console.error(`[pixel-globe] ${label} snapshot was incompatible; regenerated current state`, error);
  recovered.push(label);
}

function reconcileRestoredShipDrawnNavigation(initialReason = null) {
  let recovery = nearestValidRestoredShipPlacement();
  let reason = initialReason;

  if (!recovery) {
    const previousTileId = ship.tileId;
    const openWaterTileId = nearestTileMatching(
      previousTileId,
      (tileId) => tileId !== previousTileId && isShipOpenWaterTile(tileId)
    );
    if (openWaterTileId === undefined) {
      throw new Error(`Could not recover restored ship from blocked navigation at tile ${previousTileId}`);
    }
    placeShipAtTileCenterForRecovery(openWaterTileId);
    reason = reason || "blocked rendered hull";
    recovery = nearestValidRestoredShipPlacement();
    if (!recovery) {
      throw new Error(`Restored ship remained blocked after moving to open-water tile ${openWaterTileId}`);
    }
  }

  const { x, y, candidate } = recovery;
  if (x !== 0 || y !== 0 || candidate.tileId !== ship.tileId) {
    localLayout.viewX += x;
    localLayout.viewY += y;
    ship.tileId = candidate.tileId;
    ship.position = candidate.position;
    ship.heading = normalizeTangentOrFallback(ship.heading, ship.position, WORLD_NORTH);
    ship.targetHeading = normalizeTangentOrFallback(ship.targetHeading, ship.position, ship.heading);
    ship.velocity = [0, 0, 0];
    camera = northUpCamera(ship.position, camera.right);
    centerTileId = ship.tileId;
    reason = reason || "blocked rendered hull";
  }

  if (reason) {
    console.info(
      `[pixel-globe] recovered restored ship from ${reason}; placed on tile ${ship.tileId}`
    );
  }
  if (
    !playerShipHasLocalEscape() &&
    !recoverPlayerToNearbyNavigableWater(
      "restored ship had no local escape",
      { allowGlobalFallback: true }
    )
  ) {
    throw new Error(`Could not recover restored ship from a blocked channel at tile ${ship.tileId}`);
  }
}

function nearestValidRestoredShipPlacement() {
  return findNearestShipPlacement(SHIP_RESTORE_RECOVERY_MAX_RADIUS_PX, (offsetX, offsetY) => {
    const x = localLayout.viewX + offsetX;
    const y = localLayout.viewY + offsetY;
    const collisionTile = localCollisionTileAtPoint(x, y);
    if (!collisionTile) return null;
    const position = globePositionForLocalPoint(collisionTile.tileId, x, y);
    const navigation = shipNavigabilityAtLocalPoint(x, y, collisionTile.tileId, position);
    if (!navigation.ok) return null;
    const navigationTileId = navigation.tileId;
    const navigationPosition = navigationTileId === collisionTile.tileId
      ? position
      : globePositionForLocalPoint(navigationTileId, x, y);
    const heading = normalizeTangentOrFallback(ship.heading, navigationPosition, WORLD_NORTH);
    const occupancy = vesselOccupancyAtPosition(
      navigationPosition,
      navigationTileId,
      { x, y },
      navigation,
      heading
    );
    if (!occupancy.ok) return null;
    return { tileId: navigationTileId, position: navigationPosition };
  });
}

function placeShipAtTileCenterForRecovery(tileId) {
  ship.tileId = tileId;
  ship.position = tileCenterVector(tileId);
  ship.heading = normalizeTangentOrFallback(ship.heading, ship.position, WORLD_NORTH);
  ship.targetHeading = normalizeTangentOrFallback(ship.targetHeading, ship.position, ship.heading);
  ship.velocity = [0, 0, 0];
  camera = northUpCamera(ship.position, camera?.right || [1, 0, 0]);
  centerTileId = tileId;
  localLayout = createLocalLayout(tileId);
  chart = buildChart(camera);
}

function schedulePeriodicAutosave(nowMs = performance.now()) {
  if (periodicAutosaveRequest) return;
  if (periodicAutosaveDueMs === null) periodicAutosaveDueMs = nowMs;
  const voyageState = gameState;
  const callback = (deadline) => {
    periodicAutosaveRequest = null;
    if (voyageState !== gameState || !hasStartedVoyage || gameOverReason || ship?.hitPoints <= 0) {
      periodicAutosaveDueMs = null;
      return;
    }
    const waitedMs = performance.now() - periodicAutosaveDueMs;
    const activeControl = keys.size > 0 || pointerSteering.active || controllerSteering !== null;
    const busy = activeControl || shipCombatState.engagements.size > 0 ||
      Boolean(fishingAction) || Boolean(goldTreasureSequence) || surfaceIceEntrapmentActive;
    const hasIdleBudget = deadline.didTimeout || deadline.timeRemaining() >= 4;
    if ((busy || !hasIdleBudget) && waitedMs < AUTOSAVE_MAX_IDLE_DELAY_MS) {
      queuePeriodicAutosaveCallback(callback);
      return;
    }
    periodicAutosaveDueMs = null;
    saveVoyageNow("periodic autosave");
  };
  queuePeriodicAutosaveCallback(callback);
}

function queuePeriodicAutosaveCallback(callback) {
  if (typeof window.requestIdleCallback === "function") {
    periodicAutosaveRequest = {
      kind: "idle",
      id: window.requestIdleCallback(callback, { timeout: 1000 })
    };
    return;
  }
  periodicAutosaveRequest = {
    kind: "timeout",
    id: window.setTimeout(() => callback({
      didTimeout: false,
      timeRemaining: () => 8
    }), 50)
  };
}

function cancelPeriodicAutosave() {
  if (periodicAutosaveRequest?.kind === "idle") {
    window.cancelIdleCallback(periodicAutosaveRequest.id);
  } else if (periodicAutosaveRequest?.kind === "timeout") {
    window.clearTimeout(periodicAutosaveRequest.id);
  }
  periodicAutosaveRequest = null;
  periodicAutosaveDueMs = null;
}

function saveVoyageNow(reason) {
  cancelPeriodicAutosave();
  if (CAPTURE_SCENARIO) return true;
  if (!hasStartedVoyage || !gameState || !ship || gameOverReason || ship.hitPoints <= 0) return false;
  try {
    repairLivePlayerCargoOverflow(`before save: ${reason}`);
    const ledgerCompaction = compactPlayerLedger(gameState);
    if (ledgerCompaction) {
      console.info("[pixel-globe] compacted captain ledger before saving", ledgerCompaction);
    }
    syncCartographyToGameState();
    syncAchievementsFromGameState();
    const payload = {
      gameState,
      playerShip: snapshotPlayerShip(),
      worldClock: {
        currentMinute: weatherClockMinutes,
        voyageStartMinute: voyageStartClockMinutes
      },
      firstDayNightNotices: snapshotFirstDayNightNoticeState(firstDayNightNoticeState),
      anchored,
      survivalDamageTimers: { ...survivalDeprivationTimers }
    };
    if (demoVoyageScope) payload.demoVoyageScope = demoVoyageScope;
    const snapshotErrors = [];
    addOptionalSaveSnapshot(payload, snapshotErrors, "economy", "world economy", () => (
      snapshotWorldEconomy(worldEconomy)
    ));
    addOptionalSaveSnapshot(payload, snapshotErrors, "landTrade", "land trade", () => (
      snapshotLandTradeSystem(landTradeSystem)
    ));
    addOptionalSaveSnapshot(payload, snapshotErrors, "npcRoutes", "NPC sea routes", () => (
      snapshotNpcSeaRouteSystem(npcSeaRoutes)
    ));
    const write = writeLocalSaveWithRecovery(payload);
    const save = write.save;
    localSaveResult = { status: "ready", save, error: null };
    const previousFailure = savePersistenceWarning;
    savePersistenceWarning = null;
    if (previousFailure) showSurvivalNotice("SAVE RESTORED", "good");
    if (write.mode !== LOCAL_SAVE_MODE_FULL || snapshotErrors.length > 0) {
      console.warn(
        `[pixel-globe] saved voyage in ${write.mode} mode; reconstructible world traffic will rebuild on load`,
        { snapshotErrors, attempts: write.attempts }
      );
    }
    lastLocalSaveMode = write.mode;
    if (reason === "new voyage" || reason === "continued voyage") {
      console.info(
        `[pixel-globe] local save: ${Math.ceil(write.byteLength / 1024)} KiB (${write.mode})`
      );
    }
    lastAutosaveMs = performance.now();
    return true;
  } catch (error) {
    console.warn(`[pixel-globe] local save failed (${reason})`, error);
    gameTelemetry.captureCrash(error, telemetryCrashContext("save-write"));
    lastAutosaveMs = performance.now();
    savePersistenceWarning = {
      text: "SAVE FAILED - RETRYING",
      reason,
      error
    };
    showSurvivalNotice(savePersistenceWarning.text, "warn");
    dirty = true;
    return false;
  }
}

function addOptionalSaveSnapshot(payload, errors, key, label, snapshot) {
  try {
    payload[key] = snapshot();
  } catch (error) {
    const normalized = error instanceof Error ? error : new Error(String(error));
    console.error(`[pixel-globe] could not snapshot ${label}; it will rebuild on load`, normalized);
    errors.push(Object.freeze({ key, label, error: normalized }));
  }
}

function repairLivePlayerCargoOverflow(reason) {
  const repair = repairPlayerCargoOverflow(gameState);
  if (!repair) return null;
  console.warn(`[pixel-globe] repaired live player cargo overflow (${reason})`, repair);
  syncShipCargoFromGameState();
  dirty = true;
  return repair;
}

function currentAchievementSnapshot() {
  const state = gameState && hasStartedVoyage ? gameState : null;
  const ledger = state?.accounts?.ledger || [];
  const ledgerMetrics = state ? playerLedgerLifetimeMetrics(state) : null;
  const colony = state?.memory?.colonization;
  const colonyRecord = colony?.stage === COLONIZATION_STAGE_ESTABLISHED
    ? colonizationWorldRecord(colony)
    : null;
  const foundedCityIds = colonyRecord?.playerFoundedColony
    ? [`${colonyRecord.city}|${colonyRecord.country || ""}`]
    : [];
  const soldGoodIds = ledgerMetrics?.soldGoodIds || [];
  const currentShipSlug = state ? ship?.stats?.slug || ship?.typeSlug || null : null;
  const visitedPortCount = state ? achievementVisitedPortCount(state) : 0;
  return {
    discoveryIds: state ? [...state.memory.discoveryOrder] : [],
    discoveryCatalogIds: discoveryCatalog.map((entry) => entry.id),
    animalIds: state ? [...state.memory.animals.encounterOrder] : [],
    animalCatalogIds: ANIMAL_CATALOG.map((entry) => entry.id),
    circumnavigationDiscoveryId: CIRCUMNAVIGATION_DISCOVERY.id,
    elDoradoDiscoveryId: EL_DORADO_DISCOVERY_ID,
    soldGoodIds,
    foundedCityIds,
    sailedShipSlugs: currentShipSlug ? [currentShipSlug] : [],
    shipCatalogSlugs: SHIP_STATS.map((entry) => entry.slug),
    collapsedFactionIds: state ? [...state.memory.conquest.collapsedFactionIds] : [],
    grossDoubloonsEarned: state ? grossDoubloonsEarned(state.accounts.ledger) : 0,
    vikingLongshipUnlocked: state ? vikingLongshipUnlocked(state) : false,
    whiteWhaleKilled: state?.memory?.campaignGoal?.whiteWhaleKilled === true,
    arrivedInPortDrunk: state?.memory?.achievements?.arrivedInPortDrunk === true,
    japaneseMatchlockIndustryCreated: state ? japaneseMatchlockIndustryCompleted(state) : false,
    caribbeanGingerIndustryCreated: state ? caribbeanGingerIndustryCompleted(state) : false,
    fishCaughtQuantity: ledgerMetrics?.fishCaughtQuantity || 0,
    passengerDeliveries: ledgerMetrics?.passengerDeliveries || 0,
    acquiredShips: ledgerMetrics?.acquiredShips || 0,
    shoreScavengeCompleted: state?.memory?.flags?.achievementShoreScavengeCompleted === true,
    defeatedShip: state?.memory?.flags?.achievementDefeatedShip === true,
    mappedPercent: state ? Math.floor(mappedPercentForState(state)) : 0,
    hawaiiVisited: state ? achievementHawaiiVisited(state) : false,
    pirateCaptivesBroughtHome: state?.memory?.quests?.pirateCaptive?.completedCount || 0,
    castawaysBroughtHome: state?.memory?.quests?.castaway?.completedCount || 0,
    visitedPortCount,
    capturedPortCount: state
      ? state.memory.conquest.events.filter((entry) => entry.source === "player").length
      : 0,
    namedCrewCount: state ? namedCrewMembers(state).length : 0,
    specialEquipmentCount: state
      ? Object.values(state.inventory.items).filter((quantity) => quantity === 1).length
      : 0,
    fullCrew: Boolean(
      state?.ship &&
      state.ship.crewCapacity >= 10 &&
      state.ship.crew === state.ship.crewCapacity
    ),
    campaignVictory: state?.memory?.campaignGoal?.status === CAMPAIGN_GOAL_COMPLETE
  };
}

function achievementVisitedPortCount(state) {
  return Object.values(state.memory.visitedPorts)
    .filter((memory) => Number.isInteger(memory?.visits) && memory.visits > 0)
    .length;
}

function achievementHawaiiVisited(state) {
  const hawaii = portCities.find((city) => city.city === "Hawaii Village" && city.country === "Hawaii");
  if (!hawaii) throw new Error("Hawaii Village is missing from the 1522 port catalog");
  const portId = hawaii.portId || `city-${hawaii.tileId}`;
  return (state.memory.visitedPorts[portId]?.visits || 0) > 0;
}

function syncAchievementsFromGameState(event = null) {
  if (!gameState || !achievementProfile) return [];
  const progress = gameState.memory.achievements;
  if (event) recordVoyageAchievementEvent(progress, event);
  const snapshot = currentAchievementSnapshot();
  const result = synchronizeAchievements(
    achievementProfile,
    progress,
    snapshot
  );
  if (result.changed) {
    writeAchievementProfile(achievementProfile);
    achievementProfileResult = { status: "ready", profile: achievementProfile, error: null };
    if (result.newlyUnlocked.length > 0 && hasStartedVoyage && !startMenu) {
      queueAchievementNotices(result.newlyUnlocked);
      for (const entry of result.newlyUnlocked) {
        if (BUILD_EDITION_ID === "full") {
          publishPlatformTimelineEvent({
            title: `Achievement unlocked: ${entry.title}`,
            description: entry.description,
            icon: "steam_achievement",
            priority: 650,
            durationSeconds: 0,
            clipPriority: PLATFORM_CLIP_PRIORITY.STANDARD
          });
        }
      }
    }
  }
  queueAchievementPlatformSync(steamStatValues(
    achievementProfile,
    progress,
    snapshot,
    historicalBattleRecords
  ));
  return result.newlyUnlocked;
}

function queueAchievementNotices(entries) {
  if (!Array.isArray(entries) || entries.length === 0) return false;
  if (CAPTURE_SCENARIO?.sequence?.kind === "panda") return false;
  if (entries.length >= ACHIEVEMENT_NOTICE_BATCH_THRESHOLD) {
    achievementNoticeQueue.push({
      heading: `${entries.length} ACHIEVEMENTS UNLOCKED`,
      title: "CHECK THE ACHIEVEMENT LIST",
      iconId: "menu:achievements",
      achievementId: null
    });
  } else {
    for (const entry of entries) {
      achievementNoticeQueue.push({
        heading: "ACHIEVEMENT UNLOCKED",
        title: entry.title.toUpperCase(),
        iconId: entry.iconId,
        achievementId: entry.id
      });
    }
  }
  dirty = true;
  return true;
}

function updateAchievementNotice(nowMs) {
  if (achievementNotice && nowMs < achievementNotice.expiresAtMs) return achievementNotice;
  achievementNotice = null;
  const next = achievementNoticeQueue.shift();
  if (!next) return null;
  achievementNotice = {
    ...next,
    startedAtMs: nowMs,
    expiresAtMs: nowMs + NOTICE_DURATION_MS.achievement
  };
  playAchievementDingSound();
  return achievementNotice;
}

function queueAchievementPlatformSync(statValues = null) {
  if (BUILD_EDITION_ID === "demo") return;
  if (!achievementProfile) return;
  let adapter;
  try {
    adapter = achievementPlatformAdapter(window);
  } catch (error) {
    console.error("[pixel-globe] invalid achievement platform adapter", error);
    return;
  }
  if (!adapter && !steamPlatformBridge) return;
  const platformId = adapter?.platformId || steamPlatformBridge?.platformId || "platform";
  achievementPlatformSyncPromise = achievementPlatformSyncPromise
    .then(async () => {
      if (statValues) await updatePlatformStats(steamPlatformBridge, statValues);
      if (adapter) {
        const result = await syncAchievementProfileToPlatform(achievementProfile, adapter);
        if (result.changed) writeAchievementProfile(achievementProfile);
      }
    })
    .catch((error) => {
      console.error(`[pixel-globe] ${platformId} achievement/stat sync failed`, error);
    });
}

function applyCurrentPortConquestOwnership({
  notifyForeignSettlementExpulsions = false,
  refreshMaltaQuest = true
} = {}) {
  if (!gameState?.memory?.conquest) throw new Error("Cannot apply port ownership without conquest state");
  const allCities = [...cityByTileId.values()];
  applyPortConquestOwnership(gameState.memory.conquest, allCities);
  const cityStateByTileId = new Map(allCities.map((city) => [city.tileId, city]));
  for (const city of chart?.cityCalls || []) {
    const cityState = cityStateByTileId.get(city.tileId);
    if (cityState) factionSyncCity(city, cityState);
  }
  if (npcSeaRoutes) {
    const portFactionByTileId = new Map(portCities.map((city) => [city.tileId, city.factionId]));
    applyNpcConquestOwnership(
      npcSeaRoutes,
      portFactionByTileId,
      new Set(gameState.memory.conquest.collapsedFactionIds)
    );
    for (const state of npcVisualShips.values()) {
      const strategic = npcSeaRoutes.shipById.get(state.id);
      if (strategic) state.factionId = strategic.factionId;
    }
  }
  shoreBatteryStates.clear();
  shoreBatteryUpdateAccumulator = 0;
  reconcileForeignSettlementPolitics({ notify: notifyForeignSettlementExpulsions });
  if (refreshMaltaQuest) refreshHospitallerMaltaQuestState();
  return new Map(allCities.map((city) => [city.tileId, city.factionId]));
}

function factionSyncCity(city, canonicalCity) {
  city.foundingFactionId = city.foundingFactionId || city.factionId;
  city.factionId = canonicalCity.factionId;
  city.capitalOfFactionId = canonicalCity.capitalOfFactionId || null;
  city.isFactionCapital = canonicalCity.isFactionCapital === true;
}

function snapshotPlayerShip() {
  return {
    factionId: ship.factionId,
    typeSlug: ship.typeSlug,
    position: ship.position.slice(),
    tileId: ship.tileId,
    heading: ship.heading.slice(),
    targetHeading: ship.targetHeading.slice(),
    velocity: ship.velocity.slice(),
    hitPoints: ship.hitPoints,
    maxHitPoints: ship.maxHitPoints,
    wakeSeedCounter: ship.wakeSeedCounter,
    cannonSequence: ship.cannonSequence,
    overboardCrew: snapshotOverboardCrew(overboardCrew)
  };
}

function finiteMinuteOrNull(value) {
  return Number.isFinite(value) ? value : null;
}

