function handlePoliticsKeyDown(event) {
  event.preventDefault();
  if (event.key === "p" || event.key === "P") {
    closePoliticsMenu();
    return;
  }
  if (politicsMenu.newsDetailOpen) {
    if (event.key === "Escape") closePoliticsNewsDetail();
    else if (["ArrowUp", "PageUp"].includes(event.key)) scrollPoliticsNewsDetail(-1);
    else if (["ArrowDown", "PageDown"].includes(event.key)) scrollPoliticsNewsDetail(1);
    return;
  }
  if (event.key === "Escape") {
    closePoliticsMenu();
    return;
  }
  if (["Enter", " "].includes(event.key) && openPoliticsNewsDetail()) return;
  if (["ArrowLeft", "ArrowUp", "PageUp"].includes(event.key)) {
    stepPoliticsPage(-1);
  } else if (["ArrowRight", "ArrowDown", "PageDown"].includes(event.key)) {
    stepPoliticsPage(1);
  }
}

function handleDiscoveriesKeyDown(event) {
  event.preventDefault();
  if (discoveriesMenu.detailEntryId !== null) {
    if (event.key === "Escape") closeDiscoveryDetail();
    else if (["ArrowUp", "PageUp"].includes(event.key)) scrollDiscoveryDetail(-1);
    else if (["ArrowDown", "PageDown"].includes(event.key)) scrollDiscoveryDetail(1);
    return;
  }
  if (event.key === "Escape") {
    closeDiscoveriesMenu();
    return;
  }
  if (["ArrowLeft", "ArrowRight", "Tab"].includes(event.key)) {
    switchDiscoveriesTab(discoveriesMenu.tab === "wonders" ? "animals" : "wonders");
  } else if (event.key === "ArrowUp") {
    stepDiscoveryEntrySelection(-1);
  } else if (event.key === "ArrowDown") {
    stepDiscoveryEntrySelection(1);
  } else if (["Enter", " "].includes(event.key)) {
    openSelectedDiscoveryDetail();
  } else if (event.key === "PageUp") {
    stepDiscoveriesPage(-1);
  } else if (event.key === "PageDown") {
    stepDiscoveriesPage(1);
  }
}

function handleAchievementsKeyDown(event) {
  event.preventDefault();
  if (event.key === "Escape") {
    closeAchievementsMenu();
    return;
  }
  if (["ArrowLeft", "ArrowUp", "PageUp"].includes(event.key)) {
    stepAchievementsPage(-1);
  } else if (["ArrowRight", "ArrowDown", "PageDown", "Enter", " "].includes(event.key)) {
    stepAchievementsPage(1);
  }
}

function handleAboardMenuKeyDown(event) {
  event.preventDefault();
  if (event.key === "Escape") {
    if (aboardMenu.selectedNamedId) {
      aboardMenu.selectedNamedId = null;
      aboardMenu.backButtonRect = null;
      dirty = true;
      return;
    }
    closeAboardMenu();
    return;
  }
  if (aboardMenu.selectedNamedId) return;
  if (event.key === "Enter" || event.key === " ") {
    openFocusedAboardCharacter();
    return;
  }
  if (event.key === "Home") {
    focusAboardCharacterAtIndex(0);
    return;
  }
  if (event.key === "End") {
    focusAboardCharacterAtIndex(currentAboardRoster().named.length - 1);
    return;
  }
  if (["PageUp", "PageDown"].includes(event.key)) {
    const direction = event.key === "PageDown" ? 1 : -1;
    scrollAboardMenu(direction, event.key === "PageUp" || event.key === "PageDown");
    return;
  }
  const direction = event.key === "ArrowLeft"
    ? "left"
    : event.key === "ArrowRight"
      ? "right"
      : event.key === "ArrowUp"
        ? "up"
        : event.key === "ArrowDown" ? "down" : null;
  if (direction) {
    stepAboardCharacterFocus(direction);
  }
}

function handleNavigationMenuKeyDown(event) {
  event.preventDefault();
  if (event.key === "Escape") {
    closeNavigationMenu();
    return;
  }
  if (["ArrowLeft", "PageUp"].includes(event.key)) {
    stepNavigationMenuPage(-1);
    return;
  }
  if (["ArrowRight", "PageDown"].includes(event.key)) {
    stepNavigationMenuPage(1);
    return;
  }
  const page = navigationMenuPage();
  if (["ArrowUp", "ArrowDown"].includes(event.key)) {
    const direction = event.key === "ArrowDown" ? 1 : -1;
    navigationMenu.selectedIndex = stepMenuIndex(
      navigationMenu.selectedIndex,
      direction,
      Math.max(1, page.rows.length)
    );
    dirty = true;
    return;
  }
  if (["Enter", " ", "Backspace", "Delete"].includes(event.key)) {
    removeSelectedNavigationWaypoint();
  }
}

